window.HB_TR["leviticus"]["ks"]=["1. تہٕ خداوند کٔر موسیٰ ہس بُلوو، تہٕ وونُن جماعت کِس خیمہ منزٕ أمِس سٍتـ̡ کتھ کرنہٕ،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، یێلہِ تہٕ یێلہِ تہِ یێلہِ تہٕ چاروٕنـ̡ ہُند نذرانہٕ دِیہِ۔\n3. یێلہِ تٔمۍ سٕنز نذرانہ کھورِ ہٕندِس دزمژ قربانی آسہِ، سُہ گژھہِ پننہِ مرضی سٍتـ̡ خدایہِ سٕندِس خیمہٕ کِس دروازس پیٹھ پیش کرُن۔\n4.\\tتہٕ سُہ تھاوُن دزنہٕ نذرانہ کِس کلس پیٹھ اتھہٕ۔ تہٕ أمِس خٲطرٕ ییہِ کفارہ دِنہٕ خٲطرٕ قبول کرنہٕ۔\n5. تہٕ سُہ کرِ خداوند سٕندِس برونہہ کُن بیل مارُن، تہٕ پادٕرۍ، ہارون سٕندِ نیچوۍ، خون أنِتھ تہٕ خوُن دِیُن قربان گاہس پیٹھ یُس جماعت ہٕندِس خیمہ کِس دروازس نِش چُھ۔\n6. تہٕ سُہ کرِ دزنہٕ نذرانہ تہٕ ژٔٹِتھ ژٔٹِتھ پنہٕ نِس ٹُکرس منز۔\n7. تہٕ ہارون سٕندِ نیچو دِن قربان گاہس پیٹھ نار، تہٕ لٔکر تراوُن نارس پیٹھ۔\n8.\\tتہٕ پادٕرۍ، ہارون سٕندِ نیچوۍ، لٔکرِ ہٕندِس نارس پیٹھ یُس {چُھ} چُھہ قربان گاہس پیٹھ:\n9. مگر تٔمۍ سٕندِس اندرمِس تہٕ زنگہٕ سٍتـ̡ گژھہِ سُہ آبہٕ سٍتـ̡ واش کرنہٕ۔ تہٕ پادٕرۍ دِیہِ قربان گاہس پیٹھ سارِنٕے دزنہٕ یُن، یُس نارٕ سٍتـ̡ دِنہٕ یُن نذرانہ آسہِ۔\n10.\\tتہٕ یێلہِ تٔمۍ سُند قربانی دِنہٕ آمُت آسہِ، {یعنی}، دانٛدن ہٕندِس یا ژھاوٕنـ̡ سٕندِس دَزنہٕ خٲطرٕ۔ سُہ اَنِن أمِس نَر بےٚ داغ۔\n11. تہٕ سُہ کرِ یہِ قربان گاہ کِس شمالس کُن خداوند سٕندِ برونہہ کُن مارُن، تہٕ پادٕرۍ، ہارون سٕندِ نیچوۍ، تٔمۍ سُند خوُن قربان گاہس پیٹھ چھُکُن۔\n12.\\tتہٕ سُہ ژٔٹِتھ پننِس کلہٕ تہٕ چربی سٍتـ̡ ژٔٹِھتھ تہٕ پادٕرۍ تراوِ تِم لٔکرِ لٔکرِس پیٹھ یُس {چُھ} چُھہ قربان گاہس پیٹھ:\n13.\\tمگر سُہ کرِ اندرم تہٕ زنگہٕ آبہٕ سٍتـ̡ واش کٔرِتھ، تہٕ پادٕرۍ اَنِن سارِنٕے تہٕ قربان گاہس پیٹھ زالُن: یہِ چُھہ دزنہٕ آمُت قربانی، نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ ، یُس خداوند سٕندِ خٲطرٕ مٔٹھۍ مٔزِتھ دِنہٕ آمُت چھُ۔\n14.\\tتہٕ یێلہِ یێلہِ تٔمۍ سٕنزِ نذرانہٕ خٲطرٕ دزنہٕ آمُت قربانی یێلہِ سُہ کچھوٕ یا کۅترن ہُند نذرانہ پیش کرُن۔\n15.\\tتہٕ پادٕرۍ اَنِن یہِ قربان گاہس پیٹھ، تہٕ کلہٕ ژٔٹِتھ تہٕ دِیہِ قربان گاہس پیٹھ۔ تہٕ امیک خون گژھہِ قربان گاہ کِس اندۍ پکھۍ نِنہٕ: {نِش...: یا کلہٕ ژٔٹِتھ کٔرِو}\n16.\\tتہٕ سُہ کرِ پنُن فصل پننیو پکھہٕ سٍتـ̡ تُلِتھ تہٕ ترٲوِن مشرِقس کُن قربان گاہس نِش، سوٗر ہٕنزِ جایہِ: {تٔمۍ سٕندِ پکھہٕ: یا، تٔمِچ گندگی}\n17.\\tتہٕ سُہ کرِ یہِ پَکھہٕ سٍتـ̡ ژٔٹِتھ، {مگر} کرِ نہٕ یہِ پھٔٹِتھ تہٕ پادٕرۍ زٲلِتھ دِیہِ قربان گاہس پیٹھ، لٔکرِ پٲٹھۍ، یُس {چُھ} نارس پیٹھ: یہِ {چُھ} دزنہٕ آمُت قربانی، یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یُس خداوند سٕندِ خٲطرٕ مٔدٕر ذائقہٕ چُھہ دِنہٕ آمُت۔","1. تہٕ ییلہِ کانہہ تہِ خداوند سٕندِ خٲطرٕ ماز پیش کرِ، تٔمۍ سٕنز قربانی گژھہِ عمدہ آٹ۔ تہٕ سُہ تراوِ اتھ پیٹھ تیٖل تہٕ اَتھ پیٹھ لوبان تراوُن:\n2. تہٕ سُہ اَنِن ہارون سٕندِس نیچوِس پادٕرَن نِش۔ تہٕ سُہ نِیہِ اَمہِ سٕندِ آٹُک موٚٹ تہٕ تِمن ہٕندِس تیٖلس سٍتـ̡ سٲرۍسٕے لوبان سٍتـ̡ نِنہٕ۔ تہٕ پادٕرۍ زٲلِہ اَمیُک یادگار قربان گاہس پیٹھ، {یُس} نارٕ سٍتـ̡ دِنہٕ آمُت نذرانہٕ، یُس خداوند سٕندِ خٲطرٕ میٹھُر ذائقہٕ سٍتـ̡ دِنہٕ یُن:\n3.\\tتہٕ مازٕچ باقیات آسہِ ہارون تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھہ خداوند سٕندِ نذرانہ مَنٛز سارِوٕے کھۄتہٕ مقدس چیز۔\n4. تہٕ اگر تُہۍ اوونس مَنٛز بٔنِتھ ماز ہُند نذرانہ اَنِو، تیلہٕ سٍتـ̡ رَلاونہٕ آمُت خمیر روٚس کیک یا تیلہٕ سٍتـ̡ مسح کرنہٕ آمُت خمیر روٚس کیک آسہِ۔\n5.\\tتہٕ اگر تُہٕندِس نذرَس مَنٛز ماز پیش کرنہٕ یِنہٕ آسہِ، سُہ گژھہِ نفیس آٹُک تہٕ تیٖلس سٍتـ̡ رَلاونہٕ یُن۔ {پینس منز: یا، فلیٹ پلیٹ پیٹھ، یا، سلائس}\n6.\\tژیہ ژیہ یہ ٹُکرٕ ٹُکرٕ کٔرِتھ تیٖل تراوُن: یہِ چھُ ماز نذران۔\n7. تہٕ اگر تُہٕنٛز نذرٕ {بیکِن} ماز ہٕنٛز نذرانہ آسہِ، تیلہٕ گژھِ تیٖلہٕ سٍتۍ نٔوۍ آٹہٕ بناونہٕ یُن۔\n8. تہٕ یُس ماز نِش یُس یِمو چیزو سٍتـ̡ بناونہٕ آمُت چُھ، تہٕ یێلہِ سُہ پادٕرِس نِش پیش کرنہٕ ییہِ، سُہ اَنِن قربان گاہس پیٹھ۔\n9.\\tتہٕ پادٕرۍ نِیہِ مازٕ سٍتـ̡ اکھ یادگار، تہٕ دِیہِ قربان گاہس پیٹھ: {یہ} چُھہ نارٕ سٍتـ̡ دِنہٕ آمُت، یُس خداوند سٕندِ خٲطرٕ مٔٹھہِ مٔٹھہِ ہُند ذائقہٕ چُھ۔\n10. تہٕ یُس ماز نذرانہ منز بچومُت چُھہ سُہ آسہِ ہارون سُند تہٕ تٔمۍ سٕندِس نیچوِس سُند: {یہِ} چُھ خداوند سٕندِ نذرانہٕ مَنٛز سارِوٕے کھۄتہٕ مُقدس چیز یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ۔\n11.\\tکانہہ تہِ مازُک نذرانہ یُس تۅہہ خداوند سٕندِ خٲطرٕ أنِو، یُس نہٕ خمیر سٍتـ̡ دِنہٕ یُن، تکیازِ خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ کُنہِ تہِ نذرانہ سٍتـ̡ گژھِ نہٕ خمیر تہٕ شہد زالنہٕ۔\n12.\\tگۅڈنچہ پھلن ہٕنزِ قربان کرنُک تعلق چھُ، تم گژھن یِم خداوند سٕندِ خٲطرٕ پیش کرنہٕ، مگر یِم گژھن نہٕ مٔدٕرِ مَزٕ خٲطرٕ قربان گاہس پیٹھ زالنہٕ۔ {دزنہٕ یُن: ہیب۔ کھسُن}\n13. تہٕ پننہِ مازٕچ نذرانہ ہُند پرٮ۪تھ کُنہِ نذرانہ کٔرِو نوٗنہٕ سٍتـ̡ دِنہٕ۔ تہٕ نہ گژھ ژے پننِس خدایہ سٕندِ معاہدُک نوٗنہٕ پننہِ مازٕچ نذرانہ سٍتـ̡ کم گژھُن، تہٕ پنہٕ نِس سارِنٕے نذرانہ سٍتـ̡ نوٗن پیش کرُن۔\n14. تہٕ یێلہِ ژے پَنٕنـ̡ گۅڈنِکِس پھلُک ماز نذرانہٕ پیش کٔرِو، تێلہِ کٔرِو پنہٕ نِس گۄڈنِکِس مٮ۪وٕچ نذرانہٕ خٲطرٕ، نارس سٍتـ̡ ہۄکھمٕژ مکایہِ ہٕندِس سبز کٔن، {حتیٰ کہ} مکایہٕ کٔرِتھ کٔرِتھ دِنہٕ۔\n15.\\tتہٕ تُہۍ ترٲوِو اتھ پیٹھ تیٖل تہٕ لوبان تھووُن: یہِ چُھ ماز ہُند نذران۔\n16.\\tتہٕ پادٕرۍ زٲلِن اَمہِ کِس یادگارس {حصہ} تہٕ اَمہ کِس تیلُک {حصہ}، اَمہ کِس سارِنٕے لوبان سٍتـ̡ {یہ} چُھ نارٕ سٍتـ̡ دِنہٕ آمُت نذرانہ ۔","1. تہٕ اگر تٔمۍ سُند نذر صلح ہُند قربانی آسہِ، اگر سُہ کھورِ ہُند قربانی دِیہِ۔ چاہے سُہ مرد آسہِ یا زنانہٕ، سُہ کرِ خداوند سٕندِ برونہہ کُن بے عیب پیش کرنہٕ۔\n2. تہٕ سُہ تھاوِ پنُن نذرانہ کِس کلس پیٹھ اتھہٕ، تہٕ مارُن جماعت کِس خیمہ کِس دروازس پیٹھ۔ تہٕ ہارون سٕندِ نیچوۍ پادٕرۍ کرِ اندۍ پکھۍ قربان گاہس پیٹھ خون۔\n3. تہٕ سُہ کرِ امن ہٕندِ قربانی سٍتـ̡ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ پیش کرنہٕ۔ سُہ چربی یُس اندرمس حصس پیٹھ چُھ، تہٕ سورے چربی یُس {چُھ} اندرمس حصس پیٹھ چُھ، {چربی: یا، سوئیٹ}\n4.\\tتہ دۅشوے گردہ تہ یمن پیٹھ یُس {چُھ} چھہ تہ کۅکرس پیٹھۍ کۅکرِ سیتۍ کڈنہ آمت۔ {caul...: یا، جگرس پیٹھ، تہٕ گردن پیٹھ}\n5.\\tتہٕ ہارون سٕندِ نیچوۍ زٲلِن قربان گاہس پیٹھ یُس نارس پیٹھ {چُھ} لٔکرِ پیٹھ، یُس نارس پیٹھ {چُھ} چُھہ: {یہ} چُھہ نارٕ سٍتـ̡ دِنہٕ آمُت نذرانہ ، یُس خداوند سٕندِ خٲطرٕ مٔٹھـ̡ چُھ۔\n6. تہٕ یێلہِ تٔمۍ سٕنز قربانی دِنہٕ خٲطرٕ یێلہِ خداوند سٕندِ خٲطرٕ بٔنِتھ چُھہ مرد یا زنانہٕ، سُہ کرِ یہ بے داغ پیش کرنہٕ۔\n7. یێلہِ سُہ کُنہِ کۅکرِ ہٕندِس نذرانہٕ خٲطرٕ پیش کرُن، تێلہِ گژھہِ سُہ خداوند سٕندِ برونہہ کُن پیش کرنہٕ۔\n8. تہٕ سُہ تھاوِ پنُن نذرانہ کِس کلس پیٹھ اتھہٕ، تہٕ مارِ یہِ جماعت کِس خیمہ خانس برونہہ کُن۔ تہٕ ہارون سٕندِ نیچوۍ دِیہِ قربان گاہس پیٹھ اَمہ سُند خوُن۔\n9. تہٕ سُہ کرِ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پیش کرنہٕ۔ امچ چربی {تہٕ} پورٕ رمپ، یہٕ کرٕ کمرٕ سٕتۍ سختی سان کڈنہٕ؛ تہٕ سُہ چربی یُس اندرمِس کُن چُھ، تہٕ سٲرِی چربی یُس اندرمِس کُن چُھ،\n10.\\tتہ دۅشوے گردہ تہ چربی یُس یمن پیٹھ {چُھ} تہ کۅکرس پیٹھۍ کۅکرِ تہ گردہ کڈِتھ کڈُن۔\n11. تہٕ پادٕرۍ دِیہِ یہِ قربان گاہس پیٹھ زالُن: {یہِ} چُھہ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ ہُند کھیٛن۔\n12. تہٕ اگر تٔمۍ سُند نذرانہ ژھاوُل آسہِ، تیلہِ گژھہِ سُہ خداوند سٕندِ برونہہ کُن پیش کرنہٕ۔\n13. تہٕ سُہ تھاوُن اَتھ کِس کلس پیٹھ اتھہٕ تہٕ مارُن تہٕ ہارون سٕندِ نیچو دِیہِ اندۍ پکھۍ قربان گاہس پیٹھ اَمہ سُند خوُن۔\n14.\\tتہٕ سُہ کرِ اَمہِ سٍتـ̡ پَنٕنہِ نذرانہٕ پیش کرنہٕ، یُس نارٕ سٍتـ̡ خداوند سٍتـ̡ دِنہٕ آمُت چُھ۔ سُہ چربی یُس اندرمس کُن چُھ، تہٕ سورُے چربی یُس {چُھ} اندرمس حصس منز،\n15.\\tتہٕ دۅشوے گردہ، تہٕ یُس چربی یُس {چُھ} یُس کۅکرِ سٍتـ̡ {چُھ} تہٕ کۅکرس پیٹھ، گردن سٍتـ̡ سٍتـ̡ نِنہٕ یُن۔\n16.\\tتہٕ پادٕرۍ دِیہِ تِم قربان گاہس پیٹھ زالُن: {یہ} چُھہ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ ہُند کھیٛن: سورُے چربی چُھہ خداوند سُند۔\n17. {یہِ} آسہِ تُہنزن سارِنٕے مکانن منز تُہنزن نسلن ہٕندِ خٲطرٕ اکھ دائمی قانون، یُس نہٕ چربی تہٕ نہ خون۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، یێلہِ کانہہ روح خداوند سٕندِس کُنہِ تہِ حُکمس خلاف لاعلمی سٍتـ̡ گۅناہ کرِ، یُس نہٕ کرنہٕ یُن پزِ تہٕ یِمو منزٕ کُنہِ تہِ سٍتـ̡ کرُن:\n3. یێلہِ پادٕرۍ یُس مسح کرنہٕ آمُت چُھ، سُہ چُھ لُکن ہٕندِس گۅنہٕ مُطٲبق گۅناہ کٔرِتھ۔ تیلہِ گژھہِ سُہ پنہٕ نِس گۅنہٕ سٍتـ̡ یُس تٔمِس گۅناہ کورمُت چُھ، اَکھ جوان دانٛد یُس خداوند سٕندِ خٲطرٕ گۅنہٕ نِش نِش دِنہٕ آمُت چُھ۔\n4.\\tتہٕ سُہ اَنُن گُندٕ رٔنگہِ ہٕندِس خیمہ کِس دروازس تام۔ تہٕ کرِ پنُن اتھہٕ بیل سٕندِس کلس پیٹھ، تہٕ دِیہِ مالہٕ سٕندِس برونہہ کُن مٲرِتھ۔\n5. تہٕ یُس پادٕرۍ مسح کرنہٕ آمُت چُھ، سُہ کرِ بیلُک خوُن، تہٕ اَنِن جماعت کِس خیمہ خانس مَنٛز:\n6. تہٕ پادٕرۍ کرِ پنٕنۍ اوٚنٛگجہ خونس مَنٛز، تہٕ رٔنگہِ ہٕندِس مَنٛز سَتھ لٹہِ رٔلِتھ رٔٹ\n7. تہٕ پادٕرۍ تھاوُن خداوند سٕندِس برونہہ کُن مٔدٕرِ بخور کِس قربان گاہٕ کِس سینگس پیٹھ، یُس جماعت کِس خیمہ مَنٛز {چُھ}۔ تہٕ دزنہٕ آمٕژ قربان گاہ کِس بونہٕ کِس دامنس پیٹھ تراوِ بیلُک سورُے خون، یُس جماعت کِس خیمہ کِس دروازس پیٹھ چُھ۔\n8. تہٕ سُہ کٔڈِتھ گۅنہٕ نِشہ نِشہ دِنہٕ خٲطرٕ بیلُک سورُے چربی کڈُن۔ سُہ چربی یُس اندرمس کُن چُھ، تہٕ سورُے چربی یُس {چُھ} اندرمس حصس منز،\n9.\\tتہٕ دۅشوے گردہ، تہٕ یُس چربی یُس {چُھ} چُھ، یُس کُنہِ\n10.\\tیِتھ کٔنۍ یہِ امن ہٕندِس قربان گاہٕ سٍتـ̡ تُلنہٕ آمُت: تہٕ پادٕرۍ دِیہِ تِم زالنہٕ یِنہٕ وٲلِس قربان گاہَس پیٹھ۔\n11.\\tتہٕ بیلُک کھال، تہٕ أمۍ سُند سورُے ماز، کلہٕ سٍتـ̡ تہٕ زنگہٕ سٍتـ̡ تہٕ أندرِم سٍتـ̡ تہٕ گُرِ سٍتـ̡\n12.\\tسُہ تہِ گژھِ سُہ خٲمہٕ ورٲے صاف جایہِ نِنہٕ یُن، ییتہِ سوٗر تراونہٕ یِیہ، تہٕ لٔکرِ سٍتـ̡ نار سٍتـ̡ زالنہٕ یُن۔ {بغیر...: ہیب۔ کیمپ ورٲے کُن} {کتہِ...: ہیب۔ راکھ منزہ نیرنس پیٹھ}\n13. تہٕ یێلہِ یێلہِ سارِنٕے اِسرٲیلِچ جماعت جہالت سٍتـ̡ گۅناہ کٔرِتھ، تہٕ یہِ چیز گژھہِ مجلسہٕ نِش ژوٗرِ روزُن، تہٕ یێلہِ تِمو خداوند سٕندِس حکمس مُتلِق کُنہِ تہِ حُکمن خلاف کُنہِ تہِ کٲم کٔرمٕژ آسہِ، یُس نہٕ کرنہٕ یُن، تہٕ چُھہ قصوروار۔\n14.\\tیێلہِ یێلہِ سُہ گۅناہ یُس تِمو اتھ خلاف گناہ کورمُت چُھ، تێلہِ گژھہِ جماعت گۅنہٕ خٲطرٕ اکھ جوان بیل پیش کرُن، تہٕ سُہ انِن جماعت ہٕندِس خیمہ خانس برونہہ کُن۔\n15.\\tتہٕ جمٲژ ہٕندِس بزرگس گژھن خداوند سٕندِس برونہہ کُن بیلہٕ سٕندِس کلس پیٹھ اتھہٕ تھاوُن، تہٕ دانٛد یِن خداوند سٕندِ برونہہ کُن مارنہٕ۔\n16. تہٕ یُس پادٕرۍ مسح کرنہٕ آمُت چُھ، سُہ کرِ بیلُک خوُن جماعت کِس خیمہ خانس مَنٛز:\n17.\\tتہٕ پادٕرۍ کرِ پَنٕنہِ اوٚنگجہ کُنہِ کُنہِ خونس منز، تہٕ سَتھ لٹہِ چُھکُن رٔلِتھ تہٕ رٔنگِس برونہہ کُن تہِ۔\n18.\\tتہٕ سُہ تراوِ قربان گاہ کِس سینگس پیٹھ یُس {چُھ} خداوند سٕندِس برونہہ کُن چُھ، یعنی جماعت کِس خیمہ خانس مَنٛز، تہٕ سٲرۍسٕے خوُن تراوُن زالنہٕ کِس قربان گاہٕ کِس بۄنہٕ کنہِ یُس جماعت کِس خیمہ کِس دروازس پیٹھ چُھ۔\n19. تہٕ سُہ نِش پنُن سورے چربی نِش نِن، تہٕ دِیہِ قربان گاہس پیٹھ۔\n20. تہٕ سُہ کرِ بیلس سٍتـ̡ یِتھٕ پٲٹھـ̡ گۅناہ ہٕندِ نذرانہ خٲطرٕ بیلس سٍتـ̡ کٔرِتھ، تہٕ سُہ کرِ یێمہِ سٍتـ̡ تہٕ پادٕرۍ کرِ تِمن ہُند کفارہٕ، تہٕ یِمن ہٕندِ خٲطرٕ کفارہٕ دِیہِ۔\n21.\\tتہٕ سُہ دِیہِ گۅڈنِچ بیل زٲلِتھ تہٕ زٲلِتھ زالُن: یہِ چُھ جماعت ہٕندِ خٲطرٕ گۅناہ ہُند قربانی۔\n22. یێلہِ کُنہِ حُکُمران چُھہ گۅناہ کٔرِتھ، تہٕ یێلہِ کُنہِ تہِ حُکُمن سٍتـ̡ یُس نہٕ کرنہٕ یُن، تہٕ چُھہ قصوروار سٍتـ̡ کرنہٕ آمُت۔\n23. یا اگر تٔمۍ سُند گۅناہ یتھ منز تٔمۍ گناہ کورمُت چُھ، تٔمۍ سٕندِس علمس منز ییہ تٔمۍ سٕندِس علمس منز۔ سُہ اَنُن پنُن نذرانہ ، ژھاوُن ہُند اکھ بچہ، یُس بے داغ نَرٕ آسہِ۔\n24. تہٕ سُہ تھووُن ژھاوٕل سٕندِس کلس پیٹھ اتھہٕ، تہٕ مارُن تتھ جایہِ ییتہِ تِم خداوند سٕندِ برونہہ کُن زٲلِتھ قربانی ماران چھِ: یہِ چُھ گۅناہ ہُند نذرانہ ۔\n25.\\tتہٕ پادٕرۍ نِیہِ پننہِ اونگجہِ سٍتـ̡ گۅنہٕ نذرانہٕ ہُند خوُن، تہٕ دزنہٕ نذرانہ کِس قربان گاہٕ کِس سینگس پیٹھ تھووُن تہٕ دزنہٕ نذرانہ ہٕندِس قربان گاہٕ کِس بونہٕ کِس پٲٹھـ̡ پَنُن خوُن تراوُن۔\n26.\\tتہٕ سُہ کرِ پنُن سورے چربی قربان گاہس پیٹھ، یُس امنٕچ قربانی ہٕندِس چربہٕ سٍتـ̡ زالُن، تہٕ پادٕرۍ کرِ تٔمِس خٲطرٕ کفارہٕ، تہٕ یِیہِ أمِس معافی دِنہٕ۔\n27. تہٕ یێلہِ کانہہ عام لُکھ جہالت سٍتـ̡ گۅناہ کرِ، یێلہِ سُہ خداوند سٕندِس حکمس مُتلِق {کُنہِ حدس تام} کران چُھہ یُس نہٕ کرنہٕ یُن گژھہِ تہٕ گُناہ آسہِ۔ {کانہہ تہِ: ہیب۔ کانہہ تہِ روح} {عام...: ہیب۔ زمینک لوک}\n28. یا اگر تٔمۍ سُند گۅناہ یُس تٔمۍ سُند گۅناہ کورمُت چُھ، تٔمِس سٍتـ̡ یێلہِ سُہ پَنُن نذرانہ دِنہٕ یُس تٔمِس گۅنہٕ سٍتـ̡ دِنہٕ آمُت چُھ۔\n29.\\tتہٕ سُہ تھاوِ پَنُن گۅنہٕ نذرانہ کِس کلَس پیٹھ اتھہٕ، تہٕ دزنہٕ آمٕژ نذرانہ جایہِ مارُن گۅنہٕ ہُند قربانی۔\n30.\\tتہٕ پادٕرۍ نِیہِ اَمہِ سُند خوُن پننہِ اونگجہِ سٍتـ̡ نِنہٕ، تہٕ دِیہِ سٲرٕے خوُن قربان گاہٕ کِس بٔنِس مَنٛز تراوُن۔\n31.\\tتہٕ سُہ کٔرِن اَمہ سٍتـ̡ سٲرۍسٕے چربی نِش نِنہٕ۔ تہٕ پادٕرۍ دِیہِ قربان گاہس پیٹھ زٲلِتھ خداوند سٕندِ خٲطرٕ مٔٹھۍ مَزٕ خٲطرٕ۔ تہٕ پادٕرۍ کرِ أمِس خٲطرٕ کفارہٕ، تہٕ أمِس یِیہِ معافی دِنہٕ۔\n32. تہٕ یێلہِ سُہ گۅناہ کِس نذرانہ خٲطرٕ کُنہِ کۅکرِ ہُند بچہٕ أنِتھ تہٕ سُہ کرِ أمِس کُنہِ مادٕ سٍتـ̡ بے عیب ۔\n33.\\tتہٕ سُہ کرِ پَنُن پَنُن گۅنہٕ نذرانہٕ کِس کلَس پیٹھ اتھہٕ تہٕ سُہ مارُن گۅنہٕ سٕندِس نذرانہ خٲطرٕ یَتھ جایہِ تِم زٲلِتھ نذرانہ ماران چھِ۔\n34. تہٕ پادٕرۍ نِیہِ گۅنہٕ نذرانہٕ ہُند خوُن پننہِ اونگجہِ سٍتـ̡ نِنہٕ، تہٕ دزنہٕ کِس قربان گاہٕ کِس سینگس پیٹھ تھووُن، تہٕ اَمیُک سورُے خوُن تراوُن قربان گاہ ہٕندِس دامنس پیٹھ۔\n35.\\tتہٕ سُہ کٔرِن اَمہِ سٍتـ̡ سارِوٕے چربی نِش یِتھٕ پٲٹھۍ کٔرِتھ نِنہٕ آمُت۔ تہٕ پادٕرۍ زٲلِن تِم قربان گاہس پیٹھ، یُس خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، تہٕ پادٕرۍ کرِ پننِس گۅناہُک کفارہٕ یُس تٔمِس کٔرمُت چُھ، تہٕ یہِ گژھہِ أمِس معافی دِنہٕ۔","1. تہٕ اگر کانہہ روح گناہ کرِ، تہٕ قسمچ آواز بوزان آسہِ، تہٕ گواہ آسہِ، چاہے سہ وُچھمُت یا زانان آسہِ۔ اگر نہ سہ یہ کتھ کرِ، تیلہِ گژھہِ سہ پنن بدکار برداش۔\n2. یا اگر کانہہ شخص کُنہِ ناپاک چیزس اتھہ لاگان آسہِ، چاہے سہ کُنہِ ناپاک جانور سُند لاش آسہِ، یا ناپاک چارواین ہُند لاش، یا ناپاک چیزن ہُند لاش، تہٕ اگر سُہ أمِس نِش پوشیدٕ آسہِ۔ سُہ تہِ گژھہِ ناپاک تہٕ قصوروار۔\n3.\\tیا اگر سُہ انسان سٕنزِ ناپاکی ہُند اتھہٕ لاگہِ، سُہ گژھہِ انسان نِش ناپاک کرنہٕ یُن، تہٕ سُہ گژھہِ أمِس نِش پوشیدٕ کرنہٕ۔ ییلہ تس یہ پتاہ آسہِ، تیلہِ گژھہِ سُہ قصوروار۔\n4.\\tیا اگر کانہہ شخص بد کار کرنُک یا نیکی کرنُک قَسم کٔرِتھ قَسم کٔرِتھ تہٕ تٔمِس نِش گژھہِ پوشیدٕ روزُن۔ ییلہ تس یہ پتاہ آسہِ، تیلہِ گژھہِ سہ یمن منز کُنہِ کُنہِ کُنہِ چیزس منز قصوروار۔\n5. تہٕ یێلہِ سُہ یِمو منزٕ کُنہِ کُنہِ چیزس مَنٛز قصوروار آسہِ، سُہ کرِ اقرار زِ تٔمِس چُھ اتھ {چیز} مَنٛز گۅناہ کورمُت:\n6. تہٕ سُہ کرِ پَنُن گۅناہ کُن خداوند سٕندِس نِش یُس گۅناہ کورمُت چُھ، یُس تٔمِس گۅنہٕ سٍتـ̡ گۅنہٕ کٔرِتھ چُھہ رٔژھہِ ہٕنزِ زنانہٕ، کۅکرِ ہُند بچہٕ یا ژھاوُل ہُند بچہٕ۔ تہٕ پادٕرۍ کرِ تٔمِس سٕندِس گۅنہٕ سٍتـ̡ کفارہٕ۔\n7. تہٕ یێلہِ سُہ کُنہِ کۅکرِ ہێکہِ تہِ زٕ کۅتر یُس أمِس کُنہِ اکھ گۅناہ نِش تہٕ بیٛاکھ دزنہٕ خٲطرٕ۔ {سُہ بی...: ہیب۔ تٔمۍ سُند اَتھٕ ہیکہٕ نہٕ کُنہِ کٹہٕ کِس کٲفی تام وٲتِتھ}\n8. تہٕ سُہ اَنِن تِم پادٕرِس نِش، یُس گۅڈٕ گۅنہٕ کِس نذرانہ خٲطرٕ {چُھ} پیش کرِ، تہٕ سُہ کرِ پننہِ گردنہٕ نِش کلہٕ ژٔٹِتھ، مگر یہ کرِ نہٕ الگ الگ کرنہٕ۔\n9. تہٕ سُہ چُھہ گۅنہٕ نذرانہٕ ہُند خوُن قربان گاہ ہٕندِس اندس پیٹھ چھُکُن۔ تہٕ باقٕے خوُن یِیہِ قربان گاہ ہٕندِس بونہٕ کِس پٲٹھـ̡ نِش نِنہٕ یُن: یہِ چُھہ گۅناہ ہُند نذرانہ ۔\n10.\\tتہٕ سُہ دوٚیِم دِنہٕ خٲطرٕ دِیہِ تٔمِس گۅنہٕ سٍتـ̡ کفارہٕ، یُس تٔمِس گۅنہٕ کورمُت چُھ، تہٕ سُہ ییہِ أمِس معاف۔ {طریقہٕ: یا، آرڈیننس}\n11. مگر اگر سُہ زٕ کچھو، یا زٕ کبوتر أنِتھ ہێکہِ نہٕ، تیلہِ یُس گۅنہٕ گار آسہِ سُہ گۅنہٕ کِس نذرانہٕ خٲطرٕ عمدہ آٹُک دٔہِم حصہٕ اَننہٕ۔ سُہ تراوِ نہٕ اتھ پیٹھ کانہہ تیٖل تہٕ نہ تراوِ اتھ پیٹھ لوبان تہٕ کیازِ یہِ چُھ گۅناہ ہُند نذران۔\n12. تیلہِ گژھہِ سُہ پادٕرِس نِش اَنُن، تہٕ پادٕرۍ رٔٹِتھ تہٕ زٲلِن قربان گاہس پیٹھ، یُس خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہٕ مُطٲبق دِیہِ۔\n13.\\tتہٕ پادٕرۍ کرِ تٔمِس کفارہٕ یُس تٔمِس گۅنہٕ سٍتـ̡ یُس تٔمِس کُنہِ کُنہِ گۅنہہ سٍتـ̡ چُھ کورمُت، تہٕ سُہ گژھہِ أمِس معافی دِنہٕ۔\n14. تہٕ خداوند دِژ موسیٰ سٕندِس سٍتـ̡ وَنُن،\n15. یێلہِ کانہہ روح گناہ کٔرِتھ تہٕ لاعلمی سٍتـ̡ گناہ کرِ، خداوند سٕندِس مقدس چیزن مَنٛز۔ تیلہِ اَنہِ سُہ پننہِ خطا خٲطرٕ رٔنگہِ ہٕندِس نِش رۄپہٕ رۄپہٕ سٍتـ̡ ناجائز نذرانہ خٲطرٕ:\n16. تہٕ سُہ کرِ تٔمِس مُقدس چیزس مَنٛز یُس نقصان کورمُت چُھ، تہٕ اتھ مَنٛز کرِ پوٗنژم حصہٕ شٲمِل تہٕ پادٕرِس دِیہِ۔ تہٕ پادٕرۍ کرِ تٔمِس خٲطرٕ کفارہٕ دِنہٕ، تہٕ سُہ گژھہِ أمِس معافی دِنہٕ۔\n17. تہٕ اگر کانہہ روح گناہ کرِ، تہٕ یِمو منزٕ کانہہ تہِ کٲم کرِ یُس خداوند سٕندِ حکمہٕ سٍتـ̡ منع کرنہٕ آمُت چھُ۔ یودوَے سُہ چُھہ نہٕ وُچھان، توتہِ چُھ سُہ قصوروار، تہٕ سُہ کرِ پنُن گناہ برداش۔\n18.\\tتہٕ سُہ اَنِہ کُنہِ تہِ کفارہٕ دِنہٕ۔\n19.\\tیہِ چُھہ اکھ ناجائز نذرانہٕ: تٔمۍ چُھ یٔقیٖنی طور خداوند سٕندِس خلاف گُناہ کورمُت۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. اگر کانہہ روح گناہ کرِ، تہٕ خداوند سٕندِس خلاف گناہ کٔرِتھ، تہٕ پننِس ہمساین سٍتـ̡ یُس أمِس رژھراونہٕ خٲطرٕ دِنہٕ آمُت اوس، یا رفاقتس منز، یا تشددٕ سٍتـ̡ نِنہٕ آمٕژ چیزس مَنٛز، یا پننِس ہمساین دھوکہٕ دِنہٕ آمُت۔ {رفاقتس منز: یا، معاملہٕ منز} {فیلوشپ: ہیب۔ اَتھٕ تراوُن}\n3. یا سُہ لٔبِتھ یُس رٲومُت اوس، تہٕ اتھ متعلق چھُ اپُز قسم کھیوان۔ یِمو سارِنٕے سارِنٕے مَنٛز یُس انسان کران چُھ، اَتھ مَنٛز چُھ گۅناہ کران:\n4. تیلہِ گژھہِ یہِ آسُن، کیازِ أمِس چُھ گۅناہ کورمُت، تہٕ چُھہ قصوروار، سُہ کرِ سُہ سُہ واپس یُس تٔمِس دھوکہ دِتھ نِیومُت چُھ، یا سُہ چیز یُس أمِس رژھراونہٕ خٲطرٕ دِنہٕ آمُت اوس، یا سُہ چیز یُس أمِس رژھراونہٕ خٲطرٕ دِنہٕ آمُت اوس، یا سُہ رٲوِتھ چیز یُس أمِس لٔبِتھ اوس،\n5.\\tیا سُہ سُہ یُس تٔمِس اپُز قَسم کٔرِتھ چھُ۔ سُہ کرِ یہ پرنسپلس منز تہِ بحال، تہٕ اتھ منز کرِ پونژم حصہٕ تہِ شٲمل، {تہٕ} دِیہِ تٔمِس یٔمِس سٍتـ̡ یہ تٔمِس دِنہٕ آمُت آسہِ، تٔمۍ سٕندِس خلاف ورزی ہٕندِس دۅہس منز۔ {دۅہہ...: یا، تمہ دۅہہ ییلہ تس قصوروار قرار دِنہٕ آو: ہیب۔ تٔمۍ سٕنٛدس خلاف ورزی کس دۄہس منٛز}\n6. تہٕ سُہ کرِ پَنُن گناہ نذرانہٕ خداوند سٕندِس نِش، یُس رٔژھہِ منزٕ بے داغ روٚس کٔرِتھ، تہٕ تُہٕندِس اندازس سٍتـ̡ کُنہِ\n7. تہٕ پادٕرۍ کرِ خداوند سٕندِ برونہہ کُن أمِس کفارہٕ، تہٕ یُس تٔمِس کُنہِ تہِ کُنہِ تہِ کُنہِ چیزس مَنٛز یُس تٔمِس خلاف ورزی کٔرمٕژ آسہِ۔\n8. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ وَنُن،\n9.\\tہارون تہٕ تٔمۍ سٕندِس نیچوِس دِیُن حُکُم دِیُن، یہِ چُھہ دزنہٕ آمُت نذرانہ ہُند قانون: یہِ چُھہ سٲرۍسٕے رٲژ قربان گاہَس پیٹھ دزنہٕ یِنہٕ سٍتـ̡ صُبحَس تام دزنہٕ یِنہٕ سٍتـ̡ تہٕ قربان گاہُک نار گژھہِ اَتھ مَنٛز دزان۔ {کیازِ...: یا، دزنہٕ خٲطرٕ}\n10. تہٕ پادٕرۍ لاگُن پنُن کُن پوش، تہٕ سُہ لٲگِن پننِس مازس پیٹھ، تہٕ سُہ سوٗر تُلُن یُس نارن قربان گاہس پیٹھ دزنہٕ آمُت چھُ، تہٕ سُہ تھاوِ قربان گاہس نِش۔\n11. تہٕ سُہ ترٲوِن پَنٕنہِ پَلَو تہٕ باقٕے پَلَو لاگُن، تہٕ سوٗر نِیہِ خٲمہٕ ورٲے صاف جایہِ تام۔\n12. تہٕ قربان گاہس پیٹھ نار گژھہِ اتھ منز دزان۔ یہِ گژھِ نہٕ ژھیوراونہٕ یُن: تہٕ پادٕرۍ کرِ پرٮ۪تھ صُبحٲے اَتھ پٮ۪ٹھ لٔکٕر زالُن، تہٕ دِیہِ اتھ پٮ۪ٹھ دزنہٕ نذرانہ ترتیبہٕ۔ تہٕ سُہ زالِ اَتھ پیٹھ امن ہٕندِ نذرانہ ہُند چربی زالُن۔\n13. نار گژھہِ ہمیشہ قربان گاہس پیٹھ دزان۔ یہ گژھہِ نہ زانہہ نیبر۔\n14. تہٕ یہِ چُھہ مازٕچ قربانی ہُند قانون: ہارون سٕندِ نیچو کرِ یہِ خداوند سٕندِس برونہہ کُن، قربان گاہَس برونہہ کُن۔\n15.\\tتہٕ سُہ نِیہِ اَتھ مَنٛز پنُن موٚٹ، مازٕچ نذرانہ ہُند آٹ، تہٕ اَمہِ کِس تیٖلُک، تہٕ سٲرِی لوبان یُس ماز کِس نذرس پیٹھ چُھ، تہٕ دِیہِ قربان گاہس پیٹھ {یُس} مٔٹھُر ذائقہٕ خٲطرٕ، {حتیٰ کہ} اَمیُک یادگار، خداوند سٕندِ خٲطرٕ۔\n16. تہٕ باقی حصہٕ گژھن ہارون تہٕ تٔمۍ سٕندِس نیچوۍ کھٮ۪ن: خمیرٕ روٚس روٹی سٍتـ̡ یِن مقدس مقامس مَنٛز کھٮ۪نہٕ۔ جماعت کِس خیمہ کِس دربارس مَنٛز گژھن تِم کھٮ۪ن۔\n17. یہ گژھِ نہٕ خمیر سٍتۍ بیک کرنہٕ یُن۔ مے چُھ یہٕ تِمن دِژمُت پننین نذرانن ہُند حصہٕ نارٕ سٍتـ̡ دِنہٕ آمُت۔ یہِ {چُھ} سارِوٕے کھۄتہٕ زیادٕ مُقدس، یِتھٕ پٲٹھـ̡ {چُھ} گۅناہ ہُند نذرانہٕ، تہٕ ناجائز نذرانہٕ پٲٹھۍ۔\n18.\\tہارون سٕندِس اولادس مَنٛز سارِنٕے نَر کھٮ۪ن۔ {یہِ} آسہِ تُہنزن نسلن مَنٛز ہمیشہٕ خٲطرٕ اکھ قانون یُس خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، سُہ گژھہِ مقدس روزُن۔\n19. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن\n20. یہِ چُھ ہارون تہٕ تٔمۍ سٕندِس نیچوٮ۪ن ہُند نذرانہ یُس تِم خداوند سٕندِس دۅہٕ مسح کرنہٕ یِنہٕ سٍتـ̡ پیش کرٕنـ̡ ۔ مازُک دٔہِم حصہٕ چُھ مازٕچ نذرانہ خٲطرٕ دٔہِم حصہٕ، امیُک نصف حصہٕ صبحٲے تہٕ نصف رٲژ۔\n21.\\tپانس منز گژھہِ یہ تیٖلہٕ سٍتۍ بناونہٕ یُن۔ {تہٕ ییلہ یہ} بیک گژھِ، تہٕ ژے اَنُن: {تہٕ} مازٕچ نذرانہ ہٕندۍ بٔنِتھ ٹُکرٕ تہٕ ژے کٔرِو خداوند سٕندِ خٲطرٕ مٔٹھۍ مَزٕ پیش کرنہٕ۔\n22. تہٕ یُس تٔمۍ سٕندِس نیچوِس سٍتـ̡ مسح کرنہٕ آمُت چُھ، سُہ کرِ یہِ خدایہِ سٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون۔ یہ گژھہِ پوٗرٕ پٲٹھۍ زالنہٕ۔\n23. پادٕرۍ سٕندِ خٲطرٕ گژھِ پرٮ۪تھ کانہہ ماز دِنہٕ یُن: سُہ گژھِ نہٕ کھٮ۪نہٕ یُن۔\n24. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n25.\\tہارون تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ کتھ کرٕن، یہِ چُھہ گۅنہٕ نذرانہٕ ہُند قانون: یێلہِ یێلہِ دزنہٕ یِنہٕ واجنہِ نذرانہ یێلہِ سٍتـ̡ گۅنہٕ ہُند قربانی ییہِ خداوند سٕندِس برونہہ کُن مارنہٕ یُن: یہِ چُھ سارِوٕے کھۄتہٕ زیادٕ پاک۔\n26. یُس پادٕرۍ یہِ گۅنہٕ خٲطرٕ پیش کرِ، سُہ گژھِ یہِ کھٮ۪نہٕ یُن، یُس مُقدس مقامس مَنٛز، جماعت کِس خیمہ کِس دربارس مَنٛز۔\n27.\\tیُس تہِ امہِ کِس مازس سٍتـ̡ لگہِ سُہ گژھہِ پاک تہٕ ییلہ کُنہِ تہِ پلوس پیٹھ اَمہِ سُند خوُن چھُکاونہٕ ییہِ، تیلہِ گژھہِ یُس اتھ مُقدس مقامس پیٹھ چھُکاونہٕ آمُت آسہِ۔\n28.\\tمگر یُس میژِ بانہٕ یتھ منز یہ بٔرِتھ آسہِ، سُہ گژھہِ پھُٹُن: تہٕ اگر یہ کُنہِ برنس منز رٔلِتھ آسہِ، سُہ گژھہِ صاف کرنہٕ یُن تہٕ آبہٕ سٍتۍ چھلنہٕ یُن۔\n29.\\tپادٕرین مَنٛز سارِنٕے مرد گژھن اَمہ سٍتـ̡ کھٮ۪ن: یہِ چُھ سارِوٕے کھۄتہٕ مقدس ۔\n30. تہٕ کانہہ تہِ گۅناہ نذرانہ یُس حضرت کِس خیمہ خانس مَنٛز {withal} صلح کرنہٕ خٲطرٕ ییہِ نہٕ کھٮ۪نہٕ، سُہ گژھہِ نارس مَنٛز زالنہٕ۔","1.\\tیتھے پاٹھۍ چھہ یہ {چھہ} ناجائز قربانی ہند قانون: یہ {چھہ} مقدس ترین چیز۔\n2.\\tیَتھ جایہِ تِم دزنہٕ نذرانہ ماران چھِ، تَمہِ سٍتـ̡ گژھن تِمن ہُند خوُن قربان گاہس پیٹھ چھُکُن۔\n3. تہٕ سُہ کرِ اَمہ سٍتـ̡ سارِوٕے چربی دِنہٕ۔ مٔرِتھ، تہٕ چربی یُس اندرمِس کُن ؤلِتھ چُھ،\n4.\\tدۅشوے گردہ تہ یُس چربی یُس {چُھ} یُس کۅکرس پیٹھ {چُھ} تہ کۅکرس پیٹھ، گردہ سٍتۍ، سہ کڈُن کڈُن:\n5. تہٕ پادٕرۍ زٲلِن یِم قربان گاہس پیٹھ زالنہٕ یُس خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت چھُ، یہِ چُھ {ناجائز قربانی}۔\n6.\\tپادٕرین مَنٛز گژھِ پرٮ۪تھ کانہہ مرد اَمہ سٍتـ̡ کھٮ۪نہٕ یُن: سُہ گژھہِ مقدس مقامس مَنٛز کھٮ۪نہٕ یُن: یہِ چُھ سارِوٕے کھۄتہٕ مقدس مقام۔\n7.\\tیِتھے پٲٹھـ̡ گۅنہٕ نذرانہٕ {چُھ}، تِتھے پٲٹھـ̡ چُھہ {چُھ} گۅناہ نذرانہٕ: {چُھ} تِمن خٲطرٕ اکھ قانون: یُس پادٕرۍ یُس اتھ سٍتـ̡ کفارہ دِیہ، سُہ گژھہِ {یہ}۔\n8. تہٕ یُس پادٕرۍ کٲنٛسہِ شخصہٕ سٕنز دزنہٕ نذرانہ پیش کرِ، سُہ تہِ آسہِ پادٕرۍ سٕندِس پانس سٍتـ̡ دزنہٕ آمٕژ نذرانہ ہُند کھال یُس تٔمِس دِژمُت آسہِ۔\n9. تہٕ سٲرِی ماز یُس تنورس مَنٛز بَننہٕ چُھ، تہٕ یُس سارِوٕے ماز چُھہ تُلنہٕ یِوان، تہٕ تُلِس مَنٛز یُس سارِوٕے پٲٹھـ̡ دِنہٕ چُھ، سُہ گژھِ پادٕرۍ سُند یُس پیش کرُن۔ {پینس منز: یا، فلیٹ پلیٹ پیٹھ یا، سلائس}\n10.\\tتہٕ ہارون سٕندِس سارِنٕے نیٚچوِس آسہِ یُس تیٖلس سٍتـ̡ رلاونہٕ یِنہٕ سٍتـ̡ تہٕ خشک آسہِ۔\n11. تہٕ یہِ چُھ امن نذرانہٕ ہُند قانون یُس سُہ خداوند سٕندِ خٲطرٕ پیش کرِ۔\n12. اگر سُہ شُکریہ ادا کرنہٕ خٲطرٕ پیش کرِ، تیلہٕ کرِ سُہ شُکرگزاری سٍتـ̡ تیٖلس سٍتـ̡ رٔلِتھ خمیر روٚس کیک تہٕ تیٖلہٕ سٍتـ̡ تٔلِتھ تٔلِتھ کیک تہٕ تیٖلس سٍتـ̡ رٔلِتھ تٔلِتھ کیک پیش کرُن۔\n13.\\tکیک علاوٕ کرِ سُہ پننہِ خمیر روٹی پیش کرنہٕ سٍتـ̡ پننہِ امن ہٕندِس نذرانہ سٍتـ̡ قربانی۔\n14.\\tتہٕ اَمہ منزٕ کرِ سُہ سارِوٕے نذرانہٕ منزٕ اَکھ نذرانہٕ یُس خداوند سٕندِ خٲطرٕ اکھ نذرانہ پیش کرُن، {تہٕ} سُہ گژھہِ پادٕرۍ سُند یُس امن ہٕندِس نذرانہٕ ہُند خوُن چھُکُن دِیہِ۔\n15.\\tتہٕ شُکرگزاری خٲطرٕ تٔمۍ سٕنزِ امن ہٕنزِ قربانی ہُند ماز یِیہِ تَمی دۅہہ کھٮ۪نہٕ یُن۔ سُہ تراوِ نہٕ صبحس تام اتھ منز کانہہ تہِ۔\n16.\\tمگر یێلہِ تٔمۍ سٕنزِ قربانی ہُند نذر یا رضاکارانہٕ قربانی آسہِ، سُہ گژھہِ تمہِ دۅہہ کھٮ۪نہٕ یُن، تہٕ پگہہ تہِ ییہ باقی حصہ کھٮ۪نہٕ۔\n17.\\tمگر تریمہِ دۅہہ گژھہِ قربانی ہند باقی ماز نار سٍتـ̡ زالنہٕ۔\n18.\\tتہٕ یێلہِ یێلہِ تٔمہِ سٕندِس امن ہٕندِس نذرانہ سٍتـ̡ کانہہ تہِ ماز کھٮ۪نہٕ ییہِ، سُہ گژھہِ نہٕ قبول کرنہٕ یُن، تہٕ یُس اتھ نذرانہ دِنہٕ وٲلِس سٍتـ̡ ییہِ واجب کرنہٕ، تہٕ یُس روح یُس اتھ منز کھٮ۪وان آسہِ، سُہ گژھہِ تٔمِس بدکار سٍتـ̡ دِنہٕ۔\n19.\\tتہٕ یُس ماز کُنہِ تہِ ناپاک چیزس اتھہِ لاگہِ سُہ گژھہِ نہٕ کھٮ۪نہٕ۔ یہِ گژھہِ نارٕ سٍتـ̡ زالنہٕ: تہٕ یێلہِ ماز سٍتـ̡ یُس پاک آسہِ، سُہ گژھہِ اَمہ سٍتـ̡ کھٮ۪نہٕ۔\n20.\\tمگر یُس روح یُس امن ہٕندِ قربانی ہُند ماز کھٮ۪وان چُھ، یُس خداوند سُند ماز آسہِ، سُہ روح تہِ گژھہِ پننین لوکن نِش ژٹنہٕ۔\n21. سُہ روح یُس کُنہِ تہِ ناپاک چیزس اتھہٕ لاگہِ، یُس انسان سٕنز ناپاک یا کُنہِ تہِ ناپاک جانور، یا کُنہِ تہِ ناپاک چیزس سٍتـ̡ چُھہ اتھہٕ لاگُن، تہٕ یُس خداوند سٕندِس سٍتـ̡ چُھہ سُہ روح تہِ ژٹنہٕ یُن۔\n22. تہٕ خداوند کٔر موسیٰ سٕنز کتھ ،\n23.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کٔرِو زِ تم گژھ نہٕ چربہٕ، داند یا کۅکرِ تہٕ ژھاوٕل کھٮ۪نہٕ۔\n24.\\tیُس جانور سُند چربی یُس پانس سٍتـ̡ مران چُھ، تہٕ یُس درندٕ سٍتـ̡ ژٹنہٕ آمُت چُھ، سُہ گژھہِ کُنہِ تہِ استعمالس منز استعمال کرنہٕ یُن، مگر یێلہِ تہِ گژھِو نہٕ یێلہِ تہِ کھٮ۪نہٕ یُن۔ {جانور...: ہیب۔ کارکیس}\n25. یُس تہِ جانور سُند چربی کھٮ۪وان چُھ، یُس انسان خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ نذرانہ پیش کران چُھ، سُہ تہِ گژھہِ پننہِ لوکـ̡ نِش ژٹنہٕ۔\n26.\\tامہِ علاوہ گژھہِ نہ کُنہِ تہِ مکانس منز کُنہِ تہِ خوُن کھیوٚن، چاہے سہ جاناوار آسہِ یا جانور سُند۔\n27.\\tیُس تہِ روح کُنہِ تہِ قٕسمُک خون کھٮ۪یہ، سُہ روح تہِ گژھہِ پننین لوکن نِش ژٹنہٕ۔\n28. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n29.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ یُس خداوند سٕندِ خٲطرٕ پنٕنـ̡ امن ہٕنزِ قربانی پیش کرِ، سُہ کرِ خداوند سٕندِس سٍتـ̡ پنٕنـ̡ امن ہٕنزِ قربانی ہُند قربانی دِنہٕ۔\n30.\\tتٔمۍ سٕندِ اتھہٕ سٍتـ̡ یُس خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، سُہ یُس سُہ اَننہٕ یُن، یێلہِ سٍتـ̡\n31. تہٕ پادٕرۍ دِیہِ قربان گاہس پیٹھ چربی زالُن، مگر سین گژھہِ ہارون سُند تہٕ تٔمۍ سٕندِس نیچوِس سُند۔\n32. تہٕ دٔچھُن پھیُر دِیُن پادٕرِس پنہٕ نِس امن ہٕندِس نذرانہٕ ہٕندِس قۄربٲنی ہٕندِس نذرانہ سٍتـ̡ دِنہٕ۔\n33.\\tیُس ہارون سٕندِس نیچوِس مَنٛز یُس امن ہُند خوُن تہٕ چربی پیش کرِ، تٔمِس آسہِ دٔچھُن پھیُر دِنہٕ۔\n34.\\tلہرِ ہٕندِس سینہٕ تہٕ کھورِ ہٕندِ خٲطرٕ چُھہ مے بنی اسرٲیلِس سٍتـ̡ تِمن ہٕندِس صلح کِس نذریہٕ نِش نِمُت، تہٕ چُھس یِم اسرٲیلِس کِس اولادس مَنٛز ہمیشہٕ خٲطرٕ أکِس حکمہٕ سٍتـ̡ ہارون تہٕ تٔمۍ سٕندِس نیٚچوِس دِژمُت۔\n35. یہِ چُھ ہارون سٕندِ مسح کرنُک تہٕ تٔمۍ سٕندِس نیچوِس مسح کرنُک حصہٕ، یُس خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہٕ سٍتـ̡ دِنہٕ آمُت چُھ، ییمہِ دۅہہٕ سٍتـ̡ سُہ پادٕرۍ سٕندِس دفترس مَنٛز خداوند سٕندِس خدمتہٕ خٲطرٕ پیش کرنہٕ آو۔\n36. یُس خداوند دِیُت تِمن بنی اسرٲیلِس دِنُک حُکُم دِیُت، ییمہِ دۅہہٕ تٔمۍ تِمن مسح کٔرِ، تِمن ہٕندِس نسلس سٍتـ̡ ہمیشہٕ خٲطرٕ اکھ قانون دِنہٕ۔\n37.\\tیہِ چُھہ زالنہٕ نذرانہٕ ہُند، ماز ہُند نذرانہ تہٕ گۅنہٕ نذرانہٕ ہُند تہٕ ناجائز قربانی ہُند تہٕ امن نذرانہ ہُند شریع۔\n38.\\tیُس خداوند موسیٰ ہس سینا کِس بیابانس مَنٛز حُکُم دِیُت، ییمہِ دۅہہٕ تٔمۍ بنی اسرٲیلِس حُکُم دِیُت زِ تِم کٔرِن سینا کِس بیابانس مَنٛز خداوند سٕندِ خٲطرٕ پنٕنۍ نذرٕ پیش کرنُک حُکُم۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. ہارون تہٕ تٔمۍ سٕندِس نیچوِس پانس سٍتـ̡ نِیُن، تہٕ پوشہٕ تہٕ مسح کرنُک تیٖل تہٕ گۅنہٕ نِشہِ نِنہٕ خٲطرٕ اکھ بیل تہٕ زٕ کۅکرِ تہٕ خمیر روٚس روٹی ہُند اکھ ٹوٗکرِ۔\n3. تہٕ کٔرِو سارِنٕے جماعت ہٕندِس خیمہ کِس دروازس تام جمع کرنہٕ۔\n4. تہٕ موسىٰ کٔر خداوند سُند حُکُم یُس أمِس حکم دِیُت۔ تہٕ مجلس آیہ جماعت کِس خیمہ کِس دروازس تام جمع کرنہٕ۔\n5. تہٕ موسىٰ ہن ووٚن جماعتس سٍتـ̡ یہِ {سُہ} سُہ چیز یُس خداوند دِیُت حُکُم دِیُت۔\n6. تہٕ موسیٰ أنۍ ہارون تہٕ تٔمۍ سٕنٛدِ نیچوۍ، تہٕ کوٚرُن آبہٕ سٍتـ̡ واش۔\n7. تہٕ تٔمۍ لٲگِن أمِس کوٹ، تہٕ لوٚگُن أمِس پَلَو، تہٕ لوٚگُن أمِس ایفوڈُک عجیب لٔگِتھ تہٕ لوٚگُن أمِس سٍتـ̡ اَتھ سٍتـ̡ گٔنڈِتھ۔\n8.\\tتہٕ تٔمۍ تھووُن سینہٕ پٲٹھۍ، تہٕ تھووُن سینس منز اُریم تہٕ تھمِم۔\n9. تہٕ تٔمۍ تھوو پننس کلس پیٹھ۔ امہ علاوٕ تھوو تٔمۍ سٕندِس برونٛہہ کُن سۄنہٕ تھالہٕ، مقدس تاج۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n10.\\tتہٕ موسىٰ رٔٹِتھ مسح کرنُک تیٖل تہٕ کٔرٕن خیمہ تہٕ اَتھ مَنٛز موجود سورُے مسح تہٕ کوٚرُن تِم پاکس۔\n11. تہٕ تٔمۍ کٔرٕن قربان گاہس پیٹھ سَتھ لٹہِ چھُکُن، تہٕ قربان گاہ تہٕ پننین سارِنٕے بانن، لاور تہٕ کھۅر دۅشوے مسح کٔرِتھ تِمن پاک کرنہٕ خٲطرٕ۔\n12. تہٕ تٔمۍ تروو ہارون سٕندِس کلس پیٹھ مسح کرنُک تیٖل تہٕ کوٚرُن أمِس پاک کرنہٕ خٲطرٕ مسح کرنہٕ۔\n13. تہٕ موسیٰ أنۍ ہارون سٕندِ نیچوۍ، تہٕ لوگُن کوٹ تہٕ لٔگِتھ تہٕ لٔگِتھ لٔگِتھ تہٕ لٔگِن ٹوپۍ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔ {پُٹ بونٹ: ہیب۔ باؤنڈ بونٹ}\n14. تہٕ تٔمۍ اوٚن گۅنہٕ نِشہِ نذرانہ خٲطرٕ بیل تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچویو تھووُن گۅنہٕ ہٕندِس کلہٕ پیٹھ۔\n15. تہٕ تٔمۍ مارُن {یہ}۔ تہٕ موسیٰ ہن روٚٹ خون، تہٕ تھووُن قربان گاہ کِس سینگس پیٹھ پننہ اونگجہِ سٍتـ̡ تہٕ قربان گاہ پاک کٔرِتھ ترووُن قربان گاہ ہٕندِس دامنس مَنٛز خون، تہٕ کوٚرُن اتھ پیٹھ صلح کرنہٕ خٲطرٕ پاکیزہ۔\n16.\\tتہٕ تٔمۍ نِش سورُے چربی یُس اندرمس کُن اوس، تہٕ کۅکرِ تہٕ دۅن گردن تہٕ تِہُند چربی تہٕ موسیٰ دِژ قربان گاہس پیٹھ۔\n17.\\tمگر بیل، تہٕ أمۍ سُند کھالہٕ، أمۍ سُند ماز تہٕ گُر، سُہ دزُن کیمپٕ ورٲے نارٕ سٍتـ̡ دزان۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n18. تہٕ تٔمۍ اوٚن زالنہٕ خٲطرٕ مینڈٕ، تہٕ ہارون تہٕ تٔمۍ سٕنٛدیو نیچویو تھوو کلہٕ سٕندِس کلس پیٹھ اتھہٕ۔\n19. تہٕ تٔمۍ مٲرِتھ {یہ}۔ تہٕ موسیٰ کٔر اندۍ پکھۍ قربان گاہس پیٹھ خون۔\n20.\\tتہٕ تٔمۍ ژٔٹِتھ کٔرِتھ کٔرِتھ رٔٹِتھ تہٕ موسیٰ دِژ کلہٕ تہٕ ٹُکرٕ تہٕ چربی زٲلِتھ۔\n21.\\tتہٕ تٔمۍ کٔر أنٛدرِم تہٕ زنگہٕ آبہٕ سٍتـ̡ واش کٔرِتھ۔ تہٕ موسىٰ دِژ سورُے میٹھہٕ قربان گاہس پیٹھ زٲلِتھ: یہِ اوس مٔٹھۍ مَزٕ خٲطرٕ دزنہٕ آمُت قربانی، {تہٕ} آلہٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ یُس خداوند سٕندِ خٲطرٕ دِنہٕ آمُت اوس۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n22.\\tتہٕ تٔمۍ اوٚن بیاکھ رام یُس مقدس رژھرُن تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچویو تھووُن کلہٕ سٕندِس کلس پیٹھ اتھہٕ۔\n23.\\tتہٕ تٔمۍ مارُن {یہ}۔ تہٕ موسیٰ کٔر اَمہِ سُند خون، تہٕ تھووُن ہارون سٕندِس دٔچھنِس کَنس پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ ہٕندِس کھورِ پیٹھ۔\n24. تہٕ اوٚن ہارون سٕندِ نیچوۍ، تہٕ موسىٰ ترووُن تہندِس دٔچھنِس کنس پیٹھ، تہٕ دچھنہِ اتھن ہٕندِس انگوٹھس پیٹھ، تہٕ دٔچھنِس کھورِ پیٹھ، تہٕ موسیٰ دِژ خوُن اندۍ پکھۍ قربان گاہس پیٹھ۔\n25.\\tتہٕ تٔمۍ کٔر چربی تہٕ سٲرۍسٕے چربی یُس اندرمس کُن اوس، تہٕ کُل {ہیرِ} کرٛیٚہنہٕ، تہٕ زٕ گردہٕ، تہٕ تِہُند چربی تہٕ دٔچھُن پھیُر:\n26. تہٕ یُس خداوند سٕندِ برونہہ کُن اوس، تٔمۍ کٔر اَکھ خمیرٕ روٚس کیک تہٕ تیٖلہٕ دار روٹی تہٕ اکھ ویفر تہٕ تھووُن چربی تہٕ دٔچھنِس پھیکس پیٹھ۔\n27. تہٕ تٔمۍ تھووُن سارِوٕے ہارون سٕندِس اتھس پیٹھ، تہٕ پننین نیچوین ہٕندِس اتھن پیٹھ، تہٕ لَہرٲوِن خداوند سٕندِ برونہہ کُن اکھ لہر پیش کرنہٕ خٲطرٕ۔\n28.\\tتہٕ موسىٰ کٔر تِم تِہٕندِس اَتھٕ نِش تہٕ زٲلِتھ دِژٕنٕچ قربان گاہس پیٹھ: تِم ٲسۍ مٔٹھۍ مَزٕ خٲطرٕ مقدس کرنہٕ آمٕتۍ: یہِ چُھ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت نذران۔\n29.\\tتہٕ موسىٰ رٔٹِتھ لَہرٲوِتھ خداوند سٕندِس برونہہ کُن لَہراونہٕ آمُت: {تکیازِ} تِکیازِ یہِ اوس موسیٰ سُند حصہٕ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n30. تہٕ موسیٰ کٔر مسح کِس تیٖلہٕ سٍتـ̡ تہٕ یُس خوُن قربان گاہس پیٹھ اوس، تہٕ ہارونس پیٹھ، تہٕ پننین نیچوین پیٹھ، تہٕ پننین نیچوین ہٕندِس پلوس پیٹھ۔ تہٕ ہارون کٔرٕن تٔمۍ سٕندِس پلوس تہٕ نیچوۍ تہٕ نیچوین ہٕندِ پلو پانس سٍتـ̡ پاک۔\n31. تہٕ موسىٰ ووٚن ہارون تہٕ تٔمۍ سٕندِس نیچوِس تہٕ یُس ماز رٔٹِتھ رٔٹِتھ تہٕ یُس میہ حُکُم دِیُتمُت چھُ، یُس میہ حُکُم دِیُتمُت چھُ، ہارون تہٕ تٔمۍ سٕندِس نیچوِس کھٮ۪ن۔\n32. تہٕ یُس ماز تہٕ روٹی ہُند باقٕے روزان چُھ، سُہ گژھ نارٕ سٍتـ̡ زالنہٕ۔\n33.\\tتہٕ تُہۍ گژھِو نہٕ سَتن دۅہن جماعت ہٕندِس خیمہ کِس دروازٕ منزٕ نیبر نیرِتھ، یوتام نہٕ تُہٕندِ تقدیسُک دۅہ ختم گژھن: سَتن دۅہن کرِ سُہ تۅہہِ مقدس کرنہٕ۔\n34. یِتھٕ پٲٹھـ̡ چُھ تٔمۍ از دۅہہٕ کورمُت، یێلہِ چُھہ خداوند چُھہ تُہٕندِ خٲطرٕ کفارہ دِنُک حُکُم دِژمُت۔\n35. تێمہِ کِنۍ روزِو تُہۍ سَتھ دۅہہٕ تہٕ رٲژ جماعت کِس خیمہ کِس دروازس پیٹھ روزُن، تہٕ خداوند سُند حکم تھاوُن، یێلہِ نہٕ مٔرِو، یێلہِ چُھہ مے حُکُم دِنہٕ آمُت۔\n36. یِتھٕ پٲٹھۍ کٔر ہارون تہٕ تٔمۍ سٕندِس نیچویو سٲرۍسٕے چیٖز یُس خداوند موسیٰ سٕندِ اتھہٕ سٍتـ̡ حُکُم دِیُتمُت اوس۔","1. تہٕ یہ سپد ٲٹھمہِ دۅہ، {یُس} موسىٰ ہن ہارون تہٕ تٔمۍ سٕندِس نیچوِس تہٕ اسرٲیلِکۍ بزرگن بُلوو۔\n2. تہٕ تٔمۍ ووٚن ہارونس زِ ژے نِش گۅنہٕ خٲطرٕ اکھ بَچھرٕ تہٕ نِیُن اکھ بَچھرٕ تہٕ نِش نِش زالنہٕ خٲطرٕ اکھ مینڈٕ، تہٕ رٔلِس برونہہ کُن پیش کٔرِو۔\n3.\\tتہٕ بنی اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ تہٕ وَنُن زِ تێلہِ رٔٹِو ژھاوُن ہُند اکھ بچہٕ گۅنہٕ نِشہ نِشہ نِنہٕ۔ تہٕ اکھ بَچھرٕ تہٕ اکھ کۅکر، {دۅنوے} گۅڈنچہ ؤریس منز، بے داغ، دزنہٕ خٲطرٕ۔\n4.\\tخداہس برونہہ کُن قربانی دِنہٕ خٲطرٕ اکھ بیل تہٕ اکھ مینڈ۔ تہٕ تیلَس سٍتـ̡ رلاونہٕ آمُت مازُک نذرانہ تہٕ تِکیازِ از چُھہ خداوند تۅہہِ برونہہ کُن ظٲہر سپدِ۔\n5. تہٕ تِمو أنۍ سُہ یُس موسىٰ ہن جماعت ہٕندِس خیمہ برونہہ کُن حُکُم دِیُتمُت اوس، تہٕ سارِوٕے جماعت گٔیہِ نزدیک، تہٕ گٔیہِ خداوند سٕندِس برونہہ کُن کھڑا۔\n6. تہٕ موسىٰ ووٚن یہِ سُہ چیز یُس خداوند چُھہ حُکُم دِیُتمُت تہٕ خداوند سُند جلال گژھہِ توے برونہہ کُن ظٲہر۔\n7. تہٕ موسىٰ ووٚن ہارونس زِ قربان گاہس پیٹھ گژھ تہٕ پنُن گۅناہ تہٕ پنُن زالنہٕ نذرانہ پیش کرُن، تہٕ پانس تہٕ لوکن ہٕندِ خٲطرٕ کفارہٕ کرُن، تہٕ لوکن ہٕنز قربانی پیش کرٕن، تہٕ تِمن ہٕندِ خٲطرٕ کفارہٕ کرُن۔ یِتھٕ کٔنۍ خداوند دِیُت حُکُم۔\n8.\\tہارون گۆو قربان گاہس کُن، تہٕ مٲرِن گۅنہٕ نذرانہٕ ہُند بَچھرٕ یُس پانس خٲطرٕ اوس۔\n9. تہٕ ہارون سٕندیو نیچویو اوٚن أمِس نِش خون، تہٕ تٔمۍ ترووُن خونس مَنٛز اوٚنٛگجہ تہٕ تھووُن قربان گاہٕ کِس سینگس پیٹھ، تہٕ ترووُن قربان گاہس تل خون:\n10.\\tمگر چربی تہٕ گردہٕ تہٕ گۅنہٕ کِس کۅکرس پیٹھ، سُہ زٲلِتھ قربان گاہس پیٹھ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n11.\\tتہٕ ماز تہٕ کھال یُس أمِس کیمپَس ورٲے نارٕ سٍتـ̡ زالُن۔\n12. تہٕ تٔمۍ مٲرِتھ زٲلِتھ نذرانہٕ۔ تہٕ ہارون سٕندٮ۪و نیچویو دِژ أمِس برونہہ کُن خوُن، یُس تٔمۍ قربان گاہس پیٹھ چھُکُن۔\n13.\\tتہٕ تِمو دِژ أمِس برونہہ کُن زٲلِتھ تہٕ کلہٕ سٍتـ̡ تہٕ تٔمۍ زٲلِتھ قربان گاہس پیٹھ۔\n14.\\tتہٕ تٔمۍ کٔرٕن أنٛدرِم تہٕ زنگہٕ واش تہٕ قربان گاہس پیٹھ دزنہٕ آمٕژ قربان گاہس پیٹھ زالُن۔\n15.\\tتہٕ تٔمۍ اوٚن لُکن ہٕنز نذرانہ تہٕ رٔٹِن ژھاوٕل، یۄسہٕ لُکن ہٕندِ خٲطرٕ گۅنہٕ ہٕنز قربانی ٲس، تہٕ مٲرِتھ تہٕ کوٚرُن گۅنہٕ خٲطرٕ پیش کرنہٕ۔\n16.\\tتہٕ تٔمۍ أنِن دزنہٕ نذرانہ تہٕ کوٚرُن طٔریٖقہٕ مُطٲبق پیش کرنہٕ۔ {طریقہٕ: یا، آرڈیننس}\n17.\\tتہٕ تٔمۍ اوٚن مازٕچ نذرانہ تہٕ تٔمِس مُتعلِق رٔٹِتھ دِژُن قربان گاہَس پیٹھ، صُبحٕچ دزنہٕ آمٕژ قربانی سٍتـ̡ زٲلِتھ۔ {ٹُک...: ہیب۔ اَتھ منزٕ بٔرِتھ اَتھٕ بٔرِتھ}\n18.\\tتٔمۍ مٲرِتھ دِژ دانٛد تہٕ مینڈٕ تہِ یُس لُکن ہٕندِ خٲطرٕ اوس، تہٕ ہارون سٕندٮ۪و نیچویو دِژ أمِس نِش خوُن، یُس تٔمۍ اندۍ پکھۍ قربان گاہس پیٹھ چھُکُن دِژ،\n19.\\tتہٕ بیلن ہٕنز چربی تہٕ کۅکرِ ہٕندِس کُنہِ\n20.\\tتہٕ تِمو تھووُن سینن پیٹھ چربی تہٕ تٔمۍ زٲلِن قربان گاہس پیٹھ:\n21.\\tتہٕ سین تہٕ دٔچھُن پھیُر ہارون کٔر خداوند سٕندِ برونہہ کُن لہراونہٕ خٲطرٕ۔ یِتھ کٔنۍ موسیٰ سُند حُکُم دِیُت۔\n22. تہٕ ہارونن تُل لُکن کُن اتھہٕ تہٕ تِمن دِژ برکت تہٕ دِژن گۅنہٕ نذرانہٕ تہٕ دزنہٕ آمٕژ نذرانہ تہٕ امن ہٕنزِ نذرانہ سٍتـ̡ بۄن۔\n23. تہٕ موسیٰ تہٕ ہارون گٔیہِ جماعت کِس خیمہ خانس مَنٛز، تہٕ درٛاو تہٕ کٔرٕن لُکن برکت تہٕ خداوند سُند جلال آو سارنٕے لُکن ہٕندِس خٲطرٕ ظٲہر۔\n24.\\tتہٕ خداوند سٕندِ برونہہ کُن نار دراو تہٕ قربان گاہس پیٹھ دزنہٕ آمُت قربان گاہ تہٕ چربی زٲلِتھ تہٕ یُس سارِوٕے لُکھ وُچھ، تِمو کٔر کرٛٮ۪کھ تہٕ پٔرِتھ پٔرۍ۔","1.\\tتہٕ ناداب تہٕ ہارون سٕندِ نیچویو نِش نِش تِمو منزٕ کُنہِ تہِ پنُن سنسر، تہٕ اَتھ مَنٛز دِژُکھ نار تہٕ اَتھ پیٹھ تھووُن بخور تہٕ خداوندَس برونہہ کُن عجیب نار پیش کٔرِتھ یُس نہٕ تِمن حُکُم دِیُت۔\n2. تہٕ خداوند سٕندِ طرفہٕ نار دراو تہٕ تِم کھیوٚن تہٕ تِم گٔیہِ خداوند سٕندِ برونہہ کُن۔\n3. اَمہِ پَتہٕ ووٚن موسىٰ ہارونس زِ یہِ چُھہ خداوند وَنُن زِ بہٕ گژھہٕ تِمن مَنٛز پاکیزٕ یُس میہ نزدیک یِن، تہٕ سارِنٕے لُکن برونہہ کُن گژھہٕ بہٕ پاکیز۔ تہٕ ہارون تھوو پنُن خاموش۔\n4. تہٕ موسىٰ بُلوو مِشایل تہٕ الزافان، یِم عزیل سٕندِس نیچوِس ہارون سٕندِس پیٚتٕر ٲسۍ، تہٕ وونُن تِمن نزدیک، پنٕنـ̡ بٲے نِیُن مقدس مقامہٕ منزٕ نِنہٕ۔\n5. تہٕ تِم گٔیہِ نزدیک، تہٕ تِم نِنہٕ آمٕتۍ کوٹہٕ منٛزٕ خٲمہٕ منٛز۔ یتھہ پاٹھۍ موسیٰ ہن ووٚنمُت۔\n6. تہٕ موسىٰ ووٚن ہارونس تہٕ الیعازر تہٕ اِتھمارس تہٕ تٔمۍ سٕندِس نیچوِس تہٕ پَنٕنۍ کلہٕ ژٔٹِتھ تہٕ نہ پھٔٹِو پَنٕنۍ پَنٕنۍ پَلَو۔ یێلہِ گژھہِ تُہۍ مرُن، تہٕ سارِنٕے لُکن ہُند قہر یێلہِ، مگر پَنٕنـ̡ بٲے یێلہِ سارِنٕے اِسرٲیلِس سٍتـ̡ دِنہٕ یُس خداوند دِژمُت چُھ۔\n7. تہٕ ژیہ گژھِ نہٕ جماعت ہٕندِس خیمہ کِس دروازٕ پیٹھٕ نیرِتھ، یێلہِ گژھِ نہٕ مَرُن: کیازِ خداوند سُند مسح کرنُک تیٖل چُھہ توے پیٹھ۔ تہٕ تِمو کوٚر موسیٰ سٕندِ کلامَس مطٲبق۔\n8. تہٕ خداوند ووٚن ہارونس سٍتـ̡ وَنُن،\n9. ییلہ تم جماعت کِس خیمہ خانس مَنٛز گژھِو نہٕ شرابہٕ تہٕ نہ چیٚوُن، تہٕ تُہۍ گژھہِ مرُن: {یہِ} روزِ تُہنزن نسلن خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون۔\n10. تہٕ یُتھ زن تُہۍ پاک تہٕ ناپاک تہٕ ناپاک درمِیان فرق کٔرِو۔\n11. تہٕ یێلہِ تہٕ تُہۍ ہیچھناوِو بنی اِسرٲیلِس تِم سٲری فرمان یِم خداوند موسیٰ سٕندِ اتھہٕ سٍتـ̡ تِمن سٍتـ̡ کتھ کٔرمٕژ چھِ۔\n12. تہٕ موسىٰ کٔر ہارونس سٍتـ̡ تہٕ الیعازر تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ کتھ کرنہٕ، یُس خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہٕ سٍتـ̡ باقٕے روزان چُھ، تہٕ کھٮ۪وُن قربان گاہس نِش خمیر ورٲے کھٮ۪ن: کیازِ یہِ چُھ سارِوٕے کھۄتہٕ مقدس ۔\n13. تہٕ تُہۍ کھیوٚو یہِ مُقدس مقامس مَنٛز، تِکیازِ یہِ چُھہ تُہُند تہٕ تہندٮ۪ن نیٚچوٮ۪ن ہُند حق، یُس خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یێلہِ چُھہ مے حُکُم دِنہٕ آمُت۔\n14.\\tتہٕ لہرِ ہُند سین تہٕ ہیو پھیُر کُنہِ صاف جایہِ کھٮ۪نہٕ۔ تہٕ تُہٕندِس نیچوِس تہٕ تُہٕنزِ کورِ تہٕ تُہٕندِس نیٚچوِس سٍتـ̡ چُھہ تُہُند حق تہٕ تُہٕندِس نیٚچوِس سٍتـ̡ یُس بنی اِسرٲیلـ̡ ہٕندِس صلح کِس قربانیو سٍتـ̡ دِنہٕ آمُت چُھ۔\n15.\\tہیو پھیُر تہٕ لہرِ ہٕندِس سینہٕ سٍتـ̡ یِم چربی ہٕندِس نارس سٍتـ̡ دِنہٕ آمٕژ نذرانہٕ سٍتـ̡ أنِتھ، یێلہٕ سٍتـ̡ خداوند سٕندِس برونہہ کُن لہر ہٕندِس نذرانہ سٍتـ̡ لہراوُن۔ تہٕ یہ آسہِ تۅہہِ تہٕ تُہند نیچو تہٕ تُہند نیچو آسہِ ہمیشہٕ خٲطرٕ أکِس قانونس سٍتۍ۔ یِتھٕ کٔنۍ خداوند چُھ حُکُم دِژمُت۔\n16.\\tتہٕ موسیٰ کٔر گۅنہٕ ہٕندِس نذرانہٕ سٍتـ̡ ژھانڈنہٕ خٲطرٕ، تہٕ وُچھِتھ آو یہِ زالنہٕ، تہٕ سُہ گوٚو ہارون سٕندِس نیچوِس الیعزر تہٕ اِتھمارس سٍتـ̡ شرارت تہٕ وونُن،\n17. کیازِ چُھہ نہٕ ژیہ مقدس مقامس مَنٛز گۅناہ ہُند قربانی کھیوٚمُت، تہٕ {خدایہ} چُھ یہِ جمٲژ ہٕنز بدکاری برداشت کرنہٕ خٲطرٕ دِژمُت، یُس خداوند سٕندِ برونہہ کُن تِمن ہُند کفارہ دِنہٕ خٲطرٕ دِیُتمُت؟\n18.\\tوچھ امیک خون آو نہٕ مقدس مقامس منز اننہٕ: یُس میہ حکم دِژمُت اوس، یُس میہ حکم دِژمُت اوس، تۅہہ پزِ پزۍ پاٹھۍ یہ مقدس مقامس منز کھیوٚن۔\n19. تہٕ ہارونن ووٚن موسیٰ سٍتـ̡ وُچھِو، اَمہ دۅہہ چُھ تِمو پَنُن پَنُن پٲٹھـ̡ نذرانہ تہٕ پَنُن زٲلِتھ قربان کٔرِتھ خداوند سٍتـ̡ پیش کرنہٕ۔ تہٕ یِتھۍ کتھہٕ گٔیہِ میہ سٍتـ̡ گۅنہٕ نذرانہ کھیوٚمُت، کیا یہ گژھہِ خداوند سٕندِس نظرس منز قبول کرنہٕ یُن؟\n20.\\tتہٕ ییلہ موسیٰ ہن بوٗز، سُہ اوس مطمئن۔","1. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ تہٕ تِمن سٍتـ̡ وونُن،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، یِم چِھہ تِم جانور یِم زمینس پیٹھ موجود سارِنٕے درندَن مَنٛز کھٮ۪وان چھِو۔\n3.\\tیُس تہِ کھورِ ژٔٹِتھ تہٕ کھورِ کھٔرِتھ چُھہ، تہٕ یُس ژیہ کھٮ۪وان چھُ۔\n4. توتہِ گژھ نہ تم کھیوٚن یم کھۅر چیوان چھہِ، تہ کھورِ پھٹان چھہِ، تکیازِ سہ چھہ کھورِ چیوان مگر کھورِ چھہ نہ بٲگراونہ یوان۔ سُہ چُھ تۅہہِ خٲطرٕ ناپاک ۔\n5.\\tتہٕ کُنی، تکیازِ سُہ چُھہ کھورِ چُھہ کُنہِ تہِ کُنہِ تہِ کُنہ سُہ چُھ تۅہہِ خٲطرٕ ناپاک ۔\n6.\\tتہٕ خرگوش، کیازِ سُہ چُھہ کھورِ چُھس، مگر کھُر چُھس نہٕ تقسیم کران۔ سُہ چُھ تۅہہِ خٲطرٕ ناپاک ۔\n7. تہٕ سور، یودوَے سُہ کھُر پھٔٹِتھ تہٕ کھورِ کھورِ کٔرِتھ، توتہِ چُھس نہٕ سُہ کُڈ چِھوان۔ سُہ چُھ تۅہہِ خٲطرٕ ناپاک ۔\n8.\\tتِہُند ماز کھیوٚو نہٕ تہٕ تِہُند لاشہٕ گژھِ نہٕ اَتھٕ لاگُن۔ تِم چھِ تۅہہِ خٲطرٕ ناپاک۔\n9.\\tیِم کھٮ۪وان یُس آبس مَنٛز چُھہ، سمندرَن مَنٛز تہٕ دریاوَن مَنٛز پَکھہٕ تہٕ پَکھہٕ آسہِ، تِم کھٮ۪وان چھِو۔\n10. تہٕ یِمن سمندرس مَنٛز تہٕ دریاوَن مَنٛز پَکھہٕ تہٕ پَکھہٕ آسہِ، تہٕ کُنہِ تہِ زُو زُو یُس آبس مَنٛز چُھ، تِم گژھِ تۅہہِ خٲطرٕ مکروہ بٔنِتھ:\n11.\\tتِم گژھن تۅہہِ خٲطرٕ تہِ ناپسندیدگی تہِ آسن۔ تِہُند ماز کھیوٚو نہٕ، مگر تِہُند لاشہٕ گژھہِ مُنفرِس سٍتـ̡ کھٮ۪نہٕ۔\n12.\\tیُس نہ آبس منز پکھہ آسہِ تہ نہ پکھہ آسہِ، سہ گژھہِ تۅہہِ خٲطرٕ ناپسندیدگی آسہِ۔\n13. تہٕ یِم {تِم} چِھ یِم جاناوارن مَنٛز مُکرٲہِس سٍتـ̡ بٔرِتھ آسہِ۔ تِم گژھن نہٕ کھٮ۪نہٕ، تِم چھِ اکھ مکروہ چیز : عقاب ، تہٕ اوسیفریج ، تہٕ اوسپرے،\n14. تہٕ گُدھ تہٕ گانٛٹہٕ بیٛٲر تہٕ گانٛٹہٕ بیٛٲر۔\n15.\\tپرٮ۪تھ کۅکُن پننہِ قسمہ پتہٕ۔\n16. تہٕ راتہٕ مۄغل، تہٕ رٲژ ہُند باز، تہٕ کۅکر تہٕ باز،\n17. تہٕ لۄکُٹ راتہٕ مۄغل، تہٕ بٔڈ راتہٕ مۄغل،\n18. تہٕ ہنس تہٕ پیلیکن، تہٕ گِیر عقاب ،\n19.\\tتہٕ سارِوٕے سٕندِس قٕسمس پَتہٕ بٔرۍ، تہٕ لَپنہٕ وِنگ، تہٕ کُلہٕ کُن۔\n20.\\tسارِنٕے جاناوار یِم ژۅشونی ہٕندِس کُنہِ تہِ کُنہِ\n21.\\tتوتہِ ہیکو یِم پرٮ۪تھ کُنہِ وُڈنہٕ وٲلِس چیزس کھٮ۪وان یُس ژۅشونی ہٕندِس کھورِ پیٹھ، یِمن ہٕنزِ زنگہٕ ہیوٚر آسہِ، زمینس پیٹھ وۄٹھ دِنہٕ خٲطرٕ۔\n22.\\t{حتیٰ کہ} یِمو منزٕ ہیکو کھٮ۪تھ تہِ۔ ٹِڈی ٹِڈی پننہِ قٕسمٕکۍ پتہٕ، تہٕ ٹِڈی ٹِڈی پننہِ قٕسمٕکۍ پتہٕ، تہٕ ٹِڈٕ پننہِ قٕسمٕکۍ پتہٕ۔\n23.\\tمگر باقی سارِنٕے {وُڈِن} وُڈِتھ وُڈان یِمن ژۅن کھۅر آسہِ، تۅہہِ ہٕندِ خٲطرٕ گژھن مکروہ آسن۔\n24. تہٕ یِمن ہٕندِ خٲطرٕ گژھِو ناپاک روزُن، یُس تہِ یِمن ہٕندِس لاشس اتھہٕ لاگہِ سُہ گژھہِ ناپاک روزُن۔\n25.\\tیُس تہِ یِمن ہُند لاشہٕ تُلِتھ آسہِ سُہ گژھِ پَنُن پلو چھلُن، تہٕ سُہ روزِ ناپاک روزُن۔\n26.\\tپرٮ۪تھ کانہہ جانور یُس کھُر پھٔٹِتھ چھُ، تہٕ {چُھ} نہٕ کھورِ کھورِ تہٕ نہ چُھہ کھورِ چُھہ، {چُھہ} چُھہ تۅہہِ خٲطرٕ ناپاک آسان: یُس تہِ یِمن اتھہٕ لاگان آسہِ سُہ گژھہِ ناپاک۔\n27.\\tتہٕ یُس تہٕ یُس تہٕ تٔمۍ سٕندِس پٲٹھـ̡ ژۅشونی درندَن مَنٛز چُھہ یِم ژۅشونی ہٕندِس پٲٹھـ̡ چُھہ ناپاک آسان، یُس تہٕ یُس تہندِس لاشس اتھہٕ لاگہِ سُہ گژھہِ ناپاک روزُن۔\n28.\\tیُس یُس یِمن ہُند لاشہٕ تُلِتھ آسہِ سُہ گژھِ پَنٕنـ̡ پَ\n29. یِم تہِ گژھن تۅہہِ خٲطرٕ ناپاک آسن یُس زمینس پیٹھ کھسان چھُ۔ کچھو، تہٕ گگر تہٕ کچھو،\n30. تہٕ فیریٹ، تہٕ گرگٹ، تہٕ چھپکلی، تہٕ گھونگجہٕ، تہٕ تل۔\n31.\\tیِم چھِ تۅہہِ خٲطرٕ ناپاک یِمن سارِنٕے نژان چھِ: یُس تہِ یِمن اتھہٕ لاگہِ، یێلہِ سُہ مرُن آسہِ، سُہ روزِ ناپاک روزُن۔\n32. تہٕ یِمن مَنٛز یُس تہِ {کُنہِ} آسہِ، یێلہِ تِم مٔرِتھ پیٚیہِ، سُہ گژھہِ ناپاک ۔ چاہے سُہ کانہہ تہِ لٔکرِ، یا لباس، یا کھال، یا بوری آسہِ، یُس تہِ بانہٕ آسہِ، یتھ منز کانہہ تہِ کٲم آسہِ، سُہ گژھہِ آبس منز تراوُن، تہٕ یہ گژھہِ ناپاک روزُن۔ تہ یہ گژھہِ صاف کرنہ۔\n33.\\tتہٕ پرٮ۪تھ کُنہِ میژِ ہُند بانہٕ، یێمہِ مَنٛز {کُنہِ} تہٕ یێمہِ سٍتـ̡ {چُھ} آسہِ، سُہ گژھہِ ناپاک آسہِ۔ تہٕ ژیہ پھُٹراوُن۔\n34.\\tیُس ماز کھٮ۪نہٕ ییہِ، سُہ گژھہِ ناپاک تہٕ یُس پرٮ۪تھ کُنہِ برنہٕ مَنٛز چَنہٕ یِنہٕ آسہِ، سُہ گژھہِ ناپاک آسُن۔\n35. تہٕ پریتھ کانہہ {چیز} یُس تہندِ لاشہِ ہند کانہہ حصہ پییہِ ناپاک آسہِ۔ {چاہے سُہ تندور آسہِ، یا بانہٕ خٲطرٕ، یِم گژھن پھُٹراونہٕ یِن: {کیازِ} تِم {چِھ} ناپاک تہٕ تۅہہِ خٲطرٕ ناپاک آسن۔\n36.\\tبہر حال اکھ چشمہ یا کھۅڈ، یتھ منز واریاہ آب آسہِ، گژھہِ صاف آسُن، مگر یُس تہندس لاشس سیتۍ واٹھ آسہِ، سہ گژھہِ ناپاک آسُن۔ {یتھ منز...: ہیب۔ آبُک اکھ اجتماع}\n37.\\tتہٕ اگر تِہٕندِ لاشہٕ ہُند کانہہ حصہٕ یُس وونہٕ یُن آسہِ، سُہ گژھہِ صاف کرنہٕ۔\n38.\\tمگر اگر کُنہِ تہِ آب ییہ بیٲلِس پیٹھ تراونہٕ، تہٕ تِہٕندِس لاشُک کانہہ حصہٕ پییہِ، سُہ گژھہِ تۅہہِ خٲطرٕ ناپاک۔\n39. تہٕ اگر کانہہ جانور یُس تُہۍ کھٮ۪وان چھِو، سُہ گژھہِ مَرُن۔ یُس امہِ کِس لاشس اَتھٕ لاگان آسہِ سُہ گژھِ ناپاک روزُن۔\n40.\\tیُس امہِ ہُند لاشہٕ کھٮ۪وان چُھ، سُہ گژھِ پَنُن پلو چھلُن، تہٕ یُس تہِ یُس اَمہ ہُند لاشہٕ رٔٹِتھ آسہِ، سُہ گژھِ پَنُن پلو چھلناوُن، تہٕ یُس تہِ روزِ ناپاک روزُن۔\n41. تہٕ یُس پرٮ۪تھ کانہہ چیز زمینس پیٹھ کھسان آسہِ سُہ گژھہِ مکروہ بٔنِتھ۔ یہ گژھِ نہٕ کھٮ۪نہٕ یُن۔\n42.\\tیُس تہِ یُس یُس ژۅشونی پیٹھ گژھہِ، تہٕ یُس تہِ ژۅشونی پیٹھ کھسان آسہِ، یا یُس تہِ زمینہِ پیٹھ کھسان آسہِ، تم گژھہِ نہ کھیوٚن۔ تکیازِ تم چھہِ اکھ مکروہ چیز۔ {ہاتھ...: ہیب۔ کھۅرن ہُند ضرب دِوان}\n43. یُس تہِ کُنہِ تہِ چیزس سٍتـ̡ پان ناپاک بناوُن تہٕ نہ کرُن پان یِمن سٍتـ̡ ناپاک کرنہٕ۔ {تم پان نفرت انگیز: ہیب۔ تُہند روح وغیرہ}\n44. تِکیازِ بہٕ چُھس خداوند تُہند خدا: تێمہِ مۄکھٕ کٔرِو تُہۍ پنُن پان پاک تہٕ پاک روزُن؛ تکیازِ بہٕ چُھس پاکیز: تہٕ نہ کٔرِو پان کُنہِ تہِ طریقہٕ سٍتۍ ناپاک یُس زمینس پیٹھ رژان آسہِ۔\n45. تِکیازِ بہٕ چُھس خداوند یُس تۅہہ مصر کہِ سرزمینہٕ منزٕ نیبر نیران چُھ، تُہند خدا بننہٕ خٲطرٕ: تێلہِ گژھہِ تُہۍ پاک روزُن، تکیازِ بہٕ چُھس پاک۔\n46.\\tیہ چھہ درندن تہ جاناوارن تہ پریتھ جاندارن ہند قانون یُس آبس منز پکان چھہ تہ پریتھ کُنہِ جاندار سُند قانون یُس زمینس پیٹھ رژان چھہ۔\n47.\\tناپاک تہٕ پاکیزس درمیان فرق کرُن، تہٕ یُس جانور کھٮ۪نہٕ یِوان چھُ، تہٕ یُس نہٕ کھٮ۪نہٕ یِنہٕ وٲلِس درندَس درمِیان فرق کرُن۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، یێلہِ زنانہِ ہٕندِس بُلِس زامُت آسہِ، تہٕ مرد بچہٕ زامُت، تیلہِ گژھہِ سَتھ دۅہہٕ ناپاک روزُن۔ جدایی ہٕندِس دۅہس مطٲبق گژھہِ سُہ ناپاک آسُن۔\n3. تہٕ ٲٹھمہِ دۅہہٕ گژھہِ تٔمۍ سٕندِس کھالُک ماز ختنہ کرنہٕ۔\n4.\\tتہٕ سُہ روزِ پننہِ پاکیزگی ہٕندِس خونس منز تریہ ترہن دۅہن پاکیزہ۔ سۄ گژھِ نہٕ کانٛہہ تہِ مقدس چیزس اتھہٕ لاگنہٕ، تہٕ نہ یِنہٕ مقدس مقامس منٛز، یوٚتام نہٕ تٔمۍ سٕنٛدِ پاکیزگی ہٕندۍ دۄہ پوٗرٕ گژھن۔\n5.\\tمگر اگر أمِس دٲیرِ ہُند شُر آسہِ، تیلہِ گژھہِ سُہ دۅن ہفتن ناپاک روزُن، یِتھ کٔنۍ زِ سُہ گژھہِ پننہِ پاکیزگی ہٕندِس خونس مَنٛز تریہ تہٕ شیہ دۅہہٕ روزُن۔\n6. تہٕ ییلہِ تٔمۍ سٕندِ پاکیزگی ہٕندِ دۅہ پوٗرٕ سپدِ، نیچوِس یا کورِ ہٕندِ خٲطرٕ، سُہ اَنِہ گۅنہٕ کِس نذرانہ خٲطرٕ گۅنہٕ کِس دروازس پیٹھ، پادٕرِس نِش:  ہیب۔ تٔمۍ سٕنٛدِ ؤرۍ یُک نیچو}\n7. یُس یہِ خداوند سٕندِ برونہہ کُن پیش کرِ، تہٕ تٔمِس خٲطرٕ کفارہ دِیہِ۔ تہٕ سُہ گژھہِ پننہِ خونُک مسلہٕ نِش پاک کرنہٕ۔ یہٕ چُھ تٔمِس خٲطرٕ سُہ قانون یُس نر یا زنانہٕ زامُت چُھ۔\n8. تہٕ اگر سۅ کۅکرِ کٔرِتھ ہیکان آسہِ، تیلہِ گژھہِ سۅ زٕ کچھو، یا زٕ کۅتر أنِتھ۔ اکھ دزنہٕ خٲطرٕ، تہٕ بیٛاکھ گۅنہٕ نِشہ خٲطرٕ: تہٕ پادٕرۍ کرِ تٔمِس خٲطرٕ کفارہٕ، تہٕ سۄ گژھہِ پاک۔ {سۅ آسہِ...: ہیب۔ تٔمۍ سٕنٛدس اتھس لٔب نہٕ کافی}","1. تہٕ خداوند دِژ موسیٰ تہٕ ہارونس سٍتـ̡ وَنُن،\n2.\\tییلہ انسانس پننِس مازس منز اکھ کھور، کھورِ یا چمکدار داغ آسہِ، تہٕ یہ آسہِ تٔمۍ سٕندِس مازس منز کوڑھ ہٕندِس مسلس منز۔ تیلہِ یِیہِ سُہ پادٕرۍ ہارونَس نِش نِنہٕ یُن، یا تٔمۍ سٕندِس أکِس نیچوِس نِش یِنہٕ یِنہٕ: {وُتھُن: یا، ورم}\n3.\\tتہٕ پادٕرۍ گژھہِ مازٕ سٕندِس کھالس مَنٛز وُچھُن، تہٕ یێلہِ یێلہِ طاعون سفید، تہٕ یێلہِ وُچھنہٕ ییہِ طاعون تٔمۍ سٕندِس مازٕ کِس کھالہٕ کھۅتہٕ سرٛوٚن آسہِ، سُہ چُھ کوڑھُک وُپھ تہٕ پادٕرۍ أمِس وُچھِتھ تہٕ ناپاک قرار دِیہِ۔\n4.\\tاگر چمکدار داغ تمۍ سندِ مازِ ہندس مسلس منز سفید، تہ نظرِ تل آسہِ نہ ژمہِ کھوتہ زیادہ سوٚن تہ امیک مس گژھہِ نہ سفید۔ تیلہِ گژھہِ پادٕرۍ سَتن دۅہن بند کرُن:\n5.\\tتہٕ پادٕرۍ سٔتِمہِ دۅہہٕ وُچھُن: تہٕ وُچھِو، {یێلہِ} تٔمِس نظرِ وُچھِتھ وُپھ آسہِ، {تہٕ} طاعون پھٔہلِتھ نہٕ۔ تیلہِ کرِ پادٕرۍ أمِس سَتھ دۅہہٕ بند۔\n6.\\tتہٕ پادٕرۍ گژھہِ سٔتِمہِ دۅہہ أمِس دُبارٕ وُچھان: تہٕ وُچھِو، {یێلہ} طاعون {تہٕ} ژٔلِتھ آسہِ نہٕ، پادٕرۍ کرِ أمِس پاک قرار: یہِ {چُھ} کھورِ تہٕ سُہ کرِ پَنٕنـ̡ پٲٹھـ̡ پَنُن\n7.\\tمگر یێلہِ کھورِ ژٔلِتھ تہٕ یێلہِ سُہ پادٕرۍ سٕندِس پاکیزگی خٲطرٕ وُچھنہٕ یِیہِ، سُہ گژھہِ دُبارٕ پادٕرۍ سٕندِس نِش وُچھنہٕ:\n8.\\tتہٕ اگر پادٕرۍ وُچھِتھ زِ وُچھِتھ چُھہ مسلس مَنٛز پھٔہلِتھ، تیلہِ کرِ پادٕرۍ أمِس ناپاک قرار: یہِ چُھ کوڑھ۔\n9.\\tییلہِ کٲنسہِ انسانس منز کوڑھ ہُند وبا آسہِ، تیلہِ یِیہِ سُہ پادٕرِس نِش اننہٕ۔\n10.\\tتہٕ پادٕرۍ وُچھِن {أمِس} تہٕ وُچھِتھ {یێلہ} وُچھِتھ {یێلہِ} وُچھُن مَسلہٕ سفید، تہٕ سُہ چھُ مَس سفید، تہٕ {اَتہِ} ہُند خام ماز آسہِ۔ {جلدی...: ہیب۔ زندٕ مازُک تیز رفتار}\n11.\\tیہِ چُھ تٔمۍ سٕندِس مازس مَنٛز اکھ پرٛون کوڑھ، تہٕ پادٕرۍ کرِ أمِس ناپاک قرار دِنہٕ، تہٕ کرِ نہٕ أمِس بند کرنہٕ، کیازِ سُہ چُھ ناپاک ۔\n12.\\tتہٕ یێلہِ کوڑھ ژٔلِتھ ژٔلِتھ تہٕ کوڑھ سٕندِس سارِنٕے مٕسلہٕ ژٔلِتھ یُس کلہٕ پیٹھٕ کھورِ تام وُچھِتھ آسہِ، ییتہِ تہِ پادٕرۍ نظر دِیہِ۔\n13.\\tتیلہِ گژھہِ پادٕرۍ غور کرُن: تہٕ وُچھِو، {یێلہ} کوڑھ پنُن سورُے ماز ؤلِتھ آسہِ، سُہ کرِ {أمِس} پاک {یُس} طاعون دِنہٕ آمُت: سُہ چُھ سُہ {سُہ} صاف گومُت۔\n14. مگر ییلہ تس منز خام ماز ظٲہر گژھہِ، سُہ گژھہِ ناپاک ۔\n15.\\tتہٕ پادٕرۍ گژھہِ خام ماز وُچھِتھ تہٕ أمِس ناپاک قرار دِن: {تکیازِ} خام ماز {چُھ} ناپاک: یہِ {چُھ} کوڑھ۔\n16.\\tیا اگر خام ماز پھیُرِتھ سفید، سُہ گژھہِ پادٕرِس نِش یِنہٕ۔\n17.\\tتہٕ پادٕرۍ وُچھِن أمِس وُچھِن: تہٕ وُچھِو، {اگر} طاعون سفید۔ تیلہ کرِ پادری {أمِس} صاف {یُس طاعون چُھ}: سُہ {چُھ} پاک۔\n18.\\tماز تہِ، یتھ منز ژمہِ منز، پھۅپھ اوس، تہٕ چھہ ٹھیک سپدان،\n19.\\tتہٕ پھورِ ہنزِ جایہ آسہِ سفید، یا چمکدار داغ، سفید، تہٕ کُنہِ حدس تام وۄزل تہٕ یہ گژھہِ پادٕرِس ہاونہٕ یُن۔\n20. تہٕ یێلہِ پادٕرۍ یہِ وُچھِ، وُچھِو سُہ ژمہٕ کھۅتہٕ بۄن تہٕ تٔمِس مَس سفید۔ پادٕرۍ دِیہِ أمِس ناپاک قرار: یہِ چُھ کوڑھُک اکھ وُپھ یُس پھُٹان چُھ۔\n21.\\tمگر اگر پادٕرۍ اتھ وُچھِتھ تہٕ وُچھِتھ آسہِ نہٕ اتھ منز کانہہ سفید، تہٕ {اگر} آسہِ نہٕ ژمہِ کھۅتہٕ بۄن بلکہ {آسہِ} کُنہِ حدس تام سیاہ آسہِ۔ تیلہِ کرِ پادٕرۍ سَتھ دۅہہٕ بند۔\n22.\\tتہٕ یێلہِ یہِ ژَمہِ مَنٛز واریاہ پھٔہلِتھ آسہِ، تیلہِ گژھہِ پادٕرۍ أمِس ناپاک قرار دِن: یہِ چُھ اکھ طاعون۔\n23.\\tمگر اگر چمکدار داغ پننہِ جایہ روزِ، {تہٕ} پھٔہلِتھ آسہِ، سُہ چُھ دزُن۔ تہٕ پادٕرۍ کرِ أمِس پاک قرار۔\n24.\\tیا اگر کانہہ ماز آسہِ، یُس مسلس منز تپُر دزان آسہِ، تہٕ یُس ماز دزان آسہِ، تتھ منز چھہ سفید، کُنہِ حدس تام وۄزل یا سفید۔ {اکھ گرم...: ہیب۔ نارُک دزُن}\n25.\\tتیلہِ گژھہِ پادٕرۍ اتھ وُچھِن: تہٕ وُچھِو، {یێلہِ} چمکِس مَس سفید، تہٕ سُہ آسہِ ژمہِ کھۅتہٕ سرٛوٚن نظر۔ یہِ چُھہ دزنہٕ سٍتـ̡ اکھ کوڑھ یُس دزنہٕ سٍتـ̡ پھُٹمُت چُھ: اَمہِ مۄکھٕ چُھہ پادٕرۍ أمِس ناپاک قرار دِنہٕ: یہِ چُھ کوڑھُک طاعون۔\n26.\\tمگر اگر پادٕرۍ اتھ وُچھِتھ تہٕ وُچھِتھ چھُنہٕ چمکِس جایہِ کانہہ سفید، تہٕ یہِ آسہِ نہٕ {باقی} کھالہٕ کھۅتہٕ بۄن آسان، مگر {آسہِ} کُنہِ حدس تام سیاہ ۔ تیلہِ کرِ پادٕرۍ سَتھ دۅہہٕ بند۔\n27.\\tتہٕ پادٕرۍ گژھہِ سٔتِم دۅہہ أمِس وُچھان: {تہٕ} اگر یہِ مسلس مَنٛز واریاہ پھٔہلِتھ آسہِ، تیلہِ کرِ پادٕرۍ أمِس ناپاک قرار: یہِ چُھ کوڑھُک وباہ۔\n28.\\tتہ اگر چمکدار داغ پننہِ جایہ روزِ، {تہ} گژھہِ نہ مسلس منز پھہلِتھ بلکہ گژھہِ یہ {کُنہِ حدس تام سیاہ گٹہِ}۔ یہ {چُھ} دزنہٕ سُند وۅتھ، تہٕ پادٕرۍ کرِ أمِس صاف قرار: کیازِ یہِ چُھ دزنہٕ سُند ورم۔\n29.\\tاگر کٲنسہِ مردس یا زنانہِ کلس یا داڑھس پیٹھ وبا آسہِ۔\n30.\\tتیلہِ گژھہِ پادٕرۍ وُچھِتھ طاعون تہٕ وُچھِتھ اگر یہِ ژمہِ کھۅتہٕ سرٛوٚن آسہِ۔ {تہٕ اَتھ منز چھُ لیوٚدُر پتلہٕ مست؛ تیلہ کرِ پادٕرۍ أمِس ناپاک قرار: یہ {چُھ} خشک کال، {حتیٰ کہ} کلہٕ یا داڑھس پیٹھ کوڑھ۔\n31.\\tتہ اگر پادٕرۍ کُنہِ وُپھ وُچھِتھ وُچھِتھ تہٕ وُچھِتھ چھُنہٕ سُہ ژمہِ کھۅتہٕ سرٛوٚن وُچھان تہٕ اتھ منز چُھنہٕ کانہہ کرٛیٚہنہِ مَس وُچھان۔ تیلہ گژھہِ پادٕرۍ سَتھ دۅہن بند کرُن:\n32.\\tتہٕ سٔتِمہِ دۅہہٕ پادٕرۍ وُچھِن طاعون وُچھان: تہٕ وُچھِو، {یێلہِ} پھٔہلِتھ آسہِ نہٕ، تہٕ اَتھ مَنٛز آسہِ نہٕ لیوٚدُر مَس، تہٕ سُہ آسہِ نہٕ ژمہٕ کھۅتہٕ سرٛوٚن وُچھان۔\n33.\\tسُہ گژھِ کھوٗر کرنہٕ یُن، مگر سُہ گژھِ نہٕ کھوٗر کَرُن۔ تہٕ پادٕرۍ کرِ سَتھ دۅہ بند کرُن:\n34.\\tتہٕ سٔتِمہِ دۅہہ گژھہِ پادٕرۍ کُنہِ دۅہہٕ سٍتـ̡ وُچھِتھ تہٕ یێلہ تیلہِ کرِ پادٕرۍ أمِس پاک قرار: تہٕ سُہ کرِ پَنٕنۍ پلو چھلنہٕ، تہٕ صاف روزُن۔\n35.\\tمگر اگر صاف کرنہ پتہ مسلس منز واریاہ پھہلِتھ آسہِ۔\n36.\\tتیلہِ گژھہِ پادٕرۍ أمِس وُچھِن: تہٕ وُچھِو، یێلہِ ژٔلِس مَس مَنٛز پھٔہلِتھ آسہِ، پادٕرۍ گژھِ نہٕ لیوٚدُر مَس ژھاران۔ سُہ {چُھ} ناپاک۔\n37.\\tمگر اگر کُنہِ جایہ یُس کُنہِ ساعتہ تٔمۍ سٕندِس نظرس منز آسہِ، تہٕ {یہ} آسہِ اَتھ منز کرٛیٚہنہِ مَس کھسنہٕ آمُت۔ سُہ چُھ ٹھیٖک گومُت، سُہ چُھ صاف گومُت: تہٕ پادٕرۍ کرِ أمِس پاک قرار۔\n38.\\tاگر کٲنسہِ مردس یا زنانہِ ہندس مازس منز چمکدار داغ آسن، {حتیٰ کہ} سفید چمکدار داغ۔\n39.\\tتیلہِ گژھہِ پادٕرۍ وُچھان: تہٕ وُچھِو، {اگر} تِہندِ مازٕ کِس مسلس مَنٛز چمکدار داغ آسن سیاہ سفید۔ یہِ {چھُ} اکھ داغدار داغ {یُس} مسلس منز کھسان چھُ؛ سُہ {چُھ} صاف۔\n40.\\tتہٕ یٔمۍ سٕندِس کَلہٕ سٍتـ̡ مَس پٔرِتھ چُھ، سُہ چُھہ ٹَکُل آسان۔ {توتہِ} چھُ سُہ صاف ۔ {مس ...: ہیب۔ کلہٕ چُھ پِلڈ}\n41.\\tتہ یُس پننس کلہ پیٹھہ بُتھِس کُن مَس والہِ کُن وُچھِتھ آسہِ، سہ چھہ ڈٮ۪کہٕ کُنہِ\n42.\\tتہ اگر مس کلس یا مس ڈٮ۪کس منز آسہِ، تیلہِ چھہ سفید۔ یہِ چھُ تٔمۍ سٕنٛدِس ٹَکلہٕ کَلس یا تٔمۍ سٕنٛدِس ٹَکلہٕ ڈٮ۪کَس منٛز پٲدٕ گٔمٕژ کوڑھ۔\n43.\\tتیلہِ گژھہِ پادٕرۍ اتھ وُچھان: تہٕ وُچھِو، یێلہِ تٔمۍ سٕندِس گنج کلس منز، یا تٔمۍ سٕندِس ٹَلہٕ ڈٮ۪کہٕ منز، یِتھٕ پٲٹھۍ کوڑھ مازٕ کِس مسلس منز ظٲہر سپدِ۔\n44.\\tسُہ چُھ کوڑھ انسان، سُہ چُھ ناپاک قرار دِنہٕ آمُت: پادٕرۍ کرِ أمِس سراسر ناپاک قرار۔ تٔمۍ سُند طاعون {چُھ} تٔمۍ سٕنٛدس سرس منٛز۔\n45.\\tتہٕ یٔمِس کوڑھ یٔمِس مَنٛز طاعون چُھ، تٔمِس پَلَو پھٔٹِتھ تہٕ کلہٕ نٮ۪بر تہٕ سُہ کرِ پننِس پیٹھمِس وٕٹھس پیٹھ پردٕ تہٕ کرِ ناپاک، ناپاک۔\n46. تِمن سارِنٕے دۅہن یێلہِ تس مَنٛز طاعون آسہِ، سُہ گژھہِ ناپاک کرنہٕ۔ سُہ چُھہ ناپاک: سُہ روزِ کُنی زُن۔ کیمپ ورٲے {شال} تٔمۍ سٕنز رہائش گاہ {be}۔\n47.\\tیہ پوشاک تہِ چھہ کوڑھ ہُند وبا تہِ، {چاہے سہ اونُک پلو آسہِ، یا کُنہِ کُنہِ پوشاک۔\n48.\\tیہ آسہِ وارس منز، یا ووف۔ کتانُک، یا اونُک؛ چاہے ژمہِ منز، یا کُنہِ تہِ چیزس منز؛ {چیز...: ہیب۔ کامہِ ہُند کامہِ}\n49.\\tتہٕ اگر طاعون پوشس منز، یا مسلس منز، یا وُپھس منز، یا کُنہِ تہِ چیزس منز، یا وُپھ منز، یا کُنہِ تہِ چیزس منز؛ یہِ {چُھ} کوڑھُک وبا، تہٕ یِیہِ پادٕرِس ہاونہٕ یُن: {چیز: ہیب۔ برتن، یا، آلہٕ}\n50.\\tتہٕ پادٕرۍ وُچھِن طاعون وُچھِتھ سَتھ دۅہہٕ بند کٔرِتھ:\n51.\\tتہٕ سُہ گژھہِ سٔتِمہِ دۅہہ طاعون وُچھان: اگر یہ طاعون پوشس منز، یا وُپھ منز، یا کُنہِ تہِ کامہِ منز، یُس ژمہِ سٍتـ̡ آسہِ۔ طاعون {چُھ} اکھ پریشان کوڑھ؛ یہِ {چھُ} ناپاک۔\n52.\\tامہ کنۍ گژھہِ سُہ پلو زالُن، چاہے وُپھ آسہِ یا وُپھ آسہِ، ییرِ سٍتـ̡ یا کُنہِ تہِ ژمہِ سٍتـ̡ ، یتھ منز طاعون آسہِ: تکیازِ یہِ چُھہ اکھ کوڑھ ۔ یہ گژھہِ نارس منز زالنہٕ۔\n53.\\tتہٕ اگر پادٕرۍ وُچھِ، تہٕ وُچھِو، وُپھ گژھہِ نہٕ پلوس منز، نہ وُپھ منز، یا کُنہِ تہِ مسلس منز۔\n54. تیلہِ کرِ پادٕرۍ حکم زِ تِم گژھن سُہ چیز چھلناوُن یتھ منز طاعون {چُھ} چُھ، تہٕ سُہ کرِ سَتھ دۅہہٕ بند کرنہٕ۔\n55.\\tتہٕ پادٕرۍ گژھہِ طاعون وُچھان، تمہ پتہ ییہ یہ واش کرنہٕ: تہٕ وُچھِو، {یێلہِ} طاعون ہُند رنگ بدلیوو نہٕ، تہٕ طاعون گژھہِ نہٕ پھٔہلِتھ۔ یہِ {چُھ} ناپاک ؛ ژے دِیُن یہِ نارس منز زالُن۔ یہ {چُھ} اندرمس کُن پریشان چُھ، {کیا چُھ} یہٕ {be} اندرٕ یا نیبر ننگہٕ۔ {کیا...: ہیب۔ چاہے سہ کلس منز گنج آسہِ، یا امہِ کس ڈیکس منز}\n56.\\tتہٕ اگر پادٕرۍ وُچھِتھ وُپھ کُنہِ حدس تام سیاہ گٔژھِتھ۔ تیلہ کرِ سہ پلو منز، یا ژمہِ منز، یا وارہ منز، یا واو منزہ نیبر۔\n57.\\tتہِ اگر یہ وُنہِ تہِ پلوس منز، یا وُپھس منز، یا کُنہِ تہِ مسلس منز؛ یہِ {چُھ} اکھ پھٔہلِتھ {طاعون}: ژے زٲلِو سُہ یَتھ مَنٛز طاعون {چُھ} نارٕ سٍتـ̡ دِنہٕ آمُت۔\n58.\\tتہٕ سُہ پلو، یا وُپھ، یا وُپھ، یا یُس تہِ ژیہ واش کرُن، یُس تِمن نِش واش گژھہِ، تیلہِ گژھہِ دوٚیمہِ لٹہِ چھلنہٕ یُن، تہٕ گژھہِ صاف کرنہٕ۔\n59.\\tیہِ چُھ کوڑھ ہٕندِس وباہُک قانون یُس اونُک یا کُنہِ تہِ کُنہِ چیزس مَنٛز چھُ، یُس صاف قرار دِنہٕ خٲطرٕ یا ناپاک قرار دِنہٕ خٲطرٕ۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. یہِ آسہِ کوڑھ سُند قانون تٔمۍ سٕندِس پاکیزگی ہٕندِس دۅہٕ سٍتـ̡ یُس پادٕرِس نِش اننہٕ یُن:\n3. تہٕ پادٕرۍ گژھِ خٲمہٕ منزٕ نیبر۔ تہٕ پادٕرۍ گژھہِ وُچھان، تہٕ وُچھِو، {اگر} کوڑھِس مَنٛز گژھہِ کوڑھُک وبا ٹھیک کرنہٕ۔\n4.\\tتیلہِ کرِ پادٕرۍ حُکُم زِ یُس زٕ جاناوار زِندٕ صاف کرُن، تہٕ دِودار لٔکرِ تہٕ سرخ تہٕ ہِسپ نِنُک حُکُم: {جاناوار: یا، چُرۍ}\n5.\\tتہٕ پادٕرۍ دِیہِ حکم زِ جاناوارو منزٕ گژھہِ اکھ جاناوار وسان آبس پیٹھ میژِ بانس منز مارنہٕ۔\n6.\\tزندٕ جاناوار سُہ رٔٹِتھ تہٕ دِودار لٔکرِ تہٕ سُہ رٔٹِتھ تہٕ یُس جاناوار سٕندِس خونس مَنٛز ڈباونہٕ یُس وسوُن آبس پیٹھ مارنہٕ آمُت اوس۔\n7. تہٕ سُہ کرِ سَتھ لٹہِ کوڑھ نِش صاف گژھن وٲلِس پیٹھ چھُکُن، تہٕ کرِ أمِس پاک قرار دِنہٕ، تہٕ زندٕ جاناوار یلہٕ کھٲلہٕ مٲدانس مَنٛز یلہٕ تراوُن۔ {into...: Heb. میدان کس بُتھس پیٹھ}\n8. یُس پاک گژھُن چُھ، سُہ گژھہِ پَنُن پلو چھلُن، تہٕ سٲرۍسٕے مَس کٔرِن تہٕ پان آبہٕ سٍتـ̡ چھلناوُن، یُتھ سُہ پاک روزُن، تہٕ اَمہِ پتہٕ گژھہِ سُہ خٲمس مَنٛز یِنہٕ، تہٕ سَتن دۅہن روزِ خیمہ منزٕ نیبر۔\n9. مگر سٔتِمہِ دۅہہٕ گژھہِ سُہ پَنٕنِس کَلہٕ تہٕ داڑھ تہٕ اچھن ہٕندِس سارِنٕے مَس کھوٗر کرِ، تہٕ سُہ کرِ پَنُن پَنُن ماز آبہٕ سٍتـ̡ چھلناوُن، تہٕ سُہ گژھہِ صاف روزُن۔\n10.\\tتہٕ ٲٹھمہِ دۅہہ نِن زٕ کۅکرِ بچہٕ تہٕ گۅڈنچہ ؤریُک اکھ دانٛد بچہٕ تہٕ تریہ دٔہِم دٔہمہِ دۅہہٕ نِش نِنہٕ خٲطرٕ، یُس تیٖلس سٍتـ̡ رلاونہٕ آمُت چُھ، تہٕ اکھ لوٚگ تیٖل۔ {منز...: ہیب۔ پننہ ؤرۍ یچ کوٗر}\n11.\\tیُس پادٕرۍ یُس پاک کرُن چُھ، سُہ کرِ خداوند سٕندِس برونہہ کُن یُس پاک کرُن، تہٕ تِم چیز کرِ خداوند سٕندِس برونہہ کُن، جماعت کِس خیمہ کِس دروازس پیٹھ:\n12. تہٕ پادٕرۍ رٔٹِتھ تہٕ تٔمِس کُنہِ\n13. تہٕ سُہ کٔرِن کۅپہٕ کُن نذرانہ تہٕ زالنہٕ نذرانہٕ مُقدس مقامس مَنٛز، یێلہِ پٲٹھـ̡ گۅناہ ہُند نذرانہ {چُھ} پادٕرۍ سُند، تِتھے پٲٹھـ̡ چُھہ پادٕرِ سُند نذرانہ {چُھ} تہٕ یێلہِ چُھہ {پاک} ۔\n14.\\tتہٕ پادٕرۍ رٔٹِتھ دٔچھنِس دٔچھنِس کَنس پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ ہٕندِس کھورِ پیٹھ۔\n15.\\tتہٕ پادٕرۍ نِیہِ تیلُک لوٚگ {کینٛہہ} تہٕ تراوُن پننِس کھوورِ اتھہٕ کِس اتھس منز:\n16. تہٕ پادٕرۍ دٔچِھنہِ اوٚنٛگجہِ تیٖلس مَنٛز یُس کھوورِ اتھس مَنٛز چُھہ، تہٕ سَتھ لٹہِ چُھکھ تیلُک اوٚنگجہِ سٍتـ̡ خداوند سٕندِس برونہہ کُن چُھکُن:\n17. تہٕ باقی تیٖل یُس تٔمۍ سٕندِس اتھس منز چُھہ یُس صاف کرُن چُھ، تہٕ دچھنہِ اتھہٕ کِس اوٚنگجہِ پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ ہٕندِس بٔڈِس کھورِ پیٹھ، ناجائز قربانی ہٕندِس خونس پیٹھ:\n18.\\tتہٕ یُس تیٖل پادٕرۍ سٕندِس اتھس مَنٛز چُھہ یُس پاک گژھن وٲلِس سٕندِس کلس پیٹھ تراوُن، تہٕ پادٕرۍ کرِ خداوند سٕندِ برونہہ کُن تٔمِس خٲطرٕ کفارہٕ۔\n19. تہٕ پادٕرۍ کرِ گۅنہٕ نِشہ نذرانہ پیش تہٕ یُس تٔمِس سٕندِ ناپاکی نِش پاک گژھُن آسہِ۔ تہٕ امہ پتہٕ کرِ سُہ دزنہٕ نذرانہ مارُن:\n20. تہٕ پادٕرۍ کرِ قربان گاہس پیٹھ دزنہٕ نذرانہ تہٕ مازٕچ نذرانہ پیش کرنہٕ۔ تہٕ پادٕرۍ کرِ أمِس خٲطرٕ کفارہٕ، تہٕ سُہ گژھہِ پاک کرنہٕ۔\n21. تہٕ اگر سُہ غریب آسہِ، تہٕ یوتاہ ہیکہِ نہٕ حٲصل کٔرِتھ۔ تیلہٕ نِیہِ سُہ اکھ کٹہٕ بچہٕ یُس تٔمِس خٲطرٕ کفارہ دِنہٕ خٲطرٕ تہٕ ماز کِس نذرانہ خٲطرٕ تیٖلس سٍتـ̡ رلاونہٕ خٲطرٕ دٔہِم دٔہِم آٹہٕ تہٕ تیلُک اکھ لوٚگ نِنہٕ۔ {ہیکن نہ...: ہیب۔ تٔمۍ سُند اَتھٕ ووت نہٕ} {to be...: Heb. لہراونہٕ خٲطرٕ}\n22. تہٕ زٕ کچھو، یا زٕ جوان کبوتر، یِتھ زن أمِس حٲصِل کٔرِتھ۔ تہٕ اکھ آسہِ گۅناہ ہُند نذرانہ تہٕ بیٛاکھ زٲلِتھ قربانی۔\n23. تہٕ سُہ اَنِہ تِم ٲٹھمہِ دۅہٕ پادٕرِس نِش، جماعت کِس خیمہ کِس دروازس تام، خداوند سٕندِس برونہہ کُن۔\n24.\\tتہٕ پادٕرۍ رٔٹِتھ رٔٹِتھ تہٕ تیٖلُک لوٚگ تہٕ پادٕرۍ یِم خداوند سٕندِ برونہہ کُن لہراوُن:\n25.\\tتہٕ سُہ کرِ ناجائز قربانی ہٕندِس کۅکرس مٲرِتھ، تہٕ پادٕرۍ رٔٹِتھ دٔچھنِس دٔچھنِس کَنس پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ ہٕندِس کھورِ پیٹھ۔\n26. تہٕ پادٕرۍ تراوِ تیٖل پننِس کھوورِ اتھس مَنٛز۔\n27.\\tتہٕ پادٕرۍ دٔچِھنہِ اونگجہِ سٍتـ̡ یُس تیٖلُک {چُھ} کھوورِ اتھس مَنٛز سَتھ لٹہِ چُھکُن:\n28.\\tتہٕ پادٕرۍ یُس تیٖل پننِس اتھس منز چُھہ یُس صاف گژھن وٲلِس دٔچھنِس کنس پیٹھ تہٕ دچھنہِ کھورِ ہٕندِس کھورِ ہٕندِس کھورِ پیٹھ، دٔچھنِس کھورِ ہٕندِس کھورِ پیٹھ، ناجائز قربانی ہٕندِس خونس پیٹھ:\n29. تہٕ باقی تیٖل یُس پادٕرۍ سٕندِس اتھس مَنٛز چُھ، سُہ چُھ تٔمِس سٕندِس کلس پیٹھ تھووُن یُس پاک گژھُن چُھ، یُس خداوند سٕندِس برونہہ کُن کفارہ دِنہٕ خٲطرٕ۔\n30.\\tتہٕ سُہ کرِ کچھوَن منزٕ اَکھ یا کۅترن ہُند یُتھ أمِس مِلِتھ آسہِ۔\n31.\\tیُتھ تہِ یُس سُہ حٲصل کرِ، اَکھ {خٲطرٕ} گۅنہٕ نِش نذرانہ تہٕ بیٛاکھ {خٲطرٕ} دزنہٕ خٲطرٕ، مازٕچ نذرانہ سٍتـ̡ تہٕ پادٕرۍ کرِ تٔمِس سٕندِ خٲطرٕ کفارہٕ یُس خداوند سٕندِ برونہہ کُن پاک گژھُن آسہِ۔\n32.\\tیہِ {چُھ} شریعت {تٔمِس} یٔمِس مَنٛز {چُھ} کوڑھ ہُند طاعون چُھ، یٔمۍ سٕندِس اتھس منز چُھ نہٕ تٔمۍ سٕندِس پاکیزگی سٍتـ̡ {سُہ یُس} حٲصل سپدِتھ ہیکان۔\n33. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n34. ییلہ تہۍ کنعان کِس سرزمینس منز یُس بہٕ ژے قبضہ کرنہٕ خٲطرٕ دِوان چھُس، تہٕ بہٕ تراوُن کوڑھُک وبا تُہنزِ زمینہِ ہٕندِس أکِس مکانس منز۔\n35.\\tیُس گرُک مٲلک آسہِ سُہ گژھہِ یِتھ پادٕرِس ونُن، یہِ چُھہ میہ باسان زِ یہ چُھہ گرس مَنٛز وُپھ وُپھ گومُت:\n36. تیلہِ کرِ پادٕرۍ حکم زِ تِم گژھن گرٕ خٲلی کرُن، امہ برونہہ زِ پادٕرۍ گژھِ وُپھ وُچھنہٕ مۅکھہٕ، یُتھ گرس مَنٛز موجود سورُے {چُھ} گژھِ نہٕ ناپاک کرنہٕ یُن: تہٕ امہِ پتہٕ گژھِ پادٕرۍ گرٕ وچھنہٕ خٲطرٕ: {خٲلی: یا، تیار کرُن}\n37.\\tتہٕ سُہ وُچھِتھ وُچھان تہٕ وُچھِتھ گَرِ ہٕندِس دیوارس مَنٛز وُپھ آسہِ، سبز یا وۄزل رَنٛگہٕ سٍتۍ، یُس دیوارٕ کھۅتہٕ بۄن آسہِ۔\n38.\\tتیلہِ گژھہِ پادٕرۍ گَرٕ نیبر نیرِتھ گرٕ کِس دروازس کُن تہٕ سَتھ دۅہہٕ گَرٕ بند کرُن:\n39.\\tتہٕ پادٕرۍ یِیہِ سٔتِمہِ دۅہہٕ دُبارٕ یِنہٕ تہٕ وُچھِن: تہٕ وُچھِو، یێلہِ گَرٕ کِس دیوارس مَنٛز وُپھہِ۔\n40. تیلہِ کرِ پادٕرۍ حکم زِ تِم کٔنۍ نِن یِمن مَنٛز طاعون چُھ، تہٕ تِم تراوُن شہرٕ نیبر ناپاک جایہ۔\n41.\\tتہٕ سُہ کٔرِن گرٕ اندۍ کھٔٹِتھ تہٕ تِم ترٲوِن سُہ گرد یُس تم شہرٕ ورٲے کُنہِ ناپاک جایہِ کڈِتھ چھِ۔\n42. تہٕ تِم نِن باقٕے کٔنہِ، تہٕ تِمن کٔنِن ہٕنزِ جایہِ تھاوٕنۍ۔ تہٕ سُہ رٔٹِتھ بیاکھ مورٹر تہٕ گرٕ کرِ رٔٹِتھ۔\n43. تہٕ یێلہِ دُبارٕ وُپھ یِیہِ تہٕ گَرَس مَنٛز پھُٹِھ، تَمہِ پَتہٕ کٔرِن سُہ کٔنہِ کٔرِتھ، تہٕ گرٕ ژٔٹِتھ تہٕ ژٔٹِتھ دِنہٕ پتہٕ۔\n44.\\tتیلہِ گژھہِ پادٕرۍ یِتھ وُچھِتھ وُچھِتھ تہٕ وُچھِتھ یێلہِ گَرَس مَنٛز وُپھہٕ وُچھِ، یہِ چُھہ گَرَس مَنٛز کوڑھ بێیہِ۔\n45.\\tتہٕ سُہ پھُٹراوُن گر، اَمہ کِس کٔنہِ تہٕ اَمہ کِس لٔکرِ تہٕ گرُک سارِنٕے گَرٕ پھُٹراوُن۔ تہٕ سُہ نِیہِ شہرٕ منزٕ نیبر کُنہِ ناپاک جایہِ کُن۔\n46.\\tیُس گرس منز اژان آسہِ، یُس اتھ گرس منز بند روزِ، سُہ گژھہِ ناپاک روزُن۔\n47.\\tیُس گرس منز روزان آسہِ سُہ گژھہِ پَنُن پلو چھلُن۔ تہٕ یُس گرس مَنٛز کھٮ۪وان چُھ، سُہ کرِ پَنٕنۍ پلو چھلنہٕ۔\n48.\\tتہٕ یێلہِ پادٕرۍ اژِتھ تہٕ وُچھِتھ وُچھِتھ گَرَس مَنٛز پھٔہلِتھ وُچھُن، تێلہِ گژھہِ پادٕرۍ گَرٕ صاف قرار دِنہٕ، تِکیازِ طاعون چھُ شفا گومُت۔ {گژھہِ یِن...: ہیب۔ اَتھ منز یِنہٕ وغیرہ}\n49. تہٕ سُہ نِیہِ گرٕ صاف کرنہٕ خٲطرٕ زٕ جاناوار، تہٕ دیودار لٔکر، تہٕ سرخ تہٕ ہِسپ۔\n50. تہٕ سُہ مارِ میژِ بانس منز جاناوار یُس وسوُن آبس پیٹھ۔\n51.\\tتہٕ سُہ رٔٹِتھ کٔرِن کُنہِ جاناوار سٕندِس خونس مَنٛز، تہٕ وسوُن آبس مَنٛز، تہٕ گرس سَتھ لٹہِ چھُکُن۔\n52. تہٕ سُہ کرِ جاناوار سٕندِ خونہٕ سٍتـ̡ تہٕ وسان آبہٕ سٍتـ̡ تہٕ زندٕ جاناوارٕ سٍتـ̡ تہٕ دیودار لٔکرِ سٍتـ̡ تہٕ سرخ سٍتـ̡ گَرٕ صاف کرُن:\n53. مگر سُہ تراوِ زندٕ جاناوار شہرٕ منزٕ کھُلہٕ کھاہن مَنٛز، تہٕ گَرٕ کَرُن کفارہٕ، تہٕ سُہ گژھہِ پاک۔\n54.\\tیہ چھہ کوڑھ تہ سکیلہ چہ پریتھ قسمہ چہ وباہن ہند قانون\n55. تہٕ پوشہٕ تہٕ گرٕ کِس کوڑھ خٲطرٕ،\n56.\\tتہٕ وۅتھنہٕ خٲطرٕ، تہٕ أکِس کھورِ خٲطرٕ، تہٕ أکِس روشن مقامہٕ خٲطرٕ:\n57.\\tیہ ہیچھناوُن ییلہ {یہ} ناپاک چُھ، تہٕ ییلہ {یہ} صاف آسہِ: یہ {چُھ} کوڑھُک قانون۔ {ییلہ یہ ناپاک آسہِ...: ہیب۔ ناپاک سٕندِس دۅہس منز، تہٕ پاکیزگی ہٕندِس دۅہس منز}","1. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ کرنہٕ،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، یێلہِ کٲنسہِ شخصہٕ سٕندِس ماز سٍتـ̡ نیرُن آسہِ، سُہ چُھ ناپاک آسان۔ {دوڑان...: یا، رننگ آف دی رینس}\n3.\\tتہٕ یۅہے گژھہِ تٔمۍ سٕندِس مسلس مَنٛز ناپاکی: چاہے تٔمۍ سُند ماز تٔمۍ سٕندِس مسلس سٍتـ̡ رُکاونہٕ یُن، سُہ چُھہ تٔمۍ سُند ناپاکی۔\n4. پریتھ کانہہ بسترہ یتھ پیٹھ سہ بِہتھ آسہِ، سُہ چھہ ناپاک تہ پریتھ کانہہ چیز یتھ پیٹھ سہ بِہتھ آسہِ، سُہ گژھہِ ناپاک آسان۔ {چیز: ہیب۔ جہاز}\n5.\\tیُس تہِ پننِس بسترس اَتھٕ لاگہِ سُہ گژھہِ پَنُن پلو چھلناوُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سرٛان، تہٕ سُہ روزِ ناپاک روزُن۔\n6.\\tیُس کُنہِ تہِ چیزس پیٹھ بِہتھ آسہِ، سُہ گژھہِ پَنُن پلو چھلُن، تہٕ پانس آبہٕ سٍتـ̡ سنان تہٕ سُہ روزِ ناپاک روزُن۔\n7.\\tیُس یُس أمِس ماز اَتھٕ لاگان آسہِ، سُہ گژھہِ پَنُن پلو چھلُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سرٛان، تہٕ سُہ روزِ ناپاک روزُن۔\n8. تہٕ یێلہِ یێلہِ یُس مسلہٕ آسہِ تٔمِس سٍتـ̡ تھوکُن یُس پاک آسہِ۔ تمہ پتہ گژھہِ سُہ پَنٕنۍ پلو چھلنہٕ، تہٕ پانس آبہٕ سٍتـ̡ سرٛان، تہٕ یێلہِ تام روزِ ناپاک۔\n9.\\tتہِ کُنہِ تہِ زین سٍتـ̡ سُہ چُھہ ناپاک آسہِ۔\n10.\\tیُس تہِ تس تل کُنہِ چیزس اتھہٕ لاگہِ سُہ گژھہِ ناپاک روزُن، تہٕ یُس یُس یِمن چیزن منز کانہہ تہِ چیز رٔٹِتھ آسہِ، سُہ گژھہِ پَنُن پلو چھلناوُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سرٛاوُن، تہٕ یێلہِ تام روزِ ناپاک روزُن۔\n11.\\tتہٕ یُس تہِ یُس اَتھ سٍتـ̡ اَتھٕ چھلناوُن آسہِ، سُہ کرِ پَنٕنـ̡ پَنٕنـ�\n12. تہٕ زمینہِ ہُند بانہٕ یُس سُہ اتھہٕ لاگان چُھ، سُہ گژھہِ پھُٹُن، تہٕ لٔکرِ ہُند پرٮ۪تھ کانہہ بانہٕ گژھہِ آبہٕ سٍتـ̡ چھلنہٕ یُن۔\n13.\\tتہٕ یێلہِ یێلہِ یُس مسلہٕ آسہِ سُہ چُھہ پننِس مسلہٕ نِش پاک سپدان۔ اَمہِ پَتہٕ کرِ سُہ پانَس سَتھ دۅہہٕ گٔژھِتھ صاف کرنہٕ خٲطرٕ، تہٕ پَنٕنۍ پلو چھلناوٕن، تہٕ پَنُن ماز وَسنہٕ آبہٕ سٍتـ̡ سرٛاوُن، تہٕ گژھہِ صاف روزُن۔\n14. تہٕ ٲٹھمہِ دۅہہٕ نِیہِ سُہ پانس نِش زٕ کچھو، یا زٕ کۅتر تہٕ خداوند سٕندِ برونہہ کُن یِنہٕ جماعت کِس خیمہ کِس دروازس پیٹھ، تہٕ یِم پادٕرِس دِنہٕ۔\n15. تہٕ پادٕرۍ دِیہِ تِمن پیش کرنہٕ، اَکھ گۅنہٕ خٲطرٕ، تہٕ بیٛاکھ دَزنہٕ خٲطرٕ۔ تہٕ پادٕرۍ کرِ تٔمِس سٕندِ خٲطرٕ خداوند سٕندِ خٲطرٕ کفارہٕ۔\n16.\\tتہٕ یێلہِ کٲنٛسہِ ہٕندِس ماز سٍتـ̡ نِش نیرِ، سُہ گژھہِ پنُن سورُے ماز آبہٕ سٍتـ̡ واش کٔرِتھ، تہٕ روزِ ناپاک روزُن۔\n17.\\tتہٕ پرٮ۪تھ کُنہِ پوشہٕ تہٕ پرٮ۪تھ کُنہِ کھالہٕ یَتھ پیٹھ مَضموٗن ہُند بیول آسہِ، گژھِ آبہٕ سٍتـ̡ چھلنہٕ یُن، تہٕ یێلہِ تام گژھہِ ناپاک روزُن۔\n18.\\tسۅ زنانہِ تہِ یٔمِس سٍتـ̡ مرد سٍتـ̡ رٔلِتھ روزِ، تِم گژھن آبہٕ سٍتـ̡ سرٛان کٔرِتھ، تہٕ یێلہِ تام ناپاک روزُن۔\n19. تہٕ اگر زنانہِ کانہہ مسلہ آسہِ، تہٕ تٔمۍ سٕندِس مازس مَنٛز خون آسہِ، سُہ گژھِ ستن دۅہن الگ تھاونہٕ یُن، تہٕ یُس تہِ أمِس اتھہٕ لاگہِ سُہ گژھہِ ناپاک روزُن۔ {پُٹ...: ہیب۔ تٔمۍ سٕنٛدِس جدایی منٛز}\n20. تہٕ پریتھ چیز یُس سُہ جدایی منز روزِ، سُہ گژھہِ ناپاک تہٕ یُس چیز بِہِتھ آسہِ سُہ گژھہِ ناپاک تہِ۔\n21.\\tیُس تہٕ یُس تہٕ یُس تٔمۍ سٕندِس بسترس اَتھٕ لاگہِ سُہ گژھِ پَنُن پلو چھلناوُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سرٛان، تہٕ سُہ روزِ ناپاک روزُن۔\n22.\\tتہٕ یُس تہِ کُنہِ چیزس پیٹھ بِہتھ آسہِ، سُہ گژھہِ پَنُن پلو چھلُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سرٛان، تہٕ سُہ روزِ ناپاک روزُن۔\n23.\\tتہٕ اگر یہِ {تٔمِس} بسترس پیٹھ، یا کُنہِ تہِ چیزس پیٹھ یتھ پیٹھ سۄ بِہِتھ آسہِ، ییلہ سُہ اتھ اتھہٕ لاگہِ، سُہ گژھہِ ناپاک روزُن۔\n24. تہٕ اگر کانہہ مرد أمِس سٍتـ̡ روزِ، تہٕ تٔمِس پوش آسہِ، سُہ گژھہِ ستن دۅہن ناپاک روزُن۔ تہٕ سُہ سُہ بسترٕ یتھ پیٹھ سُہ بٔرِتھ آسہِ ناپاک آسُن۔\n25.\\tتہٕ اگر کُنہِ زنانہِ ہٕندِس جدایی ہٕندِس وقتس منزٕ واریاہ دۅہ خونُک مسلہٕ آسہِ، یا اگر یہ جدایی ہٕندِس وقتس پتہٕ روزِ۔ تٔمۍ سٕنزِ ناپاکی ہٕندِس سارِنٕے دۅہہٕ گژھن تٔمۍ سٕندِ جدایی ہٕندِس دۅہٕکۍ پٲٹھۍ: سۅ آسہِ ناپاک ۔\n26.\\tپریتھ بسترس یتھ پیٹھ سۅ پننہِ اولاد ہٕندِس سارِنٕے دۅہس پیٹھ روزِ، سُہ گژھہِ تٔمِس جدایی ہٕندِس بسترس ہٕندۍ پٲٹھۍ، تہٕ یُس تہِ بِہِتھ آسہِ سُہ گژھہِ ناپاک تہٕ تٔمۍ سٕنزِ جدایی ہٕندِ ناپاکیزگی ہٕندۍ پٲٹھۍ۔\n27.\\tیُس یِمن چیزن اتھہٕ لاگہِ سُہ گژھہِ ناپاک تہٕ پَنُن پلو چھلُن، تہٕ سُہ کرِ آبہٕ سٍتـ̡ سران تہٕ سُہ روزِ ناپاک روزُن۔\n28.\\tمگر یێلہِ سُہ پَنُن مسلہٕ نِش پاک گژھہِ، تیلہِ گژھہِ سَتھ دۅہہٕ پانس سٍتـ̡ گنزراونہٕ، تہٕ تمہ پتہٕ گژھہِ سُہ پاک۔\n29. تہٕ ٲٹھمہِ دۅہہ نِیہِ سُہ پننین دۅن کچھوَن نِش یا زٕ کۅتر نِتھ تہٕ یِم پادٕرِس نِش نِنہٕ یِنہٕ تہٕ جماعت کِس خیمہ کِس دروازس پیٹھ۔\n30.\\tتہٕ پادٕرۍ دِیہِ اَکھ گۅنہٕ نِش نذرانہ تہٕ بیٛاکھ دَزنہٕ خٲطرٕ۔ تہٕ پادٕرۍ کرِ تٔمِس خٲطرٕ خداوند سٕندِ خٲطرٕ کفارہٕ۔\n31. یِتھٕ پٲٹھـ̡ کٔرِو تُہۍ بنی اِسرٲیلِس تِہٕنزِ ناپاکی نِش الگ کٔرِو۔ زِ تِم چھِ نہٕ پننہِ ناپاکی سٍتـ̡ مَرٕن، یێلہِ تِم میانہِ خیمہ ناپاک کٔرِن یُس تِمن مَنٛز {چُھ} چُھ۔\n32.\\tیہِ چُھ تٔمِس سُند شریعت یُس اولاد آسہِ، تہٕ یٔمِس سٍتـ̡ یٔمِس سٍتـ̡ اولاد نیران چُھ، تہٕ اَمہ سٍتـ̡ ناپاک سپدِ۔\n33.\\tیُس پننہِ پوشہِ سٍتـ̡ بیمار آسہِ، تہٕ یُس مرد سُند تہٕ زنانہِ سٍتـ̡ تہٕ یُس أمِس سٍتـ̡ ناپاک آسہِ۔","1. تہٕ خداوند کٔر ہارون سٕندِ دون نیچوین ہٕندِ مرنہٕ پتہٕ موسیٰ سٕنز کتھ ییلہِ تِمو خداوند سٕندِ برونہہ کُن پیش کٔر، تہٕ مٔرۍ۔\n2. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ پننِس بٲیِس ہارونس سٍتـ̡ کتھ کرٕن، یُس نہٕ پریتھ ساتہٕ رحمتٕچ نشستہٕ برونہہ کُن مقدس مقامس مَنٛز یُس {چُھ} صندوقس پیٹھ آسان۔ سُہ چُھس نہٕ مَرُن: کیازِ بہٕ گٔیہٕ رحمتٕچ کرسی پیٹھ اوبرس منز ظٲہر۔\n3. یِتھٕ پٲٹھۍ گژھہِ ہارون مقدس مقامس مَنٛز: گۅنہٕ کِس نذرانہ خٲطرٕ اکھ جوان بیل تہٕ دزنہٕ خٲطرٕ اکھ مینڈٕ ہٮ۪تھ۔\n4.\\tسُہ لاگُن مُقدس کُن کوٹ، تہٕ تٔمِس گژھہِ پننِس مازس پیٹھ کُنہِ کُنہِ کُن لٲگِتھ، تہٕ یِمن ہٕندِس مِٹرس سٍتـ̡ لاگنہٕ یُن: یِم چھِ مقدس پوشاک۔ لہذا گژھہِ سہ پنن ماز آبہِ منز واش کرُن، تہ {یتھہ پاٹھۍ} لاگُن۔\n5. تہٕ سُہ کرِ بنی اسرٲیلِچ جماعت نِش گۅنہٕ نِش زٕ ژھاوٕنۍ تہٕ اکھ مینڈٕ زالنہٕ خٲطرٕ۔\n6. تہٕ ہارون کرِ پَنُن گۅنہٕ نذرانہٕ ہُند بیل یُس پانس خٲطرٕ {چُھ} چُھ، تہٕ کرِ پانس تہٕ پننِس گرس خٲطرٕ کفارہٕ۔\n7. تہٕ سُہ نِیہِ زٕ ژھاوٕل تہٕ یِم کرِ خداوند سٕندِس برونہہ کُن جمعہٕ کِس خیمہ کِس دروازس پیٹھ پیش۔\n8.\\tتہٕ ہارون دِیہِ دون ژھاوٮ۪ن پیٹھ لاٹ۔ اکھ لاٹ رب سٕندِ خٲطرٕ، تہٕ بیٛاکھ لاٹ قربٲنی ہٕندِ خٲطرٕ۔ {قربانی ہند بکرہ: ہیب۔ ازازل}\n9.\\tتہٕ ہارون اَن سُہ ژھاوُل یَتھ پیٹھ خداوند سُند لاٹ پیومُت اوس، تہٕ کرِ أمِس گۅنہٕ ہٕندِ قربانی دِنہٕ۔ {فیل: ہیب۔ گٔیہِ تھوٚد}\n10.\\tمگر یُس ژھاوُر یُس قربٲنی ہُند بکرٕ بنہٕ خٲطرٕ پییہ، یُس خداوند سٕندِس برونہہ کُن زندٕ پیش کرنہٕ یُن، أمِس سٍتـ̡ کفارہ دِنہٕ خٲطرٕ، {تہٕ} ییہِ أمِس بیابانس مَنٛز قربانی ہُند بکرٕ بناونہٕ خٲطرٕ دِنہٕ۔\n11.\\tتہٕ ہارون کرِ گۅنہہ ہٕندِ نذرانہ ہُند بیل یُس پانس خٲطرٕ {چُھ}، تہٕ کرِ پانس تہٕ پننِس گرس خٲطرٕ کفارہٕ، تہٕ کرِ گۅنہٕ نذرانہٕ ہُند بیل یُس پانس خٲطرٕ {چُھ}۔\n12.\\tتہٕ سُہ کرِ خداوند سٕندِس برونہہ کُن قربان گاہس پیٹھٕ نارٕکۍ دزنہٕ آمٕتۍ کولہٕ سٍتـ̡ بٔرِتھ اکھ سنسر تہٕ تٔمۍ سٕندِس اتھہٕ سٍتـ̡ مٔٹھۍ بُرِ سٍتـ̡ بٔرِتھ تہٕ اَننہٕ یِنہٕ والہِ دٔرِس منز۔\n13.\\tتہٕ سُہ تھاوِ خداوند سٕندِ برونہہ کُن نارس پیٹھ، یُتھ گوٲہی ہٕندِس رحمتُک اوٚبر آسہِ، یُس نہٕ مَرُن:\n14.\\tتہٕ سُہ دِیہِ بیلُک خوُن، تہٕ دِیہِ رحمتٕچ کرسی مشرقس کُن اونگجہِ سٍتـ̡ چُھک۔ تہٕ رحمتٕچ کرسی برونہہ کُن گژھِ سَتھ لٹہِ پننہِ اونگجہِ سٍتۍ خونُک چھُکُن۔\n15.\\tتیلہِ کرِ سُہ گۅنہٕ نذرانہٕ ہُند ژھاوُر، یُس لُکن ہٕندِ خٲطرٕ چُھ، تہٕ تٔمِس خونس سٍتـ̡ یُس تٔمۍ بیلہٕ سٕندِس خونس سٍتـ̡ کورمُت اوس، تہٕ رحمتٕچ کرسی برونہہ کُن چھُکُن:\n16.\\tتہٕ سُہ کرِ مقدس مقامہٕ خٲطرٕ کفارہٕ، یُس بنی اسرٲیلِچ ناپاک آسنہٕ کِنۍ، تہٕ تِہندِ سارِنٕے گۅنہہ سٍتـ̡ تہندِس سارِنٕے گۅنہٕ سٍتـ̡ تہٕ یِتھٕ پٲٹھـ̡ کرِ سُہ جماعت ہٕندِس خیمہ خانہٕ خٲطرٕ، یُس تِمن مَنٛز تہندِس ناپاکیزگی منز روزان چُھ۔ {باقی: ہیب۔ بستی }\n17. تہٕ یێلہِ سُہ مُقدس مقامس مَنٛز کفارہ دِنہٕ خٲطرٕ اژِہ، یوتام نہٕ سُہ نیبر نیرِ، تہٕ پننِس گرس تہٕ سارِنٕے اسرٲیلِچ جماعت خٲطرٕ کفارہ کرِ۔\n18. تہٕ سُہ گژھِ خداوند سٕندِس برونہہ کُن قربان گاہس پیٹھ یُس {چُھ} چُھ، تہٕ کرِ اَمہِ خٲطرٕ کفارہٕ۔ تہٕ داندِ سُند خون، تہٕ ژھاوٕرِ ہُند خون، تہٕ تھووُن اندۍ پکھۍ قربان گاہ ہٕندِس سینگس پیٹھ۔\n19. تہٕ سُہ کرِ سَتھ لٹہِ پننہِ اونگجہِ سٍتـ̡ اتھ پیٹھ خوُن چھُکُن، تہٕ کرِ یہِ صاف تہٕ بنی اِسرٲیلِچ ناپاکی نِش پاک کرُن۔\n20. تہٕ یێلہِ سُہ مُقدس، تہٕ جمٲژ ہٕندِس خیمہ تہٕ قربان گاہُک صلح ختم کرِ، سُہ اَنِہ زندٕ ژھاوٕل:\n21.\\tتہٕ ہارون تھاوِ پنٕنۍ دۅشوے اتھہٕ زندٕ ژھاوٕرِ ہٕندِس کلس پیٹھ، تہٕ کرِ أمِس سٍتـ̡ بنی اِسرٲیلـ̡ سٕندِس سارِنٕے گناہوں ہُند اقرار تہٕ تِمن ہٕندِس سارِنٕے گۅناہَن ہُند اقرار کرُن، تہٕ سُہ کرِ أکِس لایق شخصہٕ سٕندِس اتھہٕ سٍتـ̡ بیابانس مَنٛز۔  {اکھ فٹ...: ہیب۔ موقعُک انسان}\n22. تہٕ ژھاوٕل گژھِ تِمن ہٕندِس سارِنٕے گُناہ تٔمِس سٍتـ̡ یُس نہٕ آباد آسہِ، تہٕ سُہ تراوِ ژھاوٕل بیابانس مَنٛز۔ {نہ...: ہیب۔ علیحدگی ہُند}\n23.\\tتہٕ ہارون گژھہِ جماعت کِس خیمہ خانس مَنٛز، تہٕ یُس سُہ مقدس مقامس مَنٛز گژھنہٕ وِزِ لٲگِتھ لٲگِتھ تہٕ تراوُن تتہِ۔\n24. تہٕ سُہ کرِ پنُن ماز پاک جایہِ آبہٕ سٍتـ̡ واش کٔرِتھ، تہٕ پَنٕنہِ پَنٕنـ̡ دِنہٕ آمُت تہٕ لُکن ہٕندِ خٲطرٕ کفارہٕ دِیہِ۔\n25.\\tتہٕ گۅنہٕ نذرانہٕ ہُند چربی گژھہِ قربان گاہس پیٹھ زالنہٕ۔\n26.\\tیُس ژھاوُل یُس قربانی ہٕندِ خٲطرٕ تراوُن سُہ گژھہِ پَنُن پلو چھلناوُن، تہٕ پَنُن ماز آبہٕ سٍتـ̡ سنان تہٕ پتہٕ گژھہِ خٲمس مَنٛز۔\n27.\\tتہٕ گۅناہ ہٕندِس نذرانہ خٲطرٕ، تہٕ ژھاوٕل {خٲطرٕ} گۅنہٕ نذرانہٕ خٲطرٕ، یٔمۍ سُند خون مقدس {جایہ} کفارہ کرنہٕ خٲطرٕ آو اننہٕ، سُہ گژھہِ خٲمہٕ ورٲے نِنہٕ۔ تہٕ تِم دزِن نارس مَنٛز پنٕنۍ کھالہٕ، تہٕ پنُن ماز تہٕ گُبر۔\n28.\\tیُس یُس یِم زٲلِتھ دِیہِ سُہ پَنُن پلو چھلناوُن، تہٕ سُہ گژھہِ آبہٕ سٍتـ̡ پنُن ماز آبہٕ سٍتـ̡ سرانہٕ، تہٕ اَمہِ پتہٕ ییہِ سُہ خٲمس مَنٛز۔\n29.\\tتہٕ {یہ} آسہِ تۅہہِ خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون: {یُس} سٔتِمہِ ریتس منز، دٔہمہِ دۅہ، تہٕ کُنہِ تہِ کامہِ کٔرِو نہٕ، {چاہے سُہ پنُن ملکُک کانہہ آسہِ، یا کانہہ اجنبی آسہِ یُس توے منزٕ روزان آسہِ:\n30. تکیازِ تمہِ دۅہہ کرِ پادٕرۍ تۅہہِ خٲطرٕ کفارہٕ، یُس تۅہہِ پاک کرنہٕ خٲطرٕ، یُتھ تۅہہ خداوند سٕندِ برونہہ کُن پنٕنـ̡ تمام گۅنہو نِش پاک گٔژھِو۔\n31.\\tیہ گژھہِ تۅہہِ خٲطرٕ آرام دِنُک سبت تہٕ تۅہہِ گژھہِ پنٕنـ̡ روحس ہمیشہٕ خٲطرٕ دِنہٕ۔\n32.\\tتہٕ پادٕر، یُس سُہ مسح کرِ، تہٕ یُس سُہ پننِس مٲلہِ سٕندِ بدلہٕ پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرنہٕ خٲطرٕ وقف کرِ، سُہ کرِ کفارہٕ، تہٕ کرِ کُنہِ کُنہِ پوشہٕ لاگُن، حتیٰ کہ مقدس پوشاک۔ امۍ سند اتھہ بٔرتھ}\n33. تہٕ سُہ کرِ مقدس مقامہٕ خٲطرٕ کفارہٕ، تہٕ سُہ کرِ جماعت ہٕندِس خیمہ خانس تہٕ قربان گاہٕ خٲطرٕ کفارہٕ، تہٕ سُہ کرِ پادٕرین تہٕ جماعت کین سارنٕے لوکن ہٕندِ خٲطرٕ کفارہٕ۔\n34. تہٕ یہِ گژھہِ تۅہہِ خٲطرٕ اَکھ ابدی قانون یُس ؤریس منز اکہِ لٹہِ بنی اسرٲیلـ̡ تِہندین سارِنٕے گۅنہن ہُند کفارہ دِنہٕ ییہِ۔ تہٕ تٔمۍ کٔر یُس خداوند موسیٰ سُند حُکُم کوٚر۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. ہارونس سٍتـ̡ تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ تہٕ سارِنٕے بنی اسرٲیلـ̡ سٍتـ̡ کتھ کرٕنـ̡ تہٕ تِمن سٍتـ̡ ونُن۔ یہِ چُھہ سُہ چیز یُس خداوند چُھ حُکُم دِژمُت،\n3. یُس تہِ انسان آسہِ یُس خٲمس مَنٛز کُنہِ داند یا کۅکرِ یا ژھاوٕل مارِ، یا یُس خٲمہٕ منزٕ مارِ،\n4. تہٕ یہِ نہٕ اَننہٕ یِنہٕ جماعت کِس خیمہ کِس دروازس تام، یُس خداوند سٕندِس خیمہ خانس برونہہ کُن خداوند سٕندِ خٲطرٕ نذرانہ پیش کرنہٕ خٲطرٕ۔ تٔمِس شخصس گژھہِ خونُک الزام لگاونہٕ۔ تٔمۍ چُھ خون۔ تہٕ یہ زِ انسان گژھہِ پننین لوکن منز ژٹنہٕ:\n5. یێمہِ مۅکھہٕ یێلہِ بنی اِسرٲیلـ̡ پَنٕنـ̡ قُربٲنی أنِتھ، یُس تِم کھُلہٕ میدانس مَنٛز پیش کٔرِتھ، یێلہِ تِم خداوند سٕندِس خیمہٕ کِس دروازس تام، پادٕرِس نِش أنِتھ تہٕ تِمن ہٕندِ خٲطرٕ خداہس سٍتـ̡ پیش کرنہٕ خٲطرٕ۔\n6. تہٕ پادٕرۍ کرِ خداوند سٕندِس قربان گاہس پیٹھ خوُن چُھکُن، تہٕ کرِ خداوند سٕندِ خٲطرٕ مٔٹھۍ مَزٕ خٲطرٕ چربی زالنہٕ۔\n7. تہٕ تِم گژھن نہٕ وۅنۍ شیطانن پنٕنۍ قربانی پیش کرنہٕ، یٔمِس پتہٕ تِم بدکار گٔیہِ۔ یہ روزِ تِمن ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون۔\n8. تہٕ تُہۍ کٔرِو تِمن وَنُن، یُس تہِ انسان آسہِ، یُس تہِ اسرٲیلِس مَنٛز روزان آسہِ، یُس تہٕ یُس تہِ زالنہٕ یِنہٕ وول یا قربانی پیش کران چُھ،\n9.\\tتہٕ یێلہِ نہٕ یہِ جماعت کِس خیمہ کِس دروازس تام أنِتھ، یُس خداوند سٕندِ خٲطرٕ پیش کرنہٕ خٲطرٕ۔ سُہ انسان تہِ گژھہِ پننین لوکن منز ژٹنہٕ یُن۔\n10. تہٕ یُس تہِ انسان آسہِ، یُس تہِ اسرٲیلِک گرٕ آسہِ، یا یُس تہِ تۅہہِ درمِیان روزان چھُ، یُس کُنہِ تہِ قٕسمُک خوُن کھٮ۪وان چُھ۔ بہٕ کٔرٕ پنُن بُتھ تٔمِس روحس خلاف یُس خون کھیوان چُھ، تہٕ ژٹٕ أمِس پننین لوکن منٛز۔\n11.\\tماز سٕنزِ زندگی خٲطرٕ چُھہ خونس مَنٛز: تہٕ مے چُھہ ژے قربان گاہس پیٹھ دِژمُت زِ تُہٕندِس روحس خٲطرٕ کفارہ دِنہٕ خٲطرٕ، کیازِ یہِ چُھ سُہ خون {یُس} روحُک کفارہ بناوان۔\n12. تێمہِ کِنۍ ووٚن میہ بنی اسرٲیلِس زِ تۅہہِ منزٕ گژھِ نہٕ کانہہ تہِ جان خوُن کھٮ۪نہٕ تہٕ نہ کانہہ اجنبی یُس تہِ یُس تہِ روزان آسہِ تہٕ یُس تہِ روزان آسہِ تہٕ یُس تہِ خوُن کھٮ۪یہِ۔\n13. تہٕ یُس تہِ انسان آسہِ بنی اسرٲیل، یا یُس تہِ پرٲنِس منز روزان آسہِ، یُس کُنہِ تہِ جانور یا جاناوار یُس کھٮ۪نہٕ یِنہٕ وول آسہِ۔ سُہ تراوِ امُک خون تہِ، تہٕ دِیہِ گردِ سٍتـ̡ ؤلِتھ۔ {کُس...: ہیب۔ یُس کانہہ شکار کران چھُ}\n14. کیازِ {یہ} چُھ سارنٕے ماز سٕنز زندگی؛ اَمہِ سُند خوُن چُھہ امہِ سٕنزِ زندگی خٲطرٕ، تێمہِ کِنۍ چُھہ مے بنی اسرٲیلِس ووٚنمُت، تێلہِ چُھہ سارِنٕے ماز سُند خوُن، یێمہِ سٍتـ̡ چُھہ یُس تہٕ یُس یہِ کھٮ۪یہ، سُہ گژھہِ ژٹنہٕ یُن۔\n15.\\tتہٕ یُس کانہہ روح یُس مٔرِتھ آسہِ، یا یُس ژٹنہٕ آمُت آسہِ، چاہے سُہ تُہٕندِس ملکُک کانہہ آسہِ، یا اجنبی آسہِ، سُہ گژھہِ پَنُن پلو چھلناوُن، تہٕ پانس آبہٕ سٍتـ̡ سرانہٕ کرُن، تہٕ ناپاک روزُن، تیلہِ گژھہِ سُہ پاک روزُن۔ {یُس مرُن...: ہیب۔ اکھ لاشہٕ}\n16.\\tمگر اگر سُہ نہٕ تِمن واش کرِ، تہٕ نہ کرِ پنُن ماز۔ تیلہ گژھہِ سُہ پنُن بدکار برداش۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کرو تہٕ تِمن ونُن، بہٕ چُھس خداوند تُہند خدا۔\n3.\\tمصرٕچ سرزمینہٕ یَتھ مَنٛز تُہۍ روزان ٲسِو، تہٕ کنعان کِس سرزمینہٕ کِس اعمال پَتہٕ، یَتھ مَنٛز بہٕ تہٕ یێلہِ بہٕ تُہٕندِس احکام پٲٹھـ̡ پٔکِتھ پٔکِو۔\n4. تہٕ تُہۍ کٔرِو میٲنۍ فٲصلہٕ تہٕ میٲنۍ احکام برقرار تھاوُن، اَتھ مَنٛز پَکُن: بہٕ چُھس خداوند تُہند خدا۔\n5. تَمہِ کِنۍ پَزِ تُہۍ میٲنۍ قوانین، تہٕ میٲنۍ فٲصلن ہُند خیال تھاوُن: یُس یێلہِ کانہہ انسان کرِ، سُہ روزِ تِمن مَنٛز روزُن: بہٕ چُھس خداوند ۔\n6.\\tژے منزٕ گژھِ نہٕ کٲنسہِ تہِ یُس أمِس نزدیکی آسہِ، تِمن ہٕندِس ننگنہٕ نِش گژھِ نہٕ: بہٕ چُھس خداوند ۔ {نزدیک...: ہیب۔ تٔمۍ سُنٛد باقی ماز}\n7.\\tپننِس مٲلہِ سُند ننگہٕ یا پننہِ ماجہ ہُند ننگہٕ آسُن نہٕ ژے ظٲہر کرُن: سۅ چھے تہنز موج۔ ژے گژھ نہٕ تٔمۍ سٕنز ننگہٕ بے نقاب کٔرٕنۍ۔\n8.\\tپننہِ مٲلہِ سٕنزِ زنانہِ ہُند ننگہٕ گژھہِ نہٕ ژے ظٲہر کٔرِتھ: یہِ چھُ تُہندِ مٲلہِ سُند ننگہٕ۔\n9.\\tپننہِ بینہِ ہٕنز ننگہٕ، تہندِس مٲلہِ سٕنزِ کورِ، یا پننہِ ماجہ ہٕنز کورِ، {چاہے سۄ گھرس منز زامٕژ آسہِ، یا نیبرِم مُلکَس منز زامٕژ آسہِ، تِہٕنزِ ننگٲنی تہِ گژھِ نہٕ ژےٚ ظٲہر کٔرِتھ۔\n10.\\tپننہِ نیچوۍ سٕنزِ کورِ ہٕنزِ ننگہ آسنٕچ یا کورِ ہٕنزِ کورِ ہٕنز ننگٲنی تہِ گژھِ نہٕ تُہٕندِس ننگہٕ آسنس سٍتـ̡ تہِ ظٲہر کٔرِتھ، تِکیازِ تِہٕندِس ننگنہٕ سٍتـ̡ چُھہ تُہٕندِس ننگنہٕ سٍتـ̡ تہٕ تُہٕندِس ننگنہٕ سٍتـ̡ تہٕ تُہٕندِس ننگنہٕ سٍتـ̡ تہٕ تُہٕندِ\n11.\\tپننِس مٲلہِ سٕنزِ زنانہِ ہٕنزِ کورِ ہٕنز ننگہٕ، یُس تُہٕندِس مٲلہِ سٕنزِ بینہِ آسہِ، سُہ چھُنہٕ تٔمِس نِش بے نقاب کٔرِتھ۔\n12. ژے گژھ نہٕ پننِس مٲلہِ سٕنزِ بینہِ ہٕنز ننگہٕ ظٲہر کٔرِتھ، سۅ چھے تہندِس مٲلہِ سٕنزِ نزدیکی رشتہ دار۔\n13.\\tژیہ گژھ نہ پننہِ ماجہ ہٕنزِ بینہِ ہٕنز ننگہٕ بے نقاب کٔرِتھ، تکیازِ سۅ چھے تہنزِ ماجہ ہٕنزِ نزدیکی رشتہ دار۔\n14.\\tژے گژھ نہٕ پننِس مٲلہِ سٕندِس بٲے سٕنزِ ننگٲنی ہُند ظٲہِر کٔرِتھ، تہٕ تٔمۍ سٕنزِ زنانہِ نِش گژھِہ نہٕ تۅہہِ ہٕنزِ پۅپھ۔\n15.\\tژے گژھ نہٕ پننہِ نۅشہِ ہٕنز ننگہٕ ظٲہر کٔرِتھ: سۅ چھے تہندِس نیچوۍ سٕنز زنانہٕ۔ ژے گژھ نہٕ تٔمۍ سٕنز ننگہٕ بے نقاب کٔرٕنۍ۔\n16.\\tژے گژھ نہٕ پننِس بٲے سٕنزِ زنانہِ ہُند ننگہٕ ظٲہر کرُن: یہِ چھُ تُہندِ بٲے سُند ننگہٕ۔\n17.\\tژے گژھِ نہٕ زنانہِ تہٕ تٔمۍ سٕنزِ کورِ ہٕنزِ ننگہ پوشہٕ کٔرِتھ تہٕ تٔمۍ سٕنزِ کورِ ہٕنزِ کورِ ہٕنزِ ننگہٕ نِش نِش نِنہٕ۔ {کیازِ} تِم {چھِ} أمِس نزدیکی رشتہٕ دار: یہِ چھُ {بدکاری}۔\n18.\\tنہ گژھ نہ زنانہ پننہِ بینہِ نِش نِن، تٔمۍ سٕنزِ زندگی منز بییِس سٍتـ̡ نِش نِنہٕ خٲطرٕ۔ {اکھ زنانہٕ...: یا، اکھ بییس زنانہٕ}\n19.\\tتہِ گژھِ نہٕ کٲنسہِ زنانہِ نِش تٔمۍ سٕنزِ ننگٲنی ہُند ظٲہِر کرنہٕ خٲطرٕ گژھِ۔\n20. امہِ علاوٕ گژھ نہٕ پَنٕنِس ہمساین سٕنزِ زنانہِ سٍتـ̡ جنسی طور رٔلِتھ تہٕ پانس سٍتـ̡ ناپاک کرنہٕ خٲطرٕ۔\n21. تہٕ ژٕ گژھ نہٕ پنُن کانہہ تہِ بُلِس {نار} منزٕ مولیخس تام واتناوُن، تہٕ نہ کرٕ پنٕنِس خدایہ سُند ناو ناپاک کرنہٕ: بہٕ چُھس خداوند چُھس۔ {Molech: Gr. Moloch}\n22.\\tتوے گژھ نہ انسانس سٍتـ̡ زنانہٕ سٍتـ̡ روزُن: یہِ چُھہ مکروہ ۔\n23.\\tتہِ گژھہِ نہ کُنہِ تہِ درندس سٍتۍ پانس ناپاک کرنہٕ خٲطرٕ روزُن، تہٕ نہ گژھِ کانہہ تہِ زنانہ کُنہِ درندس برونہہ کُن کھڑا روزُن: یہ چھہ انتشار ۔\n24.\\tیِمو منزٕ کُنہِ تہِ چیزس مَنٛز کٔرِو نہٕ پان ناپاک کٔرِتھ، تکیازِ یِمن سارِنٕے قومن مَنٛز چھِ یِم میہ تۅہہِ برونہہ کُن دِنہٕ آمٕتۍ چھِ:\n25.\\tتہٕ زمین چھے ناپاک سپدان: تێمہِ کِنۍ چُھس بہٕ اَتھ سٍتـ̡ بدکار سپدان تہٕ زمینہٕ چُھہ پانہٕ پننین بسکینن ہٕندِس بسکیٖن سٍتـ̡ الٹی کران۔\n26. تێمہِ کِنۍ گژھِو میٲنۍ قونونن تہٕ میٲنۍ فٲصلن ہٕنز پاسداری، تہٕ یِمن مَنٛز کُنہِ تہِ کُنہِ کُنہِ تہ {نہ تہِ}تُہٕندِس قومس منز، تہٕ نہ کانہہ اجنبی یُس تۅہہِ منز روزان آسہِ:\n27.\\t(یِمن سارِنٕے مٔنزۍ بٔرِتھ چھِ زمینہِ ہٕندِس انسانس کٔرِتھ، یُس تۅہہِ برونہہ کُن ٲس، تہٕ زمین گٔیہِ ناپاک کرنہٕ۔)\n28.\\tیہ زِ زمینہٕ تہِ کرِ نہٕ تۅہہِ تہِ، ییلہ تہِ یہ ناپاک کٔرِو، یِتھ کٔنۍ تِم قومن ژٔٹِتھ یِم تۅہہِ برونہہ ٲسۍ۔\n29. یُس تہِ یِمو منزٕ کانہہ تہِ مکروہ کرِ، یُس تہِ یِمن ہُند ارتکاب کرِ، تِمن ہٕندِس لوکَس مَنٛز گژھِ ژٹنہٕ۔\n30. تێمہِ کِنۍ کٔرِو تُہۍ میٲنۍ حکمس پیٹھ عمل کرُن، یُس نہٕ تۅہہِ برونہہ کُن کرنہٕ آمُت چھُ، تہٕ یێلہِ کٔرِو نہٕ پان ناپاک کٔرِتھ: بہٕ چُھس خداوند تُہند خدا۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلـ̡ ہٕنزِ سارنٕے جماعتس سٍتـ̡ کتھ کرٕنـ̡ تہٕ تِمن ونُن زِ تُہٕندِس خدایہِ سٍتـ̡ چُھہ پاک۔\n3. تُہۍ گژھِو پرٮ۪تھ أکِس انسانس سٕنزِ ماجہ تہٕ مٲلِس سٍتـ̡ کھوژُن، تہٕ میٲنۍ سبت تھاوُن: بہٕ چُھس خداوند تُہند خدا۔\n4. بُتَن کُن نہٕ پھیرِو، تہٕ پانَس سٍتـ̡ پٔہلِتھ خدا: بہٕ چُھس خداوند تُہُند خدا۔\n5. تہٕ یێلہِ تہٕ یێلہِ تُہۍ خداوند سٕندِ خٲطرٕ امن ہٕنز قربانی پیش کٔرِو، تێلہِ کٔرِو یہِ پننہِ مرضی سٍتـ̡ پیش کرنہٕ۔\n6.\\tیہ گژھہِ تمہِ دۅہہ کھٮ۪نہٕ یُن، تہٕ پگہہ دۅہہ یِیہِ کھٮ۪نہٕ، تہٕ اگر تریمہِ دۅہس تام روزُن آسہِ، تیلہِ گژھہِ نارس منز زالنہٕ۔\n7.\\tاگر یہ تریمہِ دۅہہ کھٮ۪نہٕ ییہِ، تیلہِ چھہ یہ قابل نفرت آسان۔ یہ گژھِ نہٕ قبول کرنہٕ۔\n8. تێمہِ کِنۍ یُس یہِ کھٮ۪وان چُھ، سُہ گژھہِ پَنُن گُناہ برداشت کَرُن، تِکیازِ تٔمۍ چُھ خداوند سٕندِس پاک چیزس ناپاک کورمُت، تہٕ سُہ روح گژھہِ پننِس لوکَس مَنٛز ژٹنہٕ یُن۔\n9.\\tتہٕ ییلہ تۅہہ پننہِ زمینہِ ہُند فصٕل لُٹِو، تہٕ نہ کٔرِو پنہٕ نِس زمینہٕ ہٕندِس کونہٕ سٍتـ̡ لُٹنہٕ۔\n10. تہٕ ژٕ گژھ نہٕ پَنُن انگور ژٔٹِتھ تہٕ نہ کٔرِو پَنٕنِس انگورُک پرٮ۪تھ کُنہِ انگور جمع کٔرِتھ۔ ژے تراوُن تِم غریبن تہٕ اَجنبَن ہٕندِ خٲطرٕ: بہٕ چُھس خداوند تُہند خدا۔\n11.\\tژوٗرِ کرُن، نہ کرو اپُز سودا تہٕ نہ کرو اکھ أکِس سٍتـ̡ اپُز۔\n12. تہٕ ژٕ گژھ نہٕ میانہِ ناوٕ سٍتـ̡ اپُز قسم، تہٕ نہ کٔرٕکھ پَنٕنـ̡ خدایہ سُند ناو ناپاک کرنہٕ: بہٕ چُھس خداوند ۔\n13.\\tژے گژھ نہٕ پننِس ہمساین دھوکہٕ دِنہٕ تہٕ نہ لُٹُن، یُس کرایہ دِنہٕ آمُت چھُ، سُہ روزِ نہٕ صُبحَس تام سارِوٕے رٲژ توے سٍتـ̡ روزُن۔\n14. ژے گژھ نہٕ بہرَن بد دعا کٔرِتھ، تہٕ انہِ برونہہ کُن ٹھوکر تراوُن، مگر پنہٕ نِس خدایس کھوژُن: بہٕ چُھس خداوند ۔\n15.\\tفیصلس منز گژھِ نہٕ کانہہ ناانصافی کٔرٕن: غریبن ہٕندِس شخصس کٔرِو نہٕ عزت تہٕ نہ کرُن طاقتور شخصس عزت: {مگر} نیکی سٍتـ̡ کٔرِو پننِس ہمساین ہُند انصاف کرنہٕ۔\n16.\\tژے گژھ نہ پننین لوکن منز افسانہ نگار سٍتـ̡ ہیوٚر بۄن گژھُن: تہٕ نہ گژھ ژے پننِس ہمساے سٕندِس خونس خلاف کھڑا گژھُن: بہٕ چُھس خداوند ۔\n17.\\tژے گژھ نہٕ پننِس بٲے سٕندِس دلس سٍتـ̡ نفرت، تہٕ کُنہِ تہِ پٲٹھـ̡ کرٕنـ̡ پننِس ہمساین سٍتـ̡ ملامت کٔرٕنـ̡ تہٕ تٔمِس سٍتـ̡ گژھِ نہٕ گۅناہ کرنہٕ۔ {تہٕ...: یا یہ زِ تٔمۍ سٕندِ خٲطرٕ گژھ نہٕ گۅناہ برداش}\n18. توے گژھ نہٕ پننِس لوکن ہٕندِس شُرین سٍتـ̡ انتقام تہٕ نہ کُنہِ تہِ بغض تھاوُن، مگر ژٕ کرٕ پننِس ہمساین پانس سٍتـ̡ محبت کرُن: بہٕ چُھس خداوند ۔\n19.\\tمیٲنۍ قونوٗن تھاوٕنۍ۔ ژے گژھ نہٕ پنٕنۍ چارواین مختلف قٕسمس سٍتۍ جنس بناوُن: ژے گژھ نہٕ پنُن کھہٕ رلہٕ رٔلِتھ بیٲلۍ سٍتۍ ووُن، تہٕ نہ گژھِ ژےٚ کُنہِ کُنہِ تہٕ ییرُک پلو یِنہٕ۔\n20. تہٕ یُس کُنہِ زنانہِ سٍتـ̡ جنسی تعلق تھاوان چُھ، یعنی خاوندس سٍتـ̡ منگنی آسہِ، تہٕ یێلہِ نہٕ أمِس دِنہٕ آمُت تہٕ یێلہِ نہٕ أمِس آزٲدی دِنہٕ آمٕژ آسہِ۔ أمِس یِیہِ کوٹھہٕ دِنہٕ۔ تِم یِن نہٕ مارنہٕ، تِکیازِ سۄ ٲس نہٕ آزاد۔ {منگنی...: یا، بدسلوکی کٔرِتھ کُنہِ: ہیب۔ (یا، انسانس خٲطرٕ) ملامت کٔرِتھ} {سُہ کرِ...: یا، تِم، وغیرہ: ہیب۔ اتہِ گژھہِ اکھ کوڑا}\n21. تہٕ سُہ کرِ خداوند سٕندِس خیمہٕ کِس دروازس تام، تہٕ کُنہِ تہِ کُنہِ تہ\n22. تہٕ پادٕرۍ کرِ تٔمِس خٲطرٕ کفارہٕ یُس تٔمۍ سٕندِ کُنہِ گۅنہٕ کُن خداوند سٕندِ برونہہ کُن کٔرِمُت چھُ، تہٕ یُس گۅناہ تٔمۍ کٔرِمُت چُھ، سُہ گژھہِ أمِس معاف۔\n23. تہٕ ییلہ تم زمینس منز وٲتِو، تہٕ کھٮ۪نہٕ خٲطرٕ پریتھ قسمٕکۍ کُلۍ لگٲوِو، تیلہِ گژھِو تمِکۍ پھل ختنہ کرنہٕ آمُت تہٕ تریہ ؤری گژھہِ نہٕ کھٮ۪نہٕ یِنہٕ۔\n24.\\tمگر ژوٗرمہِ ؤریس مَنٛز گژھہِ اَمہِ سٍتـ̡ سٍتـ̡ مقدس سپدُن۔ {مقدس...: ہیب۔ خداوند سٕندِ تعریفُک پاکیزہٕ}\n25. تہٕ پوٗنٛژمہِ ؤریس مَنٛز کھیٛو تُہٕندِس مٮ۪وٕ سٍتـ̡ یُس تۅہہِ ہُند ہُریر دِیہِ: بہٕ چُھس خداوند تُہند خدا۔\n26.\\tژیہ گژھِ نہ خونس سٍتـ̡ کھیوٚن: نہ کرو جادو تہٕ نہ کٔرِو وقتُک مشاہدٕ۔\n27.\\tژیہ گژھ نہ پننین کلن اندۍ پکھۍ تہ نہ گژھ پننہِ داڑھی ہندس کونس سیتۍ واٹھ دِتھ۔\n28.\\tتہٕ پَنٕنِس مازس مَنٛز کُنہِ تہِ ژٔٹِتھ تہٕ نہ کُنہِ نشانہٕ چھاپُن: بہٕ چُھس خداوند ۔\n29.\\tپننہِ کورِ ہٕنز طوائف بٔنِتھ مہٕ کٔرِو طوائف۔ متان گژھہِ زمین بدکاری سٍتۍ بٔرِتھ تہٕ زمین گژھہِ بدکاری سٍتۍ بٔرِتھ۔ {طوائف: ہیب۔ ناپسندیدہ}\n30.\\tتہٕ میٲنۍ سبت تھاوُن، تہٕ میانہِ مقدس مقامس احترام: بہٕ چُھس خداوند ۔\n31.\\tتِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِ\n32.\\tژے گژھہِ کلہٕ برونہہ کُن تھوٚد تہٕ بُزرگ سٕندِس بُتھِس عزت کرُن، تہٕ پنہٕ نِس خدایس کھوژُن: بہٕ چُھس خداوند ۔\n33.\\tتہٕ اگر کانہہ اجنبی شخص تُہٕندِس سرزمینس مَنٛز روزِ، تۅہہ کٔرِو نہٕ تس پریشان۔ {vex: یا، جبر}\n34.\\t{مگر} یُس اجنبی یُس توے سٍتـ̡ روزان چُھ، سُہ گژھہِ تۅہہِ سٍتـ̡ پانس سٍتـ̡ محبت کرُن، تہٕ تُہۍ کٔرِو تس پانس سٍتـ̡ محبت۔ تِکیازِ تُہۍ ٲسِو مصرٕکِس سرزمینس مَنٛز اجنبی تہٕ بہٕ چُھس خداوند تُہند خدا۔\n35. فیصلس منز، وزنس منز، وزنس منز تہٕ پیمائشس منز گژھِ نہٕ کانہہ ناانصافی کرٕنۍ۔\n36.\\tعادل توازن، صرف وزن، اکھ عادل ایفا تہٕ اکھ عادل ہِن، یُس ژے آسُن: بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کِس سرزمینہٕ منزٕ نیبر کٔرِتھ آو۔ {وزن: ہیب۔ پتھر}\n37. تێمہِ کِنۍ کٔرِو میٲنۍ سارِنٕے قونوٗن، تہٕ میٲنۍ سارِنٕے فٲصلن ہُند عمل تہٕ یِم کٔرِو: بہٕ چُھس خداوند چُھس۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. دُبارٕ کٔرِو تُہۍ بنی اِسرٲیلِس مَنٛز یُس تہٕ یُس اِسرٲیلِس مَنٛز روزان آسہِ، یُس تٔمۍ سٕندِس اولادُک کانہہ تہِ حصہ دِیہِ۔ سُہ یِیہِ یٔقیٖنی طور مارنہٕ یُن: زمینٕکۍ لوٗکھ کٔرِن أمِس کَنہِ۔\n3.\\tتہٕ بہٕ کٔرٕ أمِس شخصس سٍتـ̡ پنُن بُتھ تہٕ ژٔٹِتھ ژٔٹِتھ أمِس لُکہٕ نِش ژٔٹِتھ ۔ تکیازِ تٔمۍ چُھ پنُن بُل مولیخس دِژمُت، میانہِ مقدس ناوس ناپاک کرنہٕ خٲطرٕ، تہٕ میانہِ مقدس ناوٕچ بے حرمتی کرنہٕ خٲطرٕ۔\n4.\\tتہٕ یێلہِ کُنہِ تہِ طٔریٖقہٕ سٍتـ̡ یێلہِ سُہ پَنُن بُل دِیہِ تہٕ سُہ کٔرِو نہٕ أمِس مٲرِتھ:\n5.\\tتیلہ کرٕ بہٕ أمِس شخصس تہٕ تٔمۍ سٕندِس عیالس خلاف پنُن بُتھ تہٕ سُہ ژٔٹِتھ تہٕ یُس أمِس پَتہٕ یِمن ہٕندِس لُکہٕ سٍتـ̡ مولیخس سٍتـ̡ بدکاری کٔرِتھ ژٔٹِتھ تہٕ سُہ ژٔٹِتھ تہٕ یُس أمِس پَتہٕ یِمن ہٕندِس لُکہٕ سٍتـ̡ بدکاری کٔرِتھ۔\n6. تہٕ یُس روح یُس مانوس روح آسہِ، تہٕ جادوگرن پتہٕ یِمن ہٕندِس پَتہٕ کُنہِ روحس سٍتـ̡ پھیران چُھ، بہٕ کٔرٕ تٔمِس روحس سٍتـ̡ بُتھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژٔٹِتھ ۔\n7. تَمہِ کِنۍ کٔرِو پنُن پان پاک تہٕ پاک روزُن، تِکیازِ بہٕ چُھس خداوند تُہند خدا۔\n8. تہٕ تُہۍ کٔرِو میٲنۍ قونوٗن رژھرٕن، تہٕ یِم کٔرِو: بہٕ چُھس خداوند یُس تُہۍ پاک کران چھُ۔\n9.\\tیُس تہِ پننِس مٲلِس یا ماجہِ ہُند بد دعا کرِ، سُہ گژھہِ یُس پننِس مٲلِس یا ماجہِ ہُند لعنت۔ تٔمۍ سُند خون آسہِ تس پیٹھ۔\n10.\\tیُس مرد بییِس مردس سٕنزِ زنانہِ سٍتـ̡ زنا کرِ، سُہ تہِ یُس پننِس ہمساے سٕنزِ زنانہِ سٍتـ̡ زنا کرِ، سُہ گژھِ یٔقیٖنی طور مارنہٕ یُن۔\n11.\\tیُس مرد پننِس مٲلہِ سٕنزِ زنانہِ سٍتـ̡ روزان چُھ، سُہ چُھ پننِس مٲلہِ سٕنز ننگہٕ کٔرِتھ، یِم یِن دۅشوے یِن مارنہٕ۔ تِہُند خون آسہِ تِمن پیٹھ۔\n12.\\tتہٕ یێلہِ کانہہ مرد پننہِ نۅشہِ سٍتـ̡ روزِ، یێلہِ یِم دۅشوے یِن مارنہٕ یِن: تِمو گٔیہِ انتشار پٲدٕ۔ تِہُند خون آسہِ تِمن پیٹھ۔\n13.\\tیێلہِ کانہہ مرد تہِ انسانس سٍتـ̡ روزِ، یِتھٕ پٲٹھۍ سُہ زنانہِ سٍتـ̡ روزان چُھ، یێلہِ چُھہ یِمو دۅشوے گٔژھمُت تہٕ یِم یِن یٔقیٖنی طور مارنہٕ یِن۔ تِہُند خون آسہِ تِمن پیٹھ۔\n14.\\tتہٕ یێلہِ کانہہ مرد زنانہِ تہٕ ماجہ رٔٹِتھ چھُ، یہِ چھُ بُرکاری : سُہ تہٕ تِم گژھن نارٕ سٍتـ̡ زالنہٕ۔ یُس نہٕ تۅہہِ منز کانہہ بد کاری آسہِ۔\n15. تہٕ اگر کانہہ انسان کُنہِ درندس سٍتـ̡ روزِ، سُہ ییہِ یقینا مارنہٕ۔\n16.\\tتہٕ اگر کانہہ زنانہ کُنہِ تہِ درندس نِش ییہ تہٕ تٔمِس سٍتـ̡ مارنہٕ یِن، تِم یِن یقینا مارنہٕ۔ تِہُند خون آسہِ تِمن پیٹھ۔\n17.\\tتہٕ اگر کانہہ مرد پننہِ بینہِ، مٲلہِ سٕنزِ کورِ یا ماجہ ہٕنز کورِ نِتھ تہٕ سُہ تٔمۍ سُند ننگہٕ وُچھِ۔ یہ {چُھ} اکھ بدکار چیز۔ تہٕ تِم یِن پننین لوکن ہٕندِس نظرس منز ژٹنہٕ: تٔمۍ کٔر پننہِ بینہِ ہٕنز ننگہٕ بے نقاب ۔ سُہ کرِ پنُن بدکار برداش۔\n18. تہٕ اگر مرد کُنہِ زنانہِ سٍتـ̡ بیمار آسہِ، تہٕ تٔمۍ سٕندِس ننگنہٕ نِش کٔرِ۔ أمِس چھُ أمۍ سُند چشمہ دریافت کوٚرمُت، تہٕ تٔمۍ کٔر پننہِ خونُک چشمہٕ تہٕ یِم دۅشوے یِن پننین لوکن منزٕ ژٹنہٕ۔ {دریافت: ہیب۔ ننگہٕ بناونہٕ آمُت}\n19.\\tتہٕ ژے گژھِ نہٕ پننہِ ماجہِ ہٕنزِ بینہِ ہٕنز ننگٲنی تہٕ نہ مٲلہِ سٕنزِ بینہِ ہٕنز بے نقابی ظٲہر کٔرِتھ، تِم گژھن پنٕنۍ بدکاری برداشت کٔرِتھ۔ {انکور: ہیب۔ چھہ ننگہٕ بنٲومُت}\n20.\\tتہٕ یێلہِ کانہہ مرد پننِس پیٚترٕ سٕنزِ زنانہِ سٍتـ̡ روزِ، تٔمِس چُھ پۯاوُن پۯاوُن، تِم گژھن پنُن گۅناہ برداش۔ تِم مرن بےٚ اولاد ۔\n21. تہٕ اگر کانہہ مرد پننِس بٲے سٕنزِ زنانہِ نِش نیرِ، سُہ چُھ ناپاک چیز: تٔمۍ چُھ پننِس بٲے سٕنز ننگہٕ کٔرِتھ۔ تِم گژھن بے اولاد آسن۔ {an...: Heb. اکھ علیحدگی}\n22. تێمہِ کِنۍ کٔرِو میٲنۍ سٲری قونوُن، تہٕ میٲنۍ سارِنٕے فٲصلہٕ تہٕ یِم کٔرِو تہٕ یێلہِ بہٕ ژےٚ اَتھ مَنٛز روزنہٕ خٲطرٕ یێلہِ تہٕ یێلہِ تہِ بہٕ ژےٚ بَساونہٕ خٲطرٕ اَنِتھ تہٕ ژے کٔرِو نہٕ ژےٚ کُن دِنہٕ۔\n23. تہٕ تُہۍ پٔکِو نہٕ قومہٕ کِس آداب سٍتـ̡ پٔکِتھ، یُس مے ژے برونہہ کُن دِژمُت چُھ، تِکیازِ تِمو کٔر یِم سارِنٕے کامہِ کٔرِتھ، تہٕ اوے کٔر بہٕ تِمن سٍتـ̡ نفرت۔\n24. مگر میہ چُھہ ژے ووٚنمُت، تہٕ بہٕ دِیہ ژے تِہٕنزِ زمینہِ ہٕندِس مٲلِس سٍتـ̡ یُس دۄدٕ تہٕ ماچھہِ سٍتـ̡ وسان چُھہ: بہٕ چُھس خداوند تُہند خدا، یٔمۍ ژے باقین لُکن نِش الگ کٔرِتھ چُھ۔\n25. تێمہِ کِنۍ کٔرِو تُہۍ پاک درندَن تہٕ ناپاک جاناوارن تہٕ پاکیزَن درمیان فرق تھاوُن، تہٕ پَنُن روح کٔرِو نہٕ درندٕ سٍتـ̡ یا کُنہِ تہِ زُوٕ سٍتـ̡ یُس زمینس پیٹھ رٔژان چُھ، یُس مے ژے نِش ناپاک قرار دِژمُت چُھ، یُس میہ ژے نِش ناپاک قرار دِژمُت چھُ۔ {کریپتھ: یا، مووتھ}\n26. تہٕ تُہۍ گژھِو میانہِ خٲطرٕ پاک روزُن، تِکیازِ بہٕ چُھس خداوند پاک تہٕ چُھس ژے باقین لُکن نِش الگ کورمُت، یُتھ تہٕ ژٕ گژھہِ میون بٔنِتھ۔\n27.\\tیُس مرد یا زنانہٕ آسہِ یُس کانہہ مانوس روح آسہِ، یا یُس جادوگر آسہِ، یُس یُس یٔقیٖنی طور مارنہٕ یُن: تِمن کٔنہِ کٔنہِ سٍتـ̡ کٔنہِ سٍتـ̡ کٔرِتھ تہٕ تِمن ہُند خوُن گژھہِ تِمن سٍتـ̡ پٲٹھـ̡ ۔","1. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ ہارون سٕندِس نیٚچوِس پادٕرین سٍتـ̡ کتھ تہٕ تِمن وَنُن زِ تٔمۍ سٕندِس لُکہٕ مَنٛز گژھِ نہٕ کانہہ تہِ مُردن ہٕندِ خٲطرٕ ناپاک کرنہٕ۔\n2. مگر پننس رشتہ دارس خٲطرٕ، یُس أمس نزدیکی چُھ، {یعنی}، پننہٕ ماجہٕ خٲطرٕ، تہٕ پننس مٲلس خٲطرٕ، تہٕ پننس نیچوس خٲطرٕ، تہٕ پننس کورِ خٲطرٕ، تہٕ پننس بٲیِس خٲطرٕ،\n3.\\tتہٕ پننہِ بینہِ ہٕندِ خٲطرٕ، یۅسہٕ أمِس نزدیک، یٔمِس نہٕ کانہہ خانٛدار آسہِ۔ تٔمۍ سٕندِ خٲطرٕ گژھ سُہ ناپاک کرنہٕ۔\n4. {مگر} سُہ کرِ نہٕ پنُن پان ناپاک کرنہٕ، {پَنٕنِس لُکن مَنٛز اکھ بٔڈِہ شخٕص آسنہٕ کِنۍ، پنُن پان ناپاک کرنہٕ خٲطرٕ۔ {سُہ ...: یا پننین لوکن منز خاوند آسنہ کِنۍ گژھِ نہ سُہ پننہِ زنانہِ ہٕندِ خٲطرٕ پانس ناپاک کرُن، وغیرہ}\n5.\\tتِم گژھن نہٕ کَلہٕ کَلہٕ کٔرِتھ، نہ کٔرِن داڑھ ہُند کوُن کاسنہٕ، تہٕ نہ کٔرِن پننِس مازس مَنٛز کانہہ ژٹ۔\n6. تِم گژھن پننِس خداہٕ سٕندِ خٲطرٕ پاک آسن، تہٕ پننِس خدایہ سٕندِ ناوٕچ ناپاک گژھن نہٕ: خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہٕ خٲطرٕ، {تہٕ} تِمن ہٕندِس خدایہِ سٕنزِ روٹی سٍتـ̡ چِھہ تِم پیش کران: تێمہِ مۄکھٕ گژھن تِم پاک آسن۔\n7.\\tتِم گژھن نہٕ زنانہٕ رٔٹِتھ یا بدکار ۔ نۂ تِم نِن زنانہٕ پننِس خاوندس نِش دور کٔرِتھ، کیازِ سُہ چُھ پننِس خداہٕ سٕندِ خٲطرٕ پاک۔\n8. تێلہِ کٔرِو تٔمِس پاکیز۔ تکیازِ سُہ چُھہ تُہندِ خدایہ سٕنز روٹی پیش کران: سُہ گژھہِ تۅہہِ خٲطرٕ پاک روزُن، کیازِ بہٕ چُھس خدا، یُس تُہہِ پاک کران چُھ، {بہ} چُھس پاک۔\n9.\\tتہٕ کُنہِ تہِ پادٕرۍ سٕنزِ کورِ، اگر سُہ طوائف سُند کردار ادا کٔرِتھ پانس بدنام کرِ، سُہ گژھِ پننِس مٲلِس بے عزتی کٔرِتھ: سُہ گژھِ نارٕ سٍتـ̡ زالنہٕ۔\n10.\\tتہٕ یُس پننین باین مَنٛز بٔڈ پادٕرۍ چُھ، یٔمۍ سٕندِس کلس پیٹھ مسح کرنُک تیٖل تراونہٕ آمُت چُھ، تہٕ یُس پلو لاگنہٕ خٲطرٕ مقدس چُھ، سُہ گژھِ نہٕ پنُن کلہٕ تہٕ نہ پَنُن پلو ژٔٹِتھ۔\n11.\\tسُہ گژھِ کُنہِ تہِ لاشس منز اژُن، نہ گژھِ پننِس مٲلِس سٍتـ̡ یا ماجہ ہٕندِ خٲطرٕ پانس ناپاک کرُن۔\n12. سُہ گژھِ نہٕ مقدس مقامہٕ منزٕ نیبر نیرُن، تہٕ نہ کرِ پننِس خدایہ سٕندِس مقدس مقامس ناپاک کرنہٕ۔ تٔمۍ سٕندِس خدایہ سٕندِ مسح کِس تیٖلُک تاج چُھس أمِس پیٹھ: بہٕ چُھس خداوند چُھس۔\n13. تہٕ سُہ کرِ کنوارِس منز زنانہٕ۔\n14.\\tبیواہ یا طلاق شدٕ زنانہٕ یا بدکار زنانہٕ یا بدکار زنانہٕ، یِم گژھِ نہٕ تٔمِس نِنہٕ، مگر سُہ کرِ پننین لوکن ہٕنزِ کُنوارِ ہٕنزِ خانٛدارِ۔\n15. نہ کرِ سُہ پننین لوکن مَنٛز پنٕنـ̡ اولاد ناپاک کٔرِتھ، تکیازِ بہٕ چُھس خداوند أمِس پاک کران۔\n16.\\tتہٕ خداوند کٔر موسیٰ سٍتـ̡ کتھ کٔرِتھ،\n17.\\tہارونس سٍتـ̡ کتھ کرِتھ ونُن، یُس تہندِس نسلس مَنٛز یُس تہندِس نسلس مَنٛز کانہہ عیب آسہِ، سُہ گژھہِ نہٕ پنہٕ نِس خدایہ سٕنز روٹی پیش کرنہٕ خٲطرٕ یُس نہٕ یِنہٕ یُن۔ {روٹی: یا، کھیٛن}\n18.\\tیُس تہِ انسان یُس داغ آسہِ، سُہ گژھِ نہٕ یُس انہِ نَس آسہِ، یا یٔمِس نَس چپٹہٕ آسہِ، یا کُنہِ تہِ غیر ضروری چیز،\n19.\\tیا کانہہ انسان یُس کھورِ پھُٹمُت آسہِ، یا پھُٹمُت اتھہٕ آسہِ،\n20.\\tیا کُنہِ پھُٹمُت۔ {اکھ بونہٕ: یا، واریاہ زٲل}\n21.\\tکانہہ تہِ انسان یُس نہٕ ہارون سٕندِ اولادُک داغ آسہِ، سُہ گژھہِ نہٕ خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پیش کرنہٕ خٲطرٕ یُس أمِس نِش داغ آسہِ۔ سُہ گژھِ نہٕ پننِس خدایہ سٕنز روٹی پیش کرنہٕ خٲطرٕ نزدیک۔\n22.\\tسُہ کھیوٚو پنہٕ نِس خدایہ سٕنز، یُس مقدس تہٕ مقدس سُند روٹی چُھ۔\n23. صرف گژھِ نہٕ سُہ گُرِ کُن اژُن، تہٕ نہ گژھِ قربان گاہس نزدیک، تکیازِ أمِس چُھ اکھ داغ۔ زِ سُہ کرِ نہٕ میانین مقدس مقامن ہٕنز بے حرمتی، تکیازِ بہٕ چُھس خداوند تِمن پاک کران۔\n24. تہٕ موسىٰ ہن ہارونس تہٕ تٔمۍ سٕندِس نیچوِس تہٕ سارِنٕے بنی اسرٲیلِس وونُن۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. ہارون تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ کتھ کرٕن، زِ تِم گژھن بنی اسرٲیلـ̡ ہٕندِس مقدس چیزو نِش الگ تہٕ یێلہِ تِم میانہِ خٲطرٕ پاکیزہ کران چھِ، تہٕ یێلہِ تِم میانہِ خٲطرٕ پاکیزٕ کران چھِ، بہٕ چُھس خداوند ۔\n3.\\tتِمن وَنُن، یُس تہندِس سارِنٕے نسلس مَنٛز آسہِ، یُس تُہٕندِس سارِنٕے نسلس مَنٛز آسہِ، یُس تُہٕندِس مُقدس چیزن کُن گَژھان چُھ، یُس بنی اسرٲیلِس خداوند سٕندِ خٲطرٕ پاک چُھ، یُس تٔمِس سٍتـ̡ ناپاک آسنہٕ سٍتـ̡ چُھہ تٔمِس سٍتـ̡ ژٹنہٕ یُن: بہٕ چُھس خداوند چُھس۔\n4.\\tہارون سٕندِس بُلِس منز کُس انسان چُھہ کوڑھ یا کانہہ مسلہٕ۔ سُہ گژھِ نہٕ پاک چیزو سٍتـ̡ کھٮ۪ن، یوتام نہٕ سُہ پاک گژھِ۔ تہٕ یُس کُنہِ تہِ چیزس {یُس} ناپاک آسہِ، یا یُس انسان یمۍ سُند بیول أمِس نِش نیران چُھ؛ {رننگ...: ہیب۔ رننگ آف دی رینس}\n5. یا یُس تہِ کُنہِ تہِ چیزس اتھہٕ لاگہِ، یمہِ سٍتـ̡ سُہ ناپاک گژھہِ، یا یێمِس سٍتـ̡ سُہ ناپاک آسہِ، سُہ تہِ چُھہ ناپاک سپدِ۔\n6.\\tیُس روح یُس یِتھِس سٍتـ̡ لوٚگمُت آسہِ، سُہ گژھہِ نہٕ پاک چیزن سٍتـ̡ کھٮ۪نہٕ، یوٚت تام نہٕ سُہ پنُن ماز آبہٕ سٍتـ̡ چھلناوُن۔\n7. تہٕ ییلہ آفتاب لوسُن، سُہ گژھہِ پاک تہٕ امہِ پتہٕ گژھہِ مقدس چیزن کھٮ۪ن۔ تِکیازِ یہِ چھُ تٔمۍ سُنٛد کھٮ۪ن۔\n8. یُس پانس سٍتـ̡ مرُن، یا ژٹِتھ چُھہ سُہ چُھہ نہٕ پانس ناپاک کرنہٕ خٲطرٕ کھٮ۪وان: بہٕ چُھس خداوند چُھس۔\n9. تێمہِ کِنۍ گژھن تِم میٲنۍ حکمہٕ برقرار تھاون، یێلہِ گژھن تِم امہِ خٲطرٕ گۅناہ تہٕ تێلہِ گژھن مرُن، تێلہِ گژھن یێلہِ تِم ناپاک کٔرِن: بہٕ چُھس خداوند تِمن پاک کران۔\n10.\\tکانہہ تہِ اجنبی گژھِ نہٕ مقدس چیز کھٮ۪ن: پادٕرۍ سُند روزُن وول یا کرایہ دار خادم گژھِ نہٕ مقدس چیز کھٮ۪ن۔\n11. مگر اگر پادٕرۍ پننیو پونسہٕ سٍتـ̡ کانہہ روح ہینہٕ چُھ، سُہ گژھہِ سُہ کھٮ۪ن، تہٕ یُس تٔمۍ سٕندِس گرس مَنٛز زامُت آسہِ، سُہ گژھہِ تٔمۍ سُند ماز کھٮ۪ن۔ {with...: Heb. پنٕنۍ پونسہٕ ہینہٕ سۭتۍ}\n12.\\tاگر پادٕرۍ سٕنزِ کورِ تہِ کٲنسہِ اجنبی سٍتـ̡ خاندر کرنہٕ ییہِ، سُہ گژھِ نہٕ مقدس چیزن ہٕندِ نذرانہ سٍتـ̡ کھٮ۪تھ۔ {اکھ اجنبی: ہیب۔ اکھ انسان اکھ اجنبی}\n13. مگر اگر پادٕرۍ سٕنز کورِ بیواہ آسہِ، یا طلاق آسہِ، تہٕ کانہہ بچہ آسہِ، تہٕ یێلہِ سُہ پننِس مٲلہِ سٕندِس گَرٕ واپس یِنہٕ، یِتھ کٔنۍ زَن جوانی ہٕندِس ماز سٍتـ̡ کھٮ۪نہٕ ییہِ۔\n14.\\tتہٕ یێلہِ کانہہ انسان نادانسٲنی سٍتـ̡ مُقدس چیز کھٮ۪وان چُھ، تیلہِ گژھہِ سُہ اَمہِ ہُند پوٗنٛژِم حصہٕ اَتھ مَنٛز تراوُن، تہٕ دِیہِ پادٕرِس مُقدس چیزس سٍتـ̡۔\n15.\\tتہٕ تِم گژھن نہٕ بنی اسرٲیلـ̡ ہٕندِس مُقدس چیزن ہٕنز بے حرمتی کٔرِتھ، یُس تِم خداوند سٍتـ̡ پیش کران چھِ۔\n16.\\tیا یِمن ہٕندِس مقدس چیز کھٮ۪نہٕ وِزِ دِیُن تِمن ہٕندِس پاکیزگی ہُند گُناہ برداشت کرُن، یێلہِ بہٕ چُھس یِمن پاکیزگی کران چھُس۔ {مصیبت...: یا، پننس پانس کھٮ۪نس منز گناہ کرنچ بدکاری کرُن}\n17.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وۆن،\n18.\\tہارونس تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ تہٕ سارنٕے بنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن زِ یُس تہٕ یُس تہِ اسرٲیلِس مُتعلِق آسہِ، یُس تٔمۍ سٕندِس سارِنٕے نذرن تہٕ تٔمۍ سٕندِس سارِنٕے نذرن ہٕندِ خٲطرٕ تہٕ تٔمۍ سٕندِس سارِنٕے نذرن ہٕندِ خٲطرٕ پیش کرِ، یُس تِم خداوند سٕندِ دزنہٕ خٲطرٕ پیش کرِ۔\n19. {تُہۍ کٔرِو پننہِ مرضی سٍتـ̡ گاوُن، کۅکرِ ہُند، کۅکرِ ہُند یا ژھاوُل سُند اکھ نَر پیش کٔرِو۔\n20.\\t{مگر} یُس تہِ کانہہ عیب آسہِ، سُہ گژھِ نہٕ تۅہہِ ہٕندِ خٲطرٕ قبول۔\n21. تہٕ یُس تہٕ یُس خداوند سٕندِ خٲطرٕ امنٕچ قربانی دِیہِ، یا گٲمِس یا دانٛدن مَنٛز آزادانہ نذرانہ پیش کرِ، سُہ گژھہِ قبوٗل کرنہٕ خٲطرٕ کٲمل۔ اتھ منز گژھہِ نہ کانہہ داغ آسن۔ {کٹہٕ: یا، ژھاوٕل}\n22. انہِ، پھُٹمُت، یا پھُٹمُت، یا کُنہِ تہِ نذرانہ سٍتـ̡ تہٕ یِمن ہٕندِس نارس سٍتـ̡ خداوند سٕندِ خٲطرٕ پیش کٔرِتھ۔\n23.\\tاکھ بیل یا کۅکرِ یُس کانہہ چیز غیر ضروری آسہِ یا تٔمۍ سٕندِس اعضا سٍتـ̡ آسہِ، یێمہِ سٍتـ̡ تۅہہ کُنہِ مرضی سٍتـ̡ پیش کٔرِتھ۔ مگر عہد کرنہٕ خٲطرٕ گژھِ نہٕ یہِ قبول کرنہٕ۔ {لیمب: یا، بچہ}\n24. یُس ژٔٹِتھ آسہِ، یا پھُٹمُت، یا ژٹنہٕ آمُت آسہِ، تہٕ ژٹنہٕ آمُت آسہِ، تُہۍ کٔرِو نہٕ خداوند سٕندِس سٍتـ̡ پیش کرنہٕ۔ تہٕ نہ کرو تُہۍ پننِس زمینس مَنٛز {امِچ کانہہ نذران}۔\n25. یِمو منزٕ کُنہِ تہِ کُنہِ تہِ اَتھٕ سٍتـ̡ کُنہِ تہِ پَنٕنـ̡ خدایہِ سٕندِ روٹی دِنہٕ یِنـ̡ ۔ تِکیازِ تِمن مَنٛز چُھ تِمن ہٕنز خرابی {تہٕ} تہٕ تِمن مَنٛز عیب {آسن}، تِم گژھِ نہٕ تۅہہِ خٲطرٕ قبول کرنہٕ۔\n26.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وونُن،\n27.\\tییلہ اکھ بیل یا کۅکرِ یا ژھاوُل نیرِ، تیلہِ گژھہِ سَتھ دۅہہٕ دۅہہ۔ تہٕ ٲٹھمہِ دۅہہٕ پیٹھٕ تہٕ پتہٕ یِیہِ یہِ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ پیش کرنہٕ خٲطرٕ قبول کرنہٕ۔\n28.\\tتہٕ {چاہے سُہ گاو آسہِ} یا دانٛدٕ، تۅہہ کٔرِو نہٕ أمِس تہٕ تٔمۍ سٕندِس بچہٕ دۄشوٕے أکِس دۅہس منز مٲرِتھ۔ {ایو: یا، سۅ ژھایہِ}\n29. تہٕ ییلہِ تُہۍ خداوند سٕندِ خٲطرٕ شُکرگزاری ہٕنز قربانی پیش کٔرِو، تہٕ کٔرِو پننہِ مرضی سٍتـ̡ پیش کرنہٕ۔\n30. امی دۅہہ گژھہِ یہ کھٮ۪نہٕ یُن۔ پگہہ تام گژھ نہ اتھ منز کانہہ تہِ تراوُن: بہٕ چُھس خداوند ۔\n31. تێمہِ کِنۍ کٔرِو میٲنۍ حُکمن ہٕنز پاسداری، تہٕ تِم کٔرِو پورٕ: بہٕ چُھس خداوند ۔\n32. تہٕ نہ کٔرِو میٲنۍ مقدس ناو ناپاک کرنہٕ۔ مگر بہٕ گژھہٕ بنی اسرائیلس مَنٛز پاک کرنہٕ: بہٕ چُھس خداوند یُس تۅہہ پاک کران چُھ،\n33. یُس ژے مصر کہِ سرزمینہٕ منزٕ نیبر نیرُن، تُہند خدا بننہٕ خٲطرٕ: بہٕ چُھس خداوند چُھس۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، خداوند سٕندِ عید متعلق، یُس تُہۍ اعلان کرِو {یُس} مقدس مجلسہٕ، {حتیٰ کہ} یِم چھِ میٲنۍ دعوت۔\n3. شیہ دۅہ گژھہِ کٲم کرنہٕ: مگر سٔتِم دۅہ چُھ آرامُک سبت ، اکھ مقدس اجتماع۔ یێلہِ تہِ چُھہ نہٕ تُہٕندِس سارِنٕے گَرَن مَنٛز خداوند سُند سبت دۅہہٕ۔\n4. یِم {چِھ}خداوند سٕندِ دعوت، {حتیٰ کہ} مقدس مجلسہٕ، یُس تُہۍ پننین موسمن مَنٛز اعلان کرِو۔\n5. گۅڈنِکِس ژۄدٲہِمِس دۅہس مَنٛز چُھ خداوند سُند فسح تہِ۔\n6. تہٕ امی ریتہٕ کِس پنٛدٲہِمہِ دۅہہٕ چُھ خداوند سٕندِ خٲطرٕ خمیرٕ روٚس روٹی ہُند عید آسان: سَتھ دۅہہٕ چُھ تُہۍ خمیرٕ روٚس روٹی کھیوٚن۔\n7. گۅڈنِکہِ دۅہہ گژھہِ تۅہہِ اکھ مقدس اجتماع کرنہٕ: اَتھ مَنٛز گژھِ نہٕ کانہہ غلامی کٲم کرنہٕ۔\n8. مگر سَتَن دۅہن کٔرِو خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ پیش کرنہٕ یُن: سٔتِم دۅہہٕ چُھہ مُقدس مجلس: تێلہِ گژھِو نہٕ کانہہ غلامی کٲم کٔرِتھ۔\n9. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n10. بنی اِسرٲیلِس سٍتـ̡ کتھ کٔرِو تہٕ تِمن وَنُن، یێلہِ یێلہِ یێلہِ بہٕ تۅہہِ دِنہٕ آمٕژ زمینہِ مَنٛز وٲتِو، تہٕ اَمہ سٍتـ̡ لُٹنہٕ یِن، تێلہِ أنِو پَنٕنـ̡ فصلہٕ کِس گۄڈنِکِس پھلُک اکھ گُلہٕ پادٕرِس نِش۔ عمر}\n11. تہٕ سُہ کرِ خداوند سٕندِ برونہہ کُن یُس تۅہہِ خٲطرٕ قبول کرنہٕ یُن، پگہہ دۅہہ کرِ پادٕرۍ یہِ لہراوُن۔\n12. تہٕ تُہۍ کٔرِو تمہِ دۅہہ یێلہِ گۅڈنِکِس ؤریس ہٕندِس دَزنہٕ سٍتـ̡ دِنہٕ خٲطرٕ دِنہٕ آمُت۔\n13.\\tتہٕ اَمہِ سٍتـ̡ ماز نذرانہ آسہِ تیٖلس سٍتـ̡ رلاونہٕ آمُت، نارٕ سٍتـ̡ دِنہٕ آمُت چُھہ مٔٹھـ̡ مٔٹھـ̡ تہٕ اَمہ سٍتـ̡ چُھہ شرابُک ژوٗرِم حصہٕ آسہِ۔\n14. تہٕ تۅہہ کھیوٚو نہٕ روٹی، نہ خشک مکئی تہٕ نہ سبز کَن، یوتام نہٕ تۅہہ پننِس خداہس خٲطرٕ نذرانہ پیش کرِو: {یہِ} آسہِ تُہنزن تمام گرن مَنٛز ہمیشہٕ خٲطرٕ اکھ قانون۔\n15.\\tتہٕ سبت پتہٕ پگہہ پیٹھٕ ژیہ گنزراونہٕ یِنہٕ والہِ دۅہہٕ پیٹھٕ یێلہِ تہٕ ژے لہر ہٕندِ نذرانہ ہُند شیف أنِو۔ ستھ سبت گژھن مکمل۔\n16. سٔتِمہِ سبت پتہٕ تہِ پَنژاہ دۅہہٕ روزُن۔ تہٕ تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ نۆو ماز پیش کرنہٕ۔\n17. تُہۍ کٔرِو پَنٕنِس بستہٕ منزٕ زٕ دٔہِمہِ ہٕندِس دٔہلِس سٍتـ̡ زٕ لہرٕ رٔٹِتھ ، یِم آسٕنـ̡ جان آٹٕچ ۔ تِم گژھن خمیر سٍتۍ سینہٕ یِن؛ {تِم چِھ}خداوند سٕندِ خٲطرٕ گۅڈنِچ پھل۔\n18.\\tتہٕ تُہۍ کٔرِو روٹی سٍتـ̡ سَتھ کۅکرِ بٔرِتھ گۅڈنِکِس ؤریس سٍتـ̡ سَتھ دانٛد تہٕ اکھ بچہٕ تہٕ زٕ مینڈٕ، یِم گژھن خداوند سٕندِ خٲطرٕ دزنہٕ یِنہٕ وول نذرانہ تہٕ تِہٕندِ شرابٕچ نذرانہ سٍتـ̡ تہٕ یێلہِ تہِ یێلہِ چُھہ نارٕ سٍتـ̡ دِنہٕ یِنہٕ آمُت، یُس خداوند سٕندِ خٲطرٕ مٔٹھہِ مٔزِتھ دِنہٕ یِنہٕ وول نذرانہ آسہِ۔\n19.\\tتێلہِ کٔرِو ژھاوُن ہُند اکھ بچہٕ گۅنہٕ کِس قربانی خٲطرٕ، تہٕ گۄڈنِکہِ ؤرۍ یُک زٕ کٹہٕ بچہٕ کٔرِو صلح کِس قربان کرنہٕ باپتھ۔\n20. تہٕ پادٕرۍ کرِ تِمن گۄڈنِکِس پھلہٕ سٕنزِ روٹی سٍتـ̡ لہراوُن، یێلہِ چُھہ خداوند سٕندِ خٲطرٕ دۅن دامن سٍتـ̡ مقدس آسن۔\n21. تہٕ تُہۍ کرو امی دۅہہ اعلان کرُن، {یُتھ} یہ گژھہِ تۅہہِ خٲطرٕ اکھ مقدس اجتماع آسُن: تہٕ تۅہہ گژھِ نہٕ کانہہ غلامی کٲم کرٕنۍ: یہ روزِ تُہنزن سارنٕے مکانن منز ہمیشہٕ خٲطرٕ اکھ قانون۔\n22. تہٕ ییلہ تہٕ پَنٕنـ̡ زمینہٕ ہُند فصٕل لُٹِو، تێلہِ کٔرِو نہٕ پَنٕنـ̡ کھہہٕ کِس کوُنـ̡ صاف سٍتـ̡ پاک کٔرِتھ، تێلہِ کٔرِو نہٕ پنہٕ نِس فصلہٕ سٍتـ̡ کُنہِ فصلہٕ سٍتـ̡ سٍتـ̡ غریبن تہٕ اَپرٲنِس سٍتـ̡ تراوُن: بہٕ چُھس خداوند تُہند خدا۔\n23.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن\n24.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، سٔتِمہِ ریتس مَنٛز، ریتہٕ کِس گۄڈنِکِس دۅہس مَنٛز، یێلہِ سبت تہٕ بُرسی ہُند یادگار، اکھ مقدس مجلس۔\n25.\\tتُہۍ کرِ نہٕ کانہہ غلامی کٲم کٔرِتھ، مگر یُس نارٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ دِنہٕ آمُت چھُ۔\n26.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وونُن،\n27.\\tامہِ سٔتِمہِ ریتہٕ کِس دٔہمہِ دۅہہٕ گژھہِ کفارہٕ دِنُک دۅہہ: یِہ گژھہِ تۅہہِ خٲطرٕ اکھ مقدس اجتماع۔ تہٕ تُہۍ کٔرِو پَنٕنـ̡ پَنٕنـ̡ دِنہٕ آمُت، تہٕ کٔرِو خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پیش کرنہٕ۔\n28. تہٕ تۅہہ کٔرِو نہٕ اَمی دۅہہٕ کُنہِ تہِ کٲم، تکیازِ یہِ چُھہ کفارہٕ ہُند دۅہہ، یُس خداوند پنُن خدایہ سٕندِس برونہہ کُن کفارہ دِنہٕ ییہِ۔\n29.\\tیُس تہِ روح آسہِ یُس نہ امی دۅہہ مصیبت سپدِ، سُہ گژھہِ پننین لوکن منز ژٹنہٕ یُن۔\n30.\\tتہٕ یُس تہِ روح اَمی دۅہس منز کانہہ کٲم کرِ، سُہ کرٕ بہٕ تٔمۍ سٕندِس لوکَس مَنٛز تباہ کرنہٕ۔\n31.\\tتۅہہ گژھہِ نہ کانہہ تہِ کٲم کرُن: {یہِ} آسہِ تُہنزن سارنٕے مکانن منز ہمیشہ خٲطرٕ اکھ قانون۔\n32. یہ گژھہِ تۅہہِ خٲطرٕ آرام دِنُک دۅہہ، تہٕ تُہۍ کٔرِو پنٕنـ̡ سبت مناونہٕ۔ {مناوُن: ہیب۔ آرام کٔرِ}\n33. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n34.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ ، یێمہِ سٔتِمہِ ریتُک پنٛدٲہِم دۅہہٕ آسہِ خداوند سٕندِ خٲطرٕ سَتَن دۅہن ہُند عید ۔\n35.\\tگۅڈنچہ دۅہہ گژھہِ مقدس مجلس: تۅہہ گژھہِ نہ کانہہ غلامی کٲم کرُن۔\n36. سَتھ دۅہہٕ یُس تُہۍ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ یِنہٕ وول نذرانہ پیش کرُن، ٲٹھمہِ دۅہہٕ گژھہِ تۅہہِ خٲطرٕ اکھ مقدس دعوت دِنہٕ۔ تہٕ تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پیش کرنہٕ: یہِ چُھہ اَکھ سنجیدہ مجلس۔ {تہٕ} تُہۍ کرِ نہٕ کانہہ غلامی کٲم {اَتھ منز}۔ {سنجید...: ہیب۔ پابندیُک دۄہ}\n37.\\tیِم چھِ خداوند سٕندِ دۅہہٕ سٍتـ̡ یِمن ہُند اعلان کرُن، یێمہِ سٍتـ̡ خداوند سٕندِ دۅہہٕ سٍتـ̡ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پیش کرنہٕ خٲطرٕ، اکھ زٲلِتھ نذرانہ تہٕ مازٕچ نذرانہ پیش کرنہٕ خٲطرٕ، یێمہِ سٕندِس دۅہہٕ سٍتـ̡ چُھہ پرٮ۪تھ کانہہ چیز۔\n38.\\tخداوند سٕندِ سبت سٍتـ̡ تہٕ چُھہ تُہٕندِس سٍتـ̡ تہٕ سارِنٕے نذرن سٍتـ̡ تہٕ تُہٕندِس سارِنٕے مرضی سٍتـ̡ یُس تُہۍ خداوند دِوان چُھ۔\n39.\\tسٔتِمہِ دۅہہٕ ییلہ تم زمینہِ ہٕندِس پھلس مَنٛز جمع سپدِو، تۯێلہِ گژھِو خداوند سٕندِ خٲطرٕ سَتھ دۅہہٕ دعوت تھاوُن: گۄڈنِکہِ دۅہہ گژھہِ سبت تہٕ ٲٹھمہِ دۅہہٕ گژھہِ سبت دۅہہٕ۔\n40. تہٕ تُہۍ نِیِو گۄڈنِکہِ دۅہہ اَصٕل کُلٮ۪ن ہٕنزِ لٔنٛجہِ، کھجور کُلٮ۪ن ہٕنزِ لنجہِ تہٕ گٔنٮ۪ن کُلٮ۪ن ہٕنزِ لٔنٛجہِ تہٕ نالہٕ ہٕندِس وِلہٕ سٍتـ̡ نِنہٕ۔ تہٕ تُہۍ کٔرِو خداوند پنُن خدایہ سٕندِ برونہہ کُن سَتن دۅہن شاد سپدُن۔ {اَصٕل کُلؠن ہٕنز: ہیب۔ میوٕ، وغیرہ}\n41. تہٕ تُہۍ تھاوِو یہِ ؤریس مَنٛز سَتھ دۅہہٕ خداوند سٕندِ خٲطرٕ دعوت ۔ {یہِ آسہِ} تُہنزن نسلن منز ہمیشہٕ خٲطرٕ اکھ قانون: تُہۍ کرو یہ سٔتِم رٮ۪تہٕ مناونہٕ۔\n42. تم روزن ستن دۅہن بوتھس منز۔ یُس سارِنٕے اسرٲیلِیو زامُت چُھ، تِم روزن بوتھس مَنٛز:\n43. یێلہِ تێلہِ پتاہ زِ مے بنوو بنی بنی اسرائیل بوتھن مَنٛز روزنہٕ خٲطرٕ، ییلہ بہٕ تِم مصرٕچ سرزمینہٕ منزٕ نٮ۪بر کٔرِتھ: بہٕ چُھس خداوند تُہند خدا۔\n44. تہٕ موسىٰ دِژ بنی اِسرٲیلِس خٲطرٕ خداوند سٕندِ عید ہُند اعلان۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس حُکُم کٔرِو زِ تِم أنِن گاشہٕ خٲطرٕ خالص تیٖل زیتون تہٕ گاشہٕ خٲطرٕ دِنہٕ یِنہٕ خٲطرٕ۔ {وجہ: ہیب۔ وجہٕ کھسُن}\n3. گوٲہی ہٕندِ پردٕ ورٲے، جماعت کِس خیمہ خانس مَنٛز، ہارون کرِ شامَس پیٹھٕ صُبحہ تام خداوند سٕندِ برونہہ کُن حکم دِنہٕ: {یہِ} آسہِ تُہنزِ نسلن مَنٛز ہمیشہٕ خٲطرٕ اکھ قانون۔\n4. سُہ کرِ خداوند سٕندِ برونہہ کُن خٲلص شمعہٕ پٲٹھـ̡ شمعہٕ دِنُک حُکُم۔\n5.\\tتہٕ ژیہ رٔٹِتھ رٔٹِتھ باہ کیک بناوُن: أکِس کیکس منز گژھن زٕ دٔہِم سودا کرنہٕ۔\n6.\\tتہٕ تِم تھاوُن خداوند سٕندِ برونہہ کُن پاک میزس پیٹھ دۄن قطارن منز، شیہ قطارس پیٹھ۔\n7. تہٕ ژے تھاوُن خالص لوبان یُس پرٮ۪تھ أکِس لٲنہِ پیٹھ آسہِ، یُس خدایہِ سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت آسہِ۔\n8. پرٮ۪تھ سبت سٍتـ̡ گژھِ سُہ خداوند سٕندِس برونہہ کُن مُسلسل ترتیب دِنہٕ، یُس اَکھ ابدی عہد سٍتـ̡ بنی اسرٲیلِس نِش نِنہٕ ییہِ۔\n9. تہٕ یہِ آسہِ ہارون سُند تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ ۔ تہٕ تِم گژھن یہِ مُقدس مقامس مَنٛز کھٮ۪ن: تکیازِ یہِ چُھہ خداوند سٕندِ خٲطرٕ سارِوٕے کھۄتہٕ مقدس یُس دٲیمی قانونہٕ سٍتـ̡ نارٕ سٍتـ̡ دِنہٕ آمُت چُھ۔\n10.\\tتہٕ أکِس اسرٲیلِی زنانہِ ہُند نیچو، یٔمۍ سُند مول مصری اوس، درٛاو اِسرٲیلِیَن ہٕندِس نیچوس منز، تہٕ اِسرٲیلِیُک یہِ نیچو تہٕ اِسرٲیلُک اکھ مرد گٔیہِ اِکہٕ وٹہٕ خٲمس مَنٛز۔\n11.\\tتہٕ اسرائیلی زنانہِ ہٕندِس نیچوِس کٔر خداوند سٕندِس ناوٕچ بے عزتی تہٕ کٔرٕن لعنت۔ تہٕ تِمو أنۍ سُہ موسیٰ سٕندِس نِش: (تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس شیلومِتھ، یُس ڈیبری سٕنز کورِ، یُس ڈین قبیلہٕ سٕندِس سٍتـ̡ اوس:)\n12.\\tتہٕ تِمو تھوو سُہ وارڈس مَنٛز، یُتھ خداوند سُند ذہن ہاونہٕ ییہِ۔ {یہ...: ہیب۔ خداوند سٕندِ زبانہِ مطٲبق تِمن ہٕنز وضاحت کرنہٕ خٲطرٕ}\n13. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن\n14.\\tیُس خٲمہٕ ورٲے لعنتُک دُعا دِیُتمُت چھُ۔ تہٕ یِمو سارِنٕے بوزن سٍتـ̡ تٔمۍ سٕندِس کلس پیٹھ اتھہٕ تھووُن، تہٕ سارِنٕے جمٲژ گٔژھن أمِس کَلہٕ پٲٹھۍ۔\n15. تہٕ تُہہِ کٔرِو بنی اِسرٲیلِس سٍتـ̡ کتھ کرٕن، یُس تہٕ یُس پننِس خدایس لعنت کرِ، سُہ گژھہِ پَنُن گۅناہ برداشت کرُن۔\n16. تہٕ یُس خداوند سٕندِس ناوٕچ بے عزتی کرِ، سُہ یِیہِ یٔقیٖنی طور مارنہٕ، تہٕ سارِنٕے جماعت یِیہِ أمِس پٔزۍ پٲٹھـ̡ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ بێعزتی کرِ، سٍتـ̡ یێلہِ یێلہِ س\n17.\\tیُس کانہہ تہِ انسان مارِ، سُہ گژھہِ یُس قتل کرنہٕ یُن۔ {مارُن...: ہیب۔ انسان سٕنز زِندٕ}\n18.\\tیُس کانہہ جانور مارِ، سُہ کرِ سُہ رٔٹِتھ ۔ درندٕ خٲطرٕ جانور۔ {درندٕ خٲطرٕ...: ہیب۔ لائف فار لائف}\n19.\\tتہٕ اگر کانہہ شخص پننِس ہمساین منز داغ دِیہِ۔ یِتھٕ پٲٹھۍ تٔمۍ کٔر، تِتھے پٲٹھۍ گژھہِ أمِس سٍتۍ کرنہٕ۔\n20.\\tدندٕ بدلہٕ اچھ، أچھ بدلہٕ أچھ، دندٕ بدلہٕ دند: یِتھٕ پٲٹھۍ أمِس انسانس منز داغ دِیُت، تِتھے پٲٹھۍ گژھہِ أمِس سٍتۍ {دوبارٕ} کرنہٕ۔\n21.\\tیُس کانہہ جانور مارِ، سُہ کرِ سُہ دُبارٕ تہٕ یُس انسان مارِ، سُہ گژھہِ مارنہٕ۔\n22.\\tتۅہہِ آسہِ اَکہِ طٔریٖقہٕ شریعت تہٕ پرٲنِس سٍتـ̡ تہٕ تُہٕندِس أکِس مُلکَس سٍتـ̡ تہِ آسہِ: کیازِ بہٕ چُھس خداوند تُہند خدا۔\n23. تہٕ موسىٰ کٔر بنی اِسرٲیلِس سٍتـ̡ کتھ زِ تِم گژھن سُہ یُس خٲمہٕ منزٕ بد دعا کورمُت اوس، تہٕ تٔمِس کٔنہِ کٔنہِ سٍتـ̡ کٔنـ̡ کٔرِتھ۔ تہٕ بنی اسرٲیلیو کٔر یُس خداوند موسیٰ سُند حکم دِیُت۔","1. تہٕ خداوند کٔر سینا پہاڑس مَنٛز موسیٰ ہس سٍتـ̡ کتھ کرنہٕ،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کٔرِو تہٕ تِمن ونُن، یێلہِ یێلہِ یێلہِ بہٕ تۅہہِ دِنہٕ آمٕژ زمینس مَنٛز یێلہِ بہٕ دِژمُت چھُ، تێلہِ گژھہِ زمینہٕ خداوند سٍتـ̡ سبت دِنہٕ۔ {کیپ: ہیب۔ آرام کٔرِ}\n3. شیہ ؤری پَنُن کھیت ووُن، تہٕ شیہ ؤری کٔرِکھ پَنُن انگور ژٹُن، تہٕ اَمہ کِس مٮ۪وَس مَنٛز جمع کٔرِتھ۔\n4. مگر سٔتِمہِ ؤریس مَنٛز روزِ زمینہٕ خٲطرٕ آرام دِنُک سبت تہٕ خداوند سٕندِ خٲطرٕ سبت روزُن: ژے کٔرِو نہٕ پَنُن کھہٕ ووتُن، تہٕ کٔرِو پنُن انگور ژٹُن۔\n5. یُس پننہِ فصلہٕ سٍتـ̡ پانہٕ کھسنہٕ سٍتـ̡ چُھہ نہٕ ژٔٹِتھ تہٕ نہ کٔرِو پنہٕ نِس انگور سٍتـ̡ کُنہِ سٍتـ̡ {تُہٕندِس بیلس منز...: ہیب۔ چانہِ جدایی ہُند}\n6. تہٕ زمینُک سبت گژھہِ تۅہہِ خٲطرٕ ماز ۔ تۅہہِ خٲطرٕ، تہٕ تُہٕندِس خادمَس خٲطرٕ، تہٕ پننہِ نوکرِ خٲطرٕ، تہٕ پننہِ کرایہ دار خادمَس خٲطرٕ، تہٕ تُہٕندِس اجنبی سٕندِ خٲطرٕ یُس توے سٍتۍ روزان چُھ،\n7. تہٕ تُہندِ چارواین تہٕ تُہنزِ زمینہِ منز موجود درندٕ سٕندِ خٲطرٕ گژھہِ سارِنٕے ماز ہُند ماز آسُن۔\n8. تہٕ توے کٔرِو سَتھ ؤری سَتھ سَتھ ؤری۔ تہٕ سَتن ؤرین ہٕندِس سبت ہُند وقفہٕ آسہِ تۅہہِ خٲطرٕ ژتٲجی تہٕ نَوُن ؤری۔\n9. تیلہٕ کٔرِو سٔتِمہِ رٮ۪تہٕ کِس دٔہِمہِ دۅہہٕ کُنہِ دۅہہٕ کُنہِ کفارہٕ دِنہٕ یِنہٕ وٲلِس دۅہہٕ سٍتـ̡ سٲرۍسٕے سرزمینس مَنٛز بٔنِتھ بجہِ۔ {جوبیل: ہیب۔ آوازِ ہُند زور}\n10. تہٕ تُہۍ کٔرِو پنژٲہِم ؤری مقدس تہٕ سارِنٕے زمینس سٍتـ̡ سارِنٕے بسکیٖنن خٲطرٕ آزادیُک اعلان کرُن: یہ گژھہِ تۅہہِ خٲطرٕ اکھ جوبل۔ تہٕ تُہۍ کٔرِو پرٮ۪تھ أکِس نفرس تٔمِس عیالس نِش واپس۔\n11.\\tاکھ جوبیل گژھہِ تۅہہِ خٲطرٕ یُس پنژاہ ؤری آسہِ، تہٕ نہ کٔرِو تۅہہ وُنُن یُس اتھ مَنٛز وۅپدان آسہِ، تہٕ نہ کٔرِو اَتھ مَنٛز پنہٕ نِس انگور سٍتـ̡ کُنہِ سٍتـ̡\n12. تکیازِ یہ {چُھ} جوبل۔ یہ گژھہِ تۅہہِ خٲطرٕ مقدس آسُن: کھہٕ منزٕ گژھہِ امہِ سٍتـ̡ اضافہٕ کھٮ۪نہٕ۔\n13. یَتھ جوبیل کِس ؤریس مَنٛز گژھِو تُہۍ پرٮ۪تھ أکِس شخصس پننِس قبضس مَنٛز واپس۔\n14.\\tتہٕ اگر تۅہہ پننِس ہمساین کٕنِتھ یا ہمسایہ سٕندِس اتھہٕ سٍتـ̡ ہیوٚت، تیلہِ کٔرِو نہٕ اکھ أکِس سٍتـ̡ ظُلم:\n15.\\tجوبیل پتہٕ یُس ؤری یُس توے ہمسایہ نِش ہینہٕ یُن، {تہٕ} مٮ۪وَن ہٕندِس تعدادس مُطٲبق یُس سُہ توے کٕنُن دِیہِ:\n16.\\tؤرین ہندِ تعدادس مطٲبق کرِ توے امیک قٕمتھ ہُرراوُن، تہٕ کم ؤرین مطٲبق کٔرِو تۅہہ امیک قٕمتھ کم کرُن، تکیازِ مٮ۪وَن ہٕندِس تعدادس مُطٲبق چُھ سُہ توے کٕنان۔\n17. تَمہِ مۄکھٕ گژھِ نہٕ اَکھ أکِس سٍتـ̡ ظُلم کٔرِتھ۔ مگر ژٕ گژھ پننِس خدایس کھوژُن: کیازِ بہٕ چُھس خداوند تُہند خدا۔\n18.\\tتێلہِ کٔرِو میٲنۍ قونوٗن تہٕ میٲنۍ فٲصلہٕ رٔٹِتھ تہٕ کٔرِو تِم کٔرِو۔ تہٕ تُہۍ روزِو زمینس منز محفوٗظ روزُن۔\n19. تہٕ زمینہٕ دِیہِ پنُن پھل تہٕ تُہۍ کھیٚیہِ پنُن پورٕ کھٮ۪وان تہٕ اَتھ مَنٛز روزِو رٲبطہٕ۔\n20. تہٕ اگر تُہۍ ؤنِو، سٔتِم ؤری کیا کھیون أسۍ؟ وچھو أسۍ نہٕ ووتُن، تہٕ نہ کٔرِو پننِس اضافس مَنٛز:\n21. تیلہِ کٔرٕ بہٕ شیٚیِمہِ ؤریس مَنٛز ژےٚ پَنُن دُعا دِنُک حُکُم، تہٕ سُہ دِیہِ ترٛٮ۪ن ؤرِین تام پھل دِنہٕ۔\n22.\\tتہٕ تُہۍ کرو ٲٹھمہِ ؤریس تام ووتُن، تہٕ نٔوِمہِ ؤریس تام کھیوٚو پرانہِ میو۔ یوٚت تام تٔمۍ سُند میوٕ یِنہٕ توٚت تام کھیوٚو تۅہہ پرون {دکان}۔\n23.\\tزمین گژھہِ نہ ہمیشہٕ خٲطرٕ کٕننہٕ: کیازِ زمین چھیہ میٲنۍ تکیازِ تم چھہِ میہ سیتۍ اجنبی تہ سفر کرن وٲلۍ۔ {ہمیشہ خٲطرٕ: یا، بالکل ژٹنہٕ خٲطرٕ: ہیب۔ ژٹنہٕ خٲطرٕ}\n24.\\tتہٕ پننہِ سارِنٕے زمینہِ مَنٛز کٔرِو تُہۍ زمینہِ ہٕندِ فٲصلہٕ دِنہٕ۔\n25.\\tاگر تُہند بٲے غریب آسہِ، تہٕ پنُن کینہہ مال کٕنُن آسہِ، تہٕ اگر تٔمۍ سُند کانہہ رشتہٕ دار ییہ یہِ چھُ، تیلہِ کرِ سُہ یُس تٔمۍ سٕندِس بٲے کٕنُن آسہِ۔\n26.\\tتہٕ اگر أمِس شخصس نِش کانہہ تہِ چھُنہٕ تہٕ پانَے چھُ یہِ فدٲیرٕ دِنہٕ خٲطرٕ قٲبل۔ {پانہٕ...: ہیب۔ تٔمۍ سٕندِ اَتھٕ چُھ حٲصل تہٕ لٔبِتھ کٲفی\n27.\\tتیلہ گژھہِ سُہ امہِ کٕنٕکۍ ؤری گٔنزراوُن، تہٕ یٔمِس شخصس یہ کٕنُن اوس تٔمِس شخصس واپس دِنہٕ۔ تاکہ سُہ گژھِ پننِس قبضس منز واپس۔\n28. مگر اگر سُہ أمِس واپس دِتھ ہیوٚک نہٕ، تیلہِ یُس کٕننہٕ آمُت چُھ، سُہ روزِ تٔمِس اتھس منز یُس یہِ ہیوٚتمُت آسہِ، تہٕ سُہ گژھہِ پننِس قبضس منز واپس۔\n29. تہٕ اگر کانہہ انسان دیوار وٲلِس شہرس مَنٛز مکانہٕ کٕنِتھ کٕنِتھ تہٕ سُہ کٕننہٕ پتہٕ پوٗرٕ ؤریس اندر سُہ چھُ واپس نِتھ۔ {اندر} پورٕ ؤریس اندر گژھ سُہ یہ نجات دِتھ۔\n30. تہٕ یێلہِ یێلہِ یہِ پوٗرٕ ؤرۍ یَس مَنٛز چھُ نہٕ نجات دِنہٕ یِوان، تیلہِ یُس گرٕ یُس دیوار وٲلِس شہرس مَنٛز چُھ، سُہ گژھہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ یُس یہِ پنہٕ نِس نسلس مَنٛز ہیوٚتمُت آسہِ: سُہ گژھِ نہٕ جوبلس مَنٛز نیرُن۔\n31.\\tمگر یِمن گامن ہٕندِ گَرٕ یِمن اندۍ پٔکھۍ نہٕ دیوار آسہِ، یِم گژھن ملکٕکۍ کھہٕ شمار کرنہٕ یِن: تِم گژھن چھِ نجات دِنہٕ یِن، تہٕ یِم گژھن جوبیلس مَنٛز نیرنہٕ۔ {تم ہیکن...: ہیب۔ نجات چُھ اتھ سٍتـ̡ سٍتـ̡\n32. لاوی ہٕندِس شہرس باوجود، تہٕ تِمن ہٕندِس قبضس منز شہرن ہٕندِس گرس باوجود، ہێکہِ لاوی کُنہِ تہِ وِزِ آزاد کٔرِتھ۔\n33.\\tتہٕ یێلہِ کانہہ شخص لاوِین ہٕندِس مَنٛز ہیوٚت، تێلہِ یُس مکانہٕ کٕننہٕ آمُت آسہِ، تہٕ تٔمِس سُند شہر یُس کٕننہٕ آمُت چُھ، یێلہِ یێلہِ ہُند مکان یُس یُس کٕننہٕ آمُت آسہِ، تہٕ یێمہِ سٍتـ̡ یُس شہر کٕننہٕ آمُت چُھ، یێلہِ چُھہ اِسرٲیلِس مَنٛز تِمن ہُند قبضہ سپدُن۔ {اکھ انسان...: یا، لاویو منزٕ اکھ چھُ تِمن چھُ نجات دِوان}\n34.\\tمگر تِہندین شہرن ہٕندِس مضافاتی علاقن ہُند مٲدان گژھِ نہٕ کٕننہٕ یِتھ۔ تکیازِ یہ چھہ تہند دائمی قبضہ۔\n35. تہٕ اگر تُہند بوے غریب، تہٕ ژےٚ سٍتـ̡ گٔژھِتھ گٔیہِ۔ تیلہ کٔرِو تٔمِس نجات دِنہٕ: {آ، چاہے سُہ اجنبی آسہِ، یا روزُن وول آسہِ۔ تاکہ سُہ روزِ توے سٍتـ̡ روزُن۔ {fallen...: Heb. تٔمۍ سُند اَتھٕ چُھ ناکام گٔژھان} {relieve: Heb. مضبوٗط کٔرِو}\n36. أمِس نِش کٔرِو نہٕ سود تہٕ ہُریر، مگر پَنٕنِس خداہِ سٍتـ̡ کھوژُن۔ تاکہ تُہند بوے روزِ ژےٚ سٍتـ̡ روزُن۔\n37.\\tتٔمِس دِیُن نہٕ سود خوری سٍتـ̡ پَنُن پٲنسہٕ دِنہٕ تہٕ نہ دِیُن أمِس ہُریرٕ خٲطرٕ پنُن پٲنسہٕ۔\n38. بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کہِ سرزمینہٕ منزٕ نیبر کٔرِتھ، تہٕ تُہند خدا بننہٕ خٲطرٕ۔\n39.\\tتہٕ یێلہِ تُہُند بٲے یُس تۅہہِ سٍتـ̡ روزان چُھ، تہٕ یێلہِ تہٕ یێلہِ تُہٕندِس سٍتـ̡ کٕننہٕ ییہِ۔ ژے کٔرِو نہٕ أمِس غلام سٕندِس خدمتس پیٹھ مجبور کرنہٕ: {مجبور...: ہیب۔ خدمت کٔرِو أمِس سٍتـ̡ خدمت وغیرہ}\n40.\\t{مگر} بحیثیت کرایہ دار نوکر، {تہٕ} روزِ تۅہہِ سٍتۍ، {تہٕ} روزِ تۅہہِ سٍتـ̡ جوبیل ؤریس تام۔\n41.\\tتہٕ سُہ گژھِ توے نِش نیرُن، سُہ تہٕ تٔمۍ سٕندِس شُرِ سٍتـ̡ پانس سٍتـ̡ واپس۔\n42. تِم چھِ میٲنۍ خادم، یِم مے مصرٕچ سرزمینہٕ منزٕ نیبر کٔرۍمٕتۍ: تِم گژھن نہٕ غلام کٕننہٕ۔ {as...: Heb. أکِس بانڈمین سٕنٛدِ کٕننہٕ سۭتۍ}\n43. تُہۍ کٔرِو نہٕ أمِس پٮ۪ٹھ سختی سان حکوٗمت۔ مگر پنہٕ نِس خدایس کھوژُن۔\n44.\\tتُہٕندِس خادمَس تہٕ تُہٕنزِ خادم، یِم تۅہہِ اندۍ پٔکھۍ یِنہٕ وٲلِس کُلِس سٍتـ̡ آسن۔ تِمو منزٕ ہینہٕ نوکر تہٕ نوکرۍ۔\n45.\\tتِمن ہٕندِس شُرِ یِم تۅہہِ منزٕ روزان چھِ، تہٕ تِمن ہٕندِس عیالس سٍتـ̡ یِم تُہٕندِس سرزمینس مَنٛز پٲدٕ سپدان چھِ، تہٕ تِم آسہِ تُہٕندِس ملکَس مَنٛز۔\n46. تہٕ تُہۍ نِیِو تِم پننین شُرین ہٕندِ خٲطرٕ وٲرثہٕ رٔٹِتھ تہٕ یِمن ہٕندِس مَنٛز وَرث حٲصِل کٔرِتھ۔ تِم روزن ہمیشہٕ خٲطرٕ تُہٕندِس غلام مگر پَنٕنـ̡ بٲے اِسرٲیلِس پى۪ٹھ، تێلہِ کٔرِو نہٕ اَکھ أکِس سٍتـ̡ سختی سٍتـ̡ حُکوٗمت کٔرِتھ۔ {تِم...: ہیب۔ تُہۍ کٔرِو تِمن سٍتـ̡ خدمت کٔرِو}\n47.\\tتہٕ یێلہِ کانہہ روزُن وول یا اجنبی تہٕ تُہند بٲے {یُس أمِس سٍتـ̡ روزان چُھ} تہٕ پانس کٕنِتھ اجنبی سٕندِس عیالس سٍتـ̡ کٕنُن: {موم امیر...: ہیب۔ تٔمۍ سُند اَتھٕ حٲصِل کٔرِتھ وغیرہ}\n48.\\tتمہ پتہ ییہ سہ کٕننہٕ پتہٕ ییہ سہ دُبارٕ فدٕ کرنہٕ۔ تٔمۍ سُند اکھ بٲے ہیکہِ أمِس نجات دِتھ:\n49.\\tیا تہٕ تٔمۍ سُند پیٚتٕر یا تٔمۍ سٕندِس پیٚتٕر سُند نیچو ہیکہِ أمِس چھڑٲوِتھ، نتہٕ یُس تہٕ تٔمِس عیالس سٍتـ̡ رشتہٕ دار آسہِ، سُہ ہیکہِ أمِس فدٕ کٔرِتھ۔ یا اگر سُہ قٲبِل آسہِ، سُہ ہیکہِ پانس نجات دِتھ۔\n50.\\tتہٕ سُہ کرِ أمِس سٍتـ̡ حساب یُس أمِس کٕننہٕ آمُت ؤری پیٹھٕ یُس أمِس کٕننہٕ آمُت اوس، تہٕ تٔمۍ سٕندِس کٕنُک قٕمتھ آسہِ ؤری مُطٲبق، یُس أکِس کرایہ دار سٕندِس وقتس مُطٲبق آسہِ۔\n51.\\tاگر وُنہِ تہِ واریاہ ؤری آسہِ، تِمن ہٕندِ مطٲبق دِیہِ سُہ دُبارٕ تِمن پونسہٕ سٍتـ̡ دِنہٕ آمُت یُس أمِس ہیوٚتمُت اوس۔\n52.\\tتہٕ یێلہِ یوبیل کِس ؤریس تام کینہہ ؤری باقٕے روزِ، تیلہِ گژھہِ سُہ أمِس سٍتـ̡ گنزراونہٕ یُن، تہٕ پنہٕ نِس وُہرۍ مُطٲبق دِیہِ سُہ دُبارٕ پننہِ فٲدِیُک قٲمتھ دِنہٕ۔\n53.\\t{تہٕ} سُہ گژھِ أمِس سٍتـ̡ س\n54. تہٕ اگر سُہ یِمن ؤرین مَنٛز نجات دِنہٕ یِیہ، تیلہِ گژھِ سُہ جوبیل ؤریس مَنٛز نیرُن، سُہ تہٕ تٔمۍ سٕندِس شُرِ سٍتـ̡ نیرُن۔ {یمن منز...: یا، یمن ذرائعو سٍتۍ}\n55. میانہِ خٲطرٕ چِھ بنی اسرائیلٕکۍ خادم۔ تِم چھِ میٲنۍ خادم یِم مے مصرٕچ سرزمینہٕ منزٕ نیبر کٔرۍمٕتۍ: بہٕ چُھس خداوند تُہند خدا۔","1. تہٕ تُہۍ بناوِ نہٕ کانہہ بُت تہٕ نہ کٔرِو تُہٕندِس مُجسمس سٍتـ̡ کُنہِ کُنہِ تہِ مجسمہٕ، تہٕ نہ کٔرِو پننِس زمینس مَنٛز کُنہِ تہِ کٔنـ̡ کُنہِ تہِ مجسمہٕ، تِکیازِ بہٕ چُھس خداوند تُہند خدا۔ {کھڑا...: یا، ستون} {تصویر...: یا، شکلہٕ پتھر: Heb. تصویرُک اکھ پتھر}\n2. تہٕ تُہۍ کرو میٲنۍ سبت تہٕ میانہِ مقدس مقامس احترام: بہٕ چُھس خداوند ۔\n3. یێلہِ تُہۍ میانین قونونن مُطٲبق پٔکِو، تہٕ میٲنۍ حُکمن ہُند عمل کٔرِو، تہٕ یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہِ کٔرِو تِمن ہٕندِ\n4. تیلہٕ دِیہ بہٕ ژے مُقرر وقتس پیٹھ روٗد، تہٕ زمینہٕ دِیہِ پنُن پھل تہٕ کھہٕکۍ کُلۍ دِیہِ پنُن مٮ۪و۔\n5. تہٕ تُہٕندِس کُنہِ کھورِ تام واتہِ، تہٕ وُنٹیج واتہِ ووت وُننہٕ کِس وقتس تام، تہٕ تُہۍ گژھِو پنٕنۍ روٹی پوٗرٕ پٲٹھۍ، تہٕ روزِو پنٕنِس سرزمینس مَنٛز محفوٗظ پٲٹھۍ۔\n6. تہٕ بہٕ دِیہٕ زمینس مَنٛز امن، تہٕ تہٕ ژے روزٕ بٔرِتھ تہٕ کانہہ تہِ کرِ نہٕ تُہٕندِس سرزمینس مَنٛز تلوار ژٔٹِتھ۔ {rid: Heb. بند گژھنک وجہ}\n7. تہٕ تُہۍ پَنٕنـ̡ دُشمن ہُند تعاقب کٔرِو، تہٕ تِم گژھن تلوار ہٕندِس سٍتـ̡ تۅہہِ برونہہ کُن پَسنہٕ۔\n8.\\tتہٕ پانژھ ہتھ تہٕ ہتھ ژٔلِتھ تہٕ تُہند دُشمن گژھن تلوار سٍتـ̡ ژٔلِتھ ژٔلِتھ تہٕ تُہند دُشمن گژھن تلوار ہٕندِ سٍتـ̡ ژٔلِتھ ژٔلِتھ تہٕ تُہند دُشمن پۯاوُن تہٕ تُہند دُشمن گژھن تلوار ہٕندِ سٍت\n9. تِکیازِ بہٕ کَرٕ تُہُند احترام، تہٕ بہٕ کَرٕ ژےٚ پھلہٕ دار تہٕ بَڑاوٕ تہٕ ژے سٍتـ̡ پنُن عہد قٲیِم کَرُن۔\n10. تہٕ تُہۍ کٔرِو پرٛون دُکان کھٮ۪وان، تہٕ نٔوِس سٍتـ̡ کٔرِو پرٛون دُکان۔\n11. تہٕ بہٕ کَرٕ پَنُن خیمہ تہٕ میٲنۍ روح کَرٕ نہٕ توے سٍتـ̡ نفرت۔\n12. تہٕ بہٕ پَکُن تہٕ تُہُند خدا بنہٕ تہٕ تُہٕندِ لُکھ بٔنِتھ تہٕ تُہٕندِس لُکہٕ سٍتـ̡ بٔنِتھ تہٕ تُہٕندِ\n13. بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کہِ سرزمینہٕ منزٕ نیبر کڈُن، یُس نہٕ تِہُند غلام بٔنِتھ۔ تہٕ مے پھُٹرٲوۍ چانہِ جودٕکۍ بند تہٕ ژے کھوٚد کھسنہٕ۔\n14. مگر اگر نہٕ ژے میانہِ کتھ بوزو، تہٕ یِم سٲری حُکمن کٔرِو نہٕ۔\n15. تہٕ یێلہِ تہٕ یێلہِ تہٕ یێلہِ تُہۍ میانہِ حکمن ہٕنز حقارت کٔرِو، تێلہِ کٔرِو نہٕ میٲنۍ سارِنٕے حُکمن ہٕندِس سٍتـ̡ ، {مگر} یێلہِ تہٕ ژے میانہِ عہد پھٕٹرٲوِو:\n16.\\tبہٕ تہِ کرٕ ژے سٍتـ̡ یۅہے کٔرِتھ بہٕ کٔرٕ ژے پیٹھ دہشت ، کھپت تہٕ دزُن دزُن، یُس أچھ کھٮ۪یہِ، تہٕ دِلُک غم پٲدٕ کرِ، تہٕ تُہۍ کرٕ پنُن بیٲلِس بیکار، تکیازِ تُہند دُشمن گژھن یہ کھٮ۪ن۔ {اوور: ہیب۔ اَپَن}\n17. تہٕ بہٕ کٔرٕ پنُن بُتھ تہٕ یِم تہٕ یِم تۅہہِ سٍتـ̡ نفرت کران چھِ، تۅہہِ ہٕندِس دُشمن برونہہ کُن مارنہٕ یِن۔ تہٕ ژٔلِو ژٔلِتھ ییٚلہِ نہٕ کانٛہہ تہِ تۄہہِ پَتہٕ پَتہٕ ییہِ۔\n18. تہٕ اگر نہٕ ژے وُنہِ تہِ یِمن سارِنٕے سٍتـ̡ میانہِ کتھ بوزو، تیلہِ دِیہٕ بہٕ ژے پننین گۅنہن ہُند سَتھ گنہٕ سزا۔\n19. تہٕ بہٕ پھُٹراوٕ چانہِ طاقتُک غرور۔ تہٕ بہٕ بناوٕ تُہند جنتُک آسمان، تہٕ تُہٕنٛز زمین پیتلُک پٲٹھۍ۔\n20. تہٕ تُہُند طاقت گژھہِ بیکار خرٕج کرنہٕ، تِکیازِ تُہٕنزِ زمینہِ ہٕندِ دِیہِ نہٕ ہُریر، تہٕ زمینہٕ کُلۍ دِیہِ نہٕ پَنُن پھل دِنہٕ۔\n21. تہٕ اگر تہٕ ژے میانہِ برعکس پکان تہٕ میانہِ کتھ بوزان چھِ۔ بہٕ اَنہٕ ژےٚ گۅنہٕ مُطٲبِق سَتھ گنہٕ زیادٕ آفت۔ {برعکس...: یا، میہ سیتۍ تمام مہم جوئی}\n22.\\tبہٕ سوزٕ ژۅہہ منزٕ جنگلی جانور تہِ، یِم تۅہہِ نِش ژٔٹِتھ تہٕ تُہٕندِس چاروٲے تباہ کٔرِن تہٕ تۅہہِ کٔرِن تعدادس منز کم۔ تہٕ تہنز {تھد} وتہٕ گژھن ویران۔\n23.\\tتہٕ یێلہِ نہٕ ژے یِمو چیزو سٍتـ̡ س�\n24. تیلہٕ بہٕ تہِ چُھس ژےٚ برعکس پکان تہٕ تہٕ دِیہٕ ژےٚ سَتھ لٹہِ پننین گناہن ہُند سزا۔\n25. تہٕ بہٕ اَنہٕ ژےٚ پٮ۪ٹھ اکھ تلوار، یُس میٲنۍ عہد کِس جھگڑُک بدلہٕ نِنہٕ ییہِ: تہٕ ییٚلہِ تُہۍ پَنٕنٮ۪ن شہرن مَنٛز جمع گٔژھِو، بہٕ سوزٕ تۄہہِ مَنٛز وَبا۔ تہٕ یِیہِ دُشمن ہٕندِس اتھس مَنٛز دِنہٕ۔\n26.\\tییلہ میہ چانہِ روٹی ہُند عصا پھُٹراو، دَہ زنانہٕ کرِ تُہند روٹی أکِس اوونس منز، تہٕ تِم دِن تُہند روٹی دُبارٕ وزنس سٍتـ̡ دِنہٕ، تہٕ تُہۍ گژھِو کھٮ۪ن، تہٕ گٔژھِو نہٕ تسلی کٔرِتھ۔\n27. تہٕ یێلہِ نہٕ یێلہِ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ میانہِ کُنہِ سٍتـ̡ بوزُن، بلکہ کٔرِو میانہِ بر\n28. تیلہٕ پَکہٕ بہٕ ژےٚ برعکس تہٕ غصہٕ سٍتـ̡ پَکُن۔ تہٕ بہٕ تہِ کٔرٕ ژےٚ سَتھ لٹہِ پننین گۅنہن خٲطرٕ سزا۔\n29. تہٕ تم کھیٛو پننین نیچوین ہُند ماز تہٕ کورِ ہُند ماز کھیوٚن۔\n30. تہٕ بہٕ کرٕ چانہِ تھدِ جایہِ تباہ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ چانہِ بُتن ہٕندِس لاشس پیٹھ تراوٕ تہٕ میون روح کرِ ژے نفرت۔\n31. تہٕ بہٕ بناوٕ چانۍ شہر برباد، تہٕ چانۍ مقدس گاہٕ ویران کٔرتھ، تہٕ بہٕ کرٕ نہٕ چانہِ مٔدٕر خوشبوہٕ ہٕنٛز خوشبو۔\n32. تہٕ بہٕ اَنِہ زمینہٕ ویران کٔرِتھ، تہٕ تُہند دُشمن یُس اَتھ مَنٛز روزان چھُ، یِم اَتھ مَنٛز روزان چھِ، گژھن حیران۔\n33. تہٕ بہٕ کٔرٕ ژےٚ کافرن مَنٛز پھٔہلِتھ تہٕ تُہٕندِس پَتہٕ تلوار کٔڈِتھ تہٕ تُہٕنز زمین گژھہِ ویران تہٕ تُہٕندِس شہرس گژھہِ برباد۔\n34.\\tتیلہِ روزِ زمینہِ پننہِ سبت دۅہہ، یوتام نہ یہ ویران روزِ، تہٕ تم روزو پننین دشمنن ہٕندِس سرزمینس منز۔ {حتیٰ کہ} تیلہِ گژھہِ زمینہِ آرام تہٕ تسبت دِنہٕ خٲطرٕ لُطف۔\n35.\\tیوتام یہ ویران روزِ، توٚت تام روزِ آرام کرُن۔ تکیازِ یہ اوس نہٕ تہندِس سبت دۅہس منز آرام کٔرِتھ، ییلہ تہۍ اتھ پیٹھ روزان ٲسۍ۔\n36.\\tتہٕ یِمن ہٕندِس دُشمن ہٕندِس سرزمینس مَنٛز یِمن ہٕندِس دِلس مَنٛز یِمن ہٕندِس دِلَس مَنٛز بٔرِتھ چھُس۔ تہٕ لٔٹِتھ پنہٕ ؤتھرٕچ آواز چھِ تِمن ہُند پیچھا کَران۔ تہٕ تِم ژلٕن، یِتھ کٔنۍ تلوار نِش ژلان۔ تہٕ تِم پیٚیہِ ییٚلہِ نہٕ کانٛہہ تہِ پیچھا کرِ۔ {ہلکان: ہیب۔ ڈرایون}\n37.\\tتہٕ تِم گژھن اَکھ أکِس پٲٹھۍ، یِتھٕ پٲٹھۍ تلوار برونہہ کُن آسہِ، ییلہ نہٕ کانہہ تہِ تعاقب کرِ، تہٕ تۅہہِ آسہِ نہٕ پننین دُشمنن برونہہ کُن کھڑا گژھنُک کانہہ طاقت۔\n38. تہٕ تُہۍ گٔژھِو کافرن مَنٛز مارٕ، تہٕ تُہٕندٮ۪ن دُشمنن ہٕنٛز زمین کھیٚیہِ تُہہِ کھٮ۪وان۔\n39. تہٕ یِم تہٕ یِم تۅہہِ ہٕندِس دُشمن ہٕندِس سرزمینس مَنٛز بٔرِتھ روزِ۔ تہٕ پننین مٲلن ہٕندِس بدکارس منز تہِ گژھن تِمن سٍتۍ رٔلِتھ۔\n40. اگر تِم پنٕنـ̡ گناہ تہٕ پننین مٲلن ہٕنزِ بدکٲری ہُند اقرار کرٕن، یُس تِمو میانہِ خلاف گُناہ کورمُت چُھ، تہٕ سُہ تہِ چُھ تِم میانہِ خلاف پٔکۍمٕتۍ۔\n41. تہٕ {یہ} بہٕ تہِ چُھس تِمن ہٕندِس برعکس پکان تہٕ تِمن ہٕندِس دُشمنن ہٕندِس سرزمینس مَنٛز انمُت۔ اگر تِہُند ختنہ نہ کرنہٕ آمُت دِل یِن عاجز کرنہٕ، تہٕ تِم چھِ پننہِ بدکٲری ہُند عذاب قبول کَرُن:\n42. اَمہِ پَتہٕ کَرٕ بہٕ یعقوبس سٍتـ̡ پنُن عہد تہٕ اسحاق سٍتـ̡ پنُن عہد تہٕ ابراہیمس سٍتـ̡ پنُن عہد تہٕ یێلہِ بہٕ یاد۔ تہٕ بہٕ روزٕ زمین یاد۔\n43.\\tزمین تہِ گژھہِ تِمن نِش تراونہٕ، تہٕ تِمن ہٕندِس سبت سٍتـ̡ لُطف روزُن، تہٕ تِم گژھن پننہِ بدکٲری ہُند سزا قبول: کیازِ، تِکیازِ تِمو ٲس میانین فٲصلن حقارت کٔرمٕژ، تہٕ تِمن ہٕندِس روحس ٲس میانین قونونن سٍتـ̡ نفرت۔\n44. تہٕ توتہِ ییلہ تم پننین دشمنن ہٕندِس سرزمینس مَنٛز آسن، بہٕ کٔرٕ نہٕ تِمن کُن نفرت، تہٕ بہٕ کرٕ نہٕ تِمن سٍتـ̡ تِمن سٍتـ̡ تباہ کرنہٕ خٲطرٕ، تہٕ تِمن سٍتـ̡ پنُن عہد پھُٹراوُن، کیازِ بہٕ چُھس خداوند تِہُند خدا۔\n45. مگر بہٕ کرٕ تِہندِ خاطرٕ تِہندِ آباؤ اجدادن ہُند عہد یاد، یُس میہ کافرن ہٕندِس نظرس منز مصر کِس سرزمینہٕ منزٕ نیبر کڈمُت، یُتھ بہٕ ہێکہٕ تِہُند خدا بٔنِتھ: بہٕ چُھس خداوند ۔\n46.\\tیِم چھِ تِم قوانین، فیصلہٕ تہٕ قوانین، یِم خداوند حضرت موسیٰ سٕندِ دٔسۍ کوہ سیناہس مَنٛز تٔمِس تہٕ بنی اسرٲیلِس درمِیان بنوو۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، یێلہِ کانہہ انسان کُنہِ وٲحِد عہد کرِ، تۯێلہِ گژھن تُہٕندِ اندازٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ آسن۔\n3.\\tتہٕ تُہند تخمینہٕ گژھہِ وُہ وُہُر وٲنسہِ تام شیٹھ وُہُر وٲنسہِ تام تہٕ تُہند تخمینہٕ گژھہِ پنژاہ شیکل رۄپہٕ۔\n4.\\tاگر یہ زنانہ آسہِ، تیلہِ گژھہِ تہند اندازہ ترہ شیکل۔\n5.\\tاگر یہ پانژو ؤری وٲنسہِ پیٹھہ وُہن ؤرین تام آسہِ، تیلہِ گژھہِ تہند اندازہ مردس وُہن شیکلن تہ زنانہِ ہندِ خاطرہ داہ شیکل۔\n6.\\tاگر یہ اکہ ریتہ پیٹھہ پانژن ؤرین تام آسہِ، تیلہِ گژھہِ تۅہہِ ہند تخمینہٕ مردس پانژھ شیکل رۅپہ تہ زنانہِ ہندِ خاطرہ گژھہِ تۅہہ تریہ شیکل رۅپھ۔\n7. تہٕ اگر {یہ} شیٹھ ؤری وٲنسہٕ تہٕ امہٕ کھوتہٕ زیادٕ وٲنسہٕ آسہٕ؛ اگر یہ مرد آسہِ، تیلہِ گژھہِ تہند اندازہ پندہ شیکل تہ زنانہِ ہندِ خاطرہ داہ شیکل۔\n8. مگر اگر سُہ تُہٕندِس اندازس کھۅتہٕ زیادٕ غریب آسہِ، تیلہِ گژھہِ سُہ پادٕرۍ سٕندِس برونہہ کُن پیش، تہٕ پادٕرۍ کرِ أمِس قدر۔ تٔمۍ سٕنزِ قٲبلِیت مُطٲبق یُس عہد کرُن پادٕرۍ أمِس قدر کرُن۔\n9. تہٕ یێلہِ کانہہ جانور آسہِ، یێمہِ سٍتـ̡ انسان خداوند سٕندِ خٲطرٕ نذرانہ دِوان چُھ، سُہ چُھ یُس {کانہہ انسان} خداوند سٕندِ خٲطرٕ دِوان چُھ، سُہ گژھہِ پاک آسُن۔\n10. سُہ کرِ نہٕ اتھ بدلاوُن، تہٕ نہ بدلاوُن، بُرٕ بدلہٕ نیُک بدلاوُن، تہٕ اگر سُہ درندٕ بدلاوُن تہٕ بدلاوُن آسہِ مُقدس۔\n11.\\tتہٕ یێلہِ کانہہ ناپاک جانور آسہِ، یێمہِ سٍتـ̡ تِم خداوند سٕندِ خٲطرٕ قربانی دِوان آسہِ، تیلہِ گژھہِ سُہ درندہ پادٕرِس برونہہ کُن پیش۔\n12.\\tتہٕ پادٕرۍ گژھہِ امِچ قدر کرُن، چاہے سُہ اصل آسہِ یا خراب: یِتھٕ پٲٹھـ̡ تُہۍ چُھہ اتھ قدر دِوان، یُس پادٕرۍ چُھ، تِتھے پٲٹھـ̡ آسہِ۔ {as...: Heb. تُہٕندِ اندازٕ مُطٲبِق اے پادٕرۍ بیترِ}\n13.\\tمگر اگر سُہ اتھ کُنہِ تہِ چھُ رٔٹِتھ دِیہِ، تیلہِ کرِ سُہ تُہٕندِس اندازس مَنٛز پٲنژِم حصہٕ شٲمِل کرُن۔\n14. تہٕ یێلہِ کانہہ انسان پَنُن گرٕ خداوند سٕندِ خٲطرٕ پاک بَناوُن، تێلہِ کرِ پادٕرۍ أمِس تخمینہٕ کٔرِتھ، چاہے سُہ اصل آسہِ یا خراب، یێلہِ زن پادٕرۍ أمِس تخمینہٕ کرِ، تِتھے پٲٹھـ̡ گژھہِ یہِ کھڑا روزُن۔\n15.\\tیێلہِ یێلہِ یُس یہِ پاک کٔرِتھ سُہ کرِ پنُن گرٕ چھُ، تێلہِ کرِ سُہ تُہندِ اندازٕ کِس پٲنژِم حصہٕ تہٕ سُہ گژھہِ تٔمِس سٍتـ̡ شٲمِل کرنہٕ۔\n16. تہٕ یێلہِ کانہہ شخٕص پننہِ مَضموٗن ہُند کُنہِ حِصہٕ خداوند سٕندِ خٲطرٕ پاک کرِ، تیلہِ گژھہِ تُہند تخمینہٕ امہِ کِس بیٲلہِ مُطٲبق آسُن: بارلی بیٲلِس ہُند مۅل گژھہِ پنژاہ شیکل رۄپہٕ۔ {an...: یا، اکھ ہومر سٕنز زمین، وغیرہ}\n17.\\tاگر سُہ جوبیل ؤری پیٹھٕ پنُن کھیت پاک کرِ، تُہندِ اندازٕ مُطٲبق گژھہِ یہِ کھڑا روزُن۔\n18. مگر اگر سُہ جوبیل پتہٕ پنُن کھیت پاک کرِ، تیلہِ گژھہِ پادٕرۍ أمِس باقٕے ؤرین مُطٲبق پونسہٕ شمار کرُن، یوبیل ؤری تام تہِ، تہٕ یہِ گژھہِ تُہندِ اندازٕ نِش کم کرنہٕ۔\n19.\\tیێلہِ یێلہِ یُس کھیت پاک کٔرِتھ آسہِ سُہ کُنہِ تہِ پٲٹھـ̡ اتھ سٍتـ̡ نجات دِنہٕ، تیلہِ کرِ سُہ تُہٕندِس اندازٕ کِس پٲنژِم حِصہٕ اتھ سٍتـ̡ شٲمل کرُن، تہٕ أمِس گژھہِ یقین دِنہٕ۔\n20.\\tتہٕ اگر سُہ کھیت کٔرِتھ نِیہ، یا اگر تٔمۍ کھیت بییِس انسانس کٕنِتھ آسہِ، تیلہِ گژھہِ نہٕ یہِ چھُنہٕ دِنہٕ یِنہٕ۔\n21. مگر کھیت ییلہ یہ جوبیلس مَنٛز نیرِ، خداوند سٕندِ خٲطرٕ مقدس آسُن، یُس میدانس وقف آسہِ۔ امیک قبضہ گژھہِ پادٕرۍ سُند۔\n22. تہٕ یێلہِ {کٲنسہِ} چُھہ خداوند سٕندِ خٲطرٕ سُہ کھیت پاک کٔرِتھ یُس تٔمۍ ہیوٚتمُت آسہِ، یُس نہٕ تٔمۍ سٕندِس مِلکہٕ کِس کھہَس مَنٛز آسہِ۔\n23.\\tتیلہِ کرِ پادٕرۍ تُہٕندِس اندازس مۅکھہٕ تہٕ تُہٕندِس اندازس سٍتـ̡ یوبیل کِس ؤریس تام، تہٕ سُہ دِیہِ تۅہہِ ہُند تخمینہٕ، یُس خداوند سٕندِ خٲطرٕ اکھ مقدس چیز آسہِ۔\n24.\\tجوبیل کس ؤریس منز گژھہِ کھیت تٔمِس نِش واپس، یٔمِس سٍتـ̡ یہِ ہیوٚتمُت آسہِ، {حتیٰ کہ} تٔمِس نِش یٔمِس زمینُک قبضہ آسہِ۔\n25.\\tتہٕ تُہند سارِنٕے تخمینہٕ گژھہِ مقدس مقامہٕ کِس شیکل مطٲبق آسُن: وُہ گیرہ آسہِ شیکل۔\n26. صرف درندن ہُند گۅڈنچہ لٹہِ، یُس خداوند سُند گۅڈنچہ لٹہِ آسُن، کانہہ تہِ انسان کرِ نہٕ اتھ پاکیزہ۔ چاہے {یہ} آسہِ، یا کۅکر: یہ {چُھ} رب سُند۔ {فرسٹلنگ آف: ہیب۔ فرسٹ بورن وغیرہ}\n27.\\tاگر یہ کُنہِ ناپاک جانور سُند آسہِ، تیلہِ گژھہِ سُہ تُہندِ اندازٕ مُطٲبق چھُ یہِ آزاد کٔرِتھ، تہٕ اَتھ مَنٛز کرِ پونژم حصہٕ شٲمِل: یا اگر نہٕ یہِ چھُنہٕ چھُ، تیلہِ گژھہِ یہِ تُہندِ اندازٕ مُطٲبق کٕننہٕ یُن۔\n28.\\tکُنہِ تہِ کُنہِ چیزس باوجود، یُس انسان تہٕ جانور تہٕ پننہِ ملکیت ہٕندِس میدانس سٍتـ̡ خداوند سٕندِ خٲطرٕ وقف کرُن، سُہ گژھِ کٕننہٕ یا چھُ فدٕ کرنہٕ یُن: پرٮ۪تھ کانہہ چیز چُھہ خداوند سٕندِ خٲطرٕ مقدس آسان۔\n29.\\tکانہہ تہِ عقیدت مند یُس انسانس سٍتـ̡ وقف آسہِ، یُس یُس انسانس سٍتـ̡ وقف آسہِ، گژھہِ نجات دِنہٕ۔ {مگر} یِیہِ یٔقیٖنی طور مارنہٕ۔\n30. تہٕ زمینُک سورُے حصہٕ، {چاہے}زمینہٕ کِس بیٲلِس منز، {یا} کُلِس مٮ۪وُک، {چُھ} خداوند سُند: {یہ} چُھ خداوند سٕندِ خٲطرٕ پاک۔\n31.\\tتہٕ اگر کانہہ انسان پنہٕ نِس دسِس حصس منز کُنہِ تہِ کُنہِ تہِ کٔرِتھ تہٕ سُہ کرِ اَتھ مَنٛز پوٗنٛژِم حصہٕ شٲمِل۔\n32.\\tتہٕ کھورِ ہٕندِس دٔہِس متعلق، یُس تہِ لورِ تل نیران چُھ، دٔہِم آسہِ خداوند سٕندِ خٲطرٕ پاک۔\n33.\\tسُہ گژھِ نہٕ ژھانڈُن زِ یہِ چھا اصل یا خراب، تہٕ نہ گژھِ سُہ بدلاوُن، تہٕ اگر سُہ یہِ بدلاوُن تہٕ تَمہِ سٍتـ̡ بدلاوُن دۅشوے آسہِ پاک۔ یہِ گژھِ نہٕ نجات دِنہٕ۔\n34. یِم چھِ تِم حُکُم، یِم خداوند موسیٰ سٕندِس کُنہِ سیناہس مَنٛز بنی اسرائیلہٕ خٲطرٕ حُکُم دِیُت۔"];
